window.__D("text/maamarei-admur-haemtzai/c005",{"p":[[1900420195,"מים דאורייתא כו' וכתי' כל אמרת אלוה צרופה כו' אל תוסיף כו'<sup data-n=\"777\">248</sup> ונק' חכמה ברורה שכבר הובררה בכח החכ' הקדומה שבעצמות א\"ס ממש דלתבונתו אין מספר<sup data-n=\"778\">249</sup> כו', וע\"כ נק' התורה שלמעלה משל הקדמוני<sup data-n=\"779\">250</sup> כו' וזהו כמשל חכם גדול מאד שבכח חכמתו העמוקה ביותר בירור וחידוש דבר שכל וחכמה לאמיתתו בתכלית שהוא בלתי נטי' ימין ושמאל כפי שעולה בפנימית ועצמות כח חכמתו שהוא ע\"פ עצמות הרצון והתענוג שכל עצמו נמשך ומלובש בזה, כדוגמת משלי שלמה שהן ע\"פ עצם עומק החכמה הלבושים בדברי משל כו', או שידבר דבר החכמה באותיות וצירופים מכוונים שיעלו ע\"פ נקודת עומק החכמה שבעצמותו ממש, והעיקר במה שיביא אותה החכמה הברורה בציווי המעשה לעשות כך וכך בדקדוק מכוון ע\"פ שכל וחכמה זו כו', כמו שיצוה האב החכם לבנו שילך בדרכים ומנהגים טובים וישרים כפי שעלה ברצונו וחכמתו העצמי' והפנימי' שכבר הוברר אצלו בלי נטי' ימין ושמאל כלל שגנוז בהם כל עומק של החכמה והרצון העצמי בבחי' היושר והמיצוע במזיגה נכונה לא יוסיף ולא יגרע שלא יצא מתמצית אמיתי' הבירור שהי' לו בזה מכבר לעצמו הכל במדה ומשקל כו' וד\"ל.\n<b>וכך</b> הוא בענין תורה של מעלה שיצאה מן ההעלם דעצמות החכ' הקדומה בבחי' קו המדה איך יהי' אופן הרצה\"ע במצות העליונות שהן פנימית רצון בבחי' התכללות דחו\"ג באופן דיחו\"ע באו\"כ ואו\"מ ואו\"פ בתורה דאצי' לאכללא שמאלא בימינא כו', הכל במדה ושיעור ע\"פ הבירור דחכה\"ק שכבר הוברר וכך נמשך בצירופי אותיות התורה בדקדוק מכוון לא יוסיף כו', והן המצות שבתושב\"כ אע\"פ שנאמרו בכללות אבל הם ע\"פ הבירור דח\"ע הקדומה בהתכללות דשם מ\"ה דחכ' דתיקון כמ\"ש מי מדד בשעלו כו' וכתיב אז ראה ויספרה שנק' ספר הכינה וגם חקרה כו', והיינו שהתורה בבחי' ציור דאדם כמ\"ש זאת תורת האדם<sup data-n=\"780\">251</sup> כו' שהוא בחי' מ\"ה דחכ' דתיקון בהתכללות דאו\"כ גם בחיצוני' שהן אברים שהן המצות שנק' רמ\"ח אברים דמלכא כידוע<sup data-n=\"781\">252</sup>, וכנ\"ל בענין תתן אמת ליעקב שהתורה נק' אמת שהוא בקו האמצעי דת\"ת שכלול מב' הקוין דחו\"ג במזיגה נכונה ע\"פ הבירור דח\"ע בלי נטי' ימין ושמאל שזהו בחי' היושר כמ\"ש כי ישרים דרכי ה'<sup data-n=\"782\">253</sup> כו' וע\"כ נק' ספר הישר<sup data-n=\"783\">254</sup>.",[["777","248","<b>מי מדד. . כל אמרת אלוה צרופה כו' אל תוסיף כו'</b>: ישעי' מ, יב. משלי ל, ה-ו."],["778","249","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."],["779","250","<b>נק' התורה. . משל הקדמוני</b>: ראה פירש\"י: משפטים כא, יג. שמואל-א כד, יג. מכות י, ב [ד\"ה והאלקים]. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שמו. וש\"נ."],["780","251","<b>זאת תורת האדם</b>: ראה לעיל ח\"א ע' קע. וש\"נ."],["781","252","<b>רמ\"ח אברים דמלכא כידוע</b>: ראה תקוני זהר ת\"ל (עד, סע\"א). זח\"א קע, ב. זח\"ג קיח, א. זח\"ג קכב, ב."],["782","253","<b>כי ישרים דרכי ה'</b>: הושע יד, י."],["783","254","<b>ספר הישר</b>: ע\"פ יהושע י, יג. וראה ע\"ז כה, רע\"א. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ס\"ע תתנא."]]],[1900420196,"<b>אך</b> כ\"ז הוא בבחי' חכמה דתורה דאצי' בבחי' שם מ\"ה דתיקון כמו שהיא למעלה בתוה\"ק שנק' תורת הוי' תורת האדם העליון וכן מצות הוי' שנק' מצות כענין ה' מניח תפילין וכה\"ג כידוע, והוא הגנוז ומלובש באותיות דתושב\"כ כנ\"ל, אמנם עיקר שלימות הבירור לבירור זה עצמו דח\"ע דתורה ש\"מ הוא כאשר ירדה התורה מאצי' לבריאה עד סוף עולם העשי' בעוה\"ז הגשמי שלנו שנתלבשה בדברים גשמי' בנוגה דעשי' בבירור דטו\"ר הגשמי' שנפל למטה ממש להבדיל בין טמא לטהור כו' ולתקן ולברר לבחי' חושך דק\"נ ע\"י בחי' עיון ודיוק דתושבע\"פ שנק' עמל תורה זהו בחי' בירור שני שמברר ומאמת לבירור ואמת דתורה של מעלה הנ\"ל, והוא בחי' בירורים דאו\"ח דשם ב\"ן דמל' שעולה למעלה מבחי' שם מ\"ה דא\"ח עט\"ב ונקבה תסובב גבר משום דבינה יתירה ניתנה באשה יותר מבאיש כנ\"ל. ויובן זה עד\"מ כאשר החכם הגדול שהמציא איזה דבר חכמה עמוקה בכח הבירור שבעצם כח שכלו רוצה לידע בעצמו אם אור החכמה זו ברורה בתכלית האמת אע\"פ שכבר הובררה אצלו בכח הבירור שבכח עצמו' עומק חכמתו, הנה יביא הדבר חכ' זאת בנסיון במעשה דבר מה שאם יעלה ויצליח דבר מעשה זו כמו שהוא ע\"פ חכמה זו אז ידע ויוברר אמיתתה וכמ\"ש אין חכם כבעל הנסיון כידוע<sup data-n=\"784\">255</sup>, שזהו כמו המצרף שמשימים בו כסף לצרף אותו שיוברר בו בתכלית כמ\"ש מצרף לכסף, כך יש מצרף לחכמה<sup data-n=\"785\">256</sup> לברר וללבן החכמה אם היא לאמיתי' בתכלית או שיתנהג באיזה דבר מה שיהי' ע\"פ אותה החכמה אם יצליח ויהי' מכוון היטיב כמו שהוא לפי אופן חכמה זו אז יבורר לו שהיא אמת, וכמו האב שמצוה לבנו להתנהג בדרכים ומעשים שהם עולים ע\"פ כח הבירור שבחכ' העמוקה אם הדרכי' ומעשים הן שבאו לידי מעשה בפו\"מ והם מצליחים ומכוונים בטוב וישר לפי אופן החכמה דוקא אז נשלם שלימות דחכ' זו בשלימות אמיתי יותר מכמו שהיתה אצלו בבירור בכח החכמה שבעצמו' בתחלתה כו' וד\"ל. והעיקר לשלימות דחכמה הוא כאשר יכול בחכמה זו להמציא טרף לנפשו בריוח, כמו בכלי אומנות שאע\"פ שלמד היטב חכמת אומנות זו העיקר בשלימות של חכמה זו כאשר הצליח במלאכתו בפו\"מ להוציא מזה ריוח הון יקר כו', כמו כאשר בכלי אומנות זו יעשה כלים יקרים ולתקן כל דבר המקולקל ביותר להעלותם בעילוי היותר טוב ויקר כמו לעשות ולתקן אבנים טובות ויקרות וכה\"ג בכל עושר והון שיגיע לו מיגיע כפיו בחכ' זו כו', שז\"ש והחכמה תחי' בעלי'<sup data-n=\"786\">257</sup> כו' בעלי' דחכמה כאשר חכמתו עמדה לו למצוא טרף לנפשו להרויח הון רב או לתקן דבר המקולקל כו' שבזה דוקא נשלם שלימות האמיתי לחכ' שבירר כבר. וכן הענין בהשפעת חכמה זו למקבל ששם הצליחה ועשה פרי",[["784","255","<b>אין חכם כבעל הנסיון כידוע</b>: לשון העקידה פ' נח שי\"ד [ד\"ה הקדמה השלישית]. ומובא בכ\"מ בדא\"ח — ראה לעיל ח\"א ע' פב. וש\"נ."],["785","256","<b>מצרף לכסף כך יש מצרף לחכמה</b>: משלי יז, ג. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' שה. ח\"ב ע' תקעח. ח\"ג ע' תתקעח. ובהמ\"מ שם."],["786","257","<b>והחכ' תחי' בעלי'</b>: קהלת ז, יב."]]],[1900420197,"תולדות, כזורע קב ומוציא כמה כורים וכזריעת טפה ונולד ולד שלם לפי שבבואו למקבל דוקא הובררו בירור שני שתברר לבירור הראשון להוסיף ולהתגדל האור בכפלי כפליים כו' וד\"ל.\n[לא] <b>ובכל</b> דוגמא זו יובן הנמשל באור שפע דח\"ע דתוה\"ק שבבחי' או\"י כאשר ירדה למטה במקבל שהיא תורה הנגלית לנו בעה\"ד טו\"ר להיות בירור שני שיצרף צירוף אמיתי לבירור דח\"ע ולהוסיף בה אור גדול בכפלי כפליים, כי עי\"ז נשלם עיקר שלימותה, והיינו ע\"י העיון ודיוק בפלפול דקושיות ותירוצים בחכ' דמקבל שהן חכמי ישראל לברר וללבן הדבר היטב כמו בנסיון בפו\"מ או כמו מצרף לכסף כו' לפי שזה העיון הוא במקבל התורה שזהו בהתלבשות התורה בעה\"ד טו\"ר שהוא בנוגה דעשי' שיש מסתיר ומחשיך האור כו' שהן הקושיות מסט' דקליפה והבירור בזה זהו בירור החושך לאור שאז יבורר האור יותר לאמיתתו ויצליח לעשות פרי יותר מעיקר אור הזרוע בתורה של מעלה לפי שבזה נשלם עיקר שלימות דח\"ע הקדומה מטעם הנ\"ל, וכמשל הנ\"ל בשלימות דחכ' בנסיון או בדרכים ומעשים או בכלי אומנות להרויח הון ולתקן דבר המקולקל שהן רפ\"ח ניצוצים שנפלו בק\"נ שיבורר מן החושך לאור כו', וזהו שנק' עמל תורה כמו העמל בעבודה מלאכה שמצטער ביגיעה רבה לתקן המקולקל בחרישה ותיקון האדמה וכן באומנות ביגיע כפיו כו', אך כשחכמתו עמדה לו מוצא בה ריוח הון רב, כך הוא בחי' הבירורים דח\"ת דעמל תורה ועבודת המצות בפו\"מ שיצליח ויעשה פרי למעלה באצילות בתוס' גדול ולהוסיף אור התענוג גדול בעצמות השעשועי' הרבה יותר מתענוג ושעשועי' שהי' בבירור דח\"ע הקדומה בבחי' או\"י כו', וכמו שרואים בחוש בעמל ויגיעה דתורה בעיון ודיוק בפלפול כל שמצטער יותר זמן ולא יעמוד על אמיתי' הדבר, יותר יתענג וישמח אח\"כ כאשר יצא לאור האמיתי לתכלית האמת בדין והלכה זו מן החושך וההעלם דקושיות כו' שהי' נבוך ומבולבל בהן עד מיצוי הנפש, ששמחה זאת ועונג זה גדולה הרבה יותר משמחה ועונג שהי' לו בהמצאת החכ' ממקורה בתחלה אע\"פ שהי' ברורה לו מאד כו', כמ\"ש בספרי המחקר שאין תענוג ושמחה יותר מהתרת הספיקות<sup data-n=\"787\">258</sup> כו', וכה\"ג יובן בעמל תורה בפלפול דתלמוד בבלי שע\"ז א' במחשכים הושיבני<sup data-n=\"788\">259</sup> כו' כידוע שע\"כ א' שהעוסק בתלמוד שהוא הפלפול אין לך מדה גדולה הימנה<sup data-n=\"789\">260</sup> לפי שביתרון האור מן החושך בהיתר הספיקות והבלבול יתוסף האור האמיתי דח\"ע בלי מדה וגבול כלל שהוא העומק והעילוי האמיתי באמיתתה של חכמה שלא",[["787","258","<b>בספרי המחקר שאין תענוג ושמחה יותר מהתרת הספיקות</b>: מובא בשו\"ת הרמ\"א ס\"ה בתחילתו. ובס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קי — בשם הרמב\"ם. סה\"מ תרל\"ו ח\"א ע' א' וח\"ב ע' שפא — בשם החכם."],["788","259","<b>במחשכים הושיבני</b>: סנהד' כד, א."],["789","260","<b>שהעוסק בתלמוד. . מדה גדולה הימנה</b>: ב\"מ לג, א. ראה לעיל אות כ\"ט, קרוב לסופו."]]],[1900420198,"יגיע לזה כל מדה ושיעור דחכ' הקדומה שיש בכח הח\"ע מקודם, וכמ\"ש ביום ההוא יצאו מ\"ח<sup data-n=\"790\">261</sup> מירושלים חציים אל הים הקדמוני כמשל המים שמתבררים בעפר שיצאו נקיים יותר ונק' מים חיים ממש ויעלו בכח גדול למעלה בתוקף עד אין שיעור למעלה מאד נעלה יותר ממקור הראשון דח\"ע הקדומה כו' וד\"ל. וזהו בחי' מקיף דח\"ת דאו\"ח שמבחי' בירורים דעיון מעמל תורה הנ\"ל (שהן חידושי ההלכות שמתחדשים לאין שיעור ע\"י הפלפול כמ\"ש ועלמות אין מספר<sup data-n=\"791\">262</sup> כו') שהוא מפני דחיקת האו\"פ בכלי שלא יכילנו יוצא ובוקע בבחי' שערות דאו\"ח דנוק' נק' חופה דמקבל שהוא תושבע\"פ שעולה בבחי' או\"ח לקדמותו ממש למקור השעשועי' העצמי' שהוא העדן עצמו שלמעלה ממקיף דאו\"י דחופה דחתן שהאיר בח\"ע דתוה\"ק כו'. וז\"ש משמח חתן דבחי' חופה דאו\"י דתושב\"כ עם הכלה בשביל הכלה דתושבע\"פ שהוא חופה דמקבל שנק' כבוד התחתון שבא ועולה מן המיצר אל המרחב דעצמות ממש (אבל במ\"ת שהי' בבחי' או\"י בדבור דתושב\"כ למקבל והעלאה דאו\"ח לא הי' רק במ\"ש נעשה ולא שנתברר בפו\"מ ממש עדיין עד ימוהמ\"ש ע\"ז א' משמח חו\"כ (וזהו ב' חצאי כדורים שהמה מתרחבים באמצעו שז\"ס למהוי אחד באחד ממש כמ\"ש במ\"א<sup data-n=\"792\">263</sup>).\n[לב] <b>ובכ\"ז</b><sup data-n=\"793\">264</sup> יובן הטעם דבתושבע\"פ מצות העיון עיקר יותר מבקריאה בדבור כנ\"ל אע\"פ שצ\"ל משנה בדבור קודם לעיון התלמוד כמ\"ש ליגמר אינש והדר ליסבר עכ\"ז העיקר הוא בעיון ודיוק בפלפול שבתלמוד שנק' שימוש ת\"ח שגדולה שימושה יותר מלימודה<sup data-n=\"794\">265</sup>, וכמ\"ש במשנה מדה ונוטלי' עלי' שכר התלמוד אין לך כו'. ולפי הנ\"ל בטעם מצות קריאה בדיבור שבתושב\"כ שהוא עיקר יותר לפי שנתחב\"ס הי' ראוי להיות כן גם בתושבע\"פ שיהי' קריאה בדיבור וגירסא בשונה הלכות יותר עיקר מן העיון כו' דנתחב\"ס ולמה אין העדן עצמו בא רק למחכה לו שבעיון ודיוק דתושבע\"פ כו'. אך הנה באמת מ\"ש משמח חתן עם הכלה מדבר לע\"ל כמ\"ש מהרה ישמע כו' קול חתן וקול כלה הזכיר ששון ושמחה, וזהו בבחי' ח\"ת דתושבע\"פ דוקא שיש בה ג\"כ בחי' חו\"כ חכ' בראש וחכמה בסוף, והיינו שישראל נק' חתן והתורה נק' כלה כמ\"ש תורה צוה לנו משה שזהו תושבע\"פ מאורסה, והוא כאשר ניתנה א\"י לירושה נק' התורה מאורסה, שזהו הטעם שישראל הם המבררים לרפ\"ח כו' בקיום המצות בפו\"מ, ושלימות הבירורים דח\"ת דעמל תורה הנ\"ל יהי' בימוהמ\"ש דכתי' בי' ישכיל עבדי כו' אבל במ\"ת התורה נק' חתן וכנ\"י נק'",[["790","261","<b>ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ד. ראה בארוכה לעיל אות כ\"א ואילך."],["791","262","<b>ועלמות אין מספר</b>: שה\"ש ו, ח."],["792","263","<b>ב' חצאי כדורים. . למהוי אחד באחד ממש כמ\"ש במ\"א</b>: ראה ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' שנז. במדבר ח\"ב ע' תרצו-ז. לעיל ח\"א ע' יד. להלן ד\"ה קול מצהלות סוף אות ל'."],["793","264","<b>[לב] ובכ\"ז יובן</b>: ע\"כ נמצא תח\"י מאמר בגוכי\"ק, ומכאן ואילך נדפס ע\"פ כת\"י מעתיק."],["794","265","<b>ליגמר אינש והדר ליסבר. . גדולה שימושה יותר מלימודה</b>: שבת סג, א. ברכות ז, ב."]]],[1900420199,"כלה להיות שהי' בבחי' או\"י דתורה שלמעלה שנמשך בדיבור למקבל כנ\"ל. והענין הוא, דודאי כח זה שיש במקבל שהן חכמי ישראל בעיון ועמל תורה לחדש דינים והלכות בתוס' וריבוי גדול ביותר ממה שמקבל בתושב\"כ כר\"ע שהי' דורש על כל קוץ תילי תילים של הלכות זהו מצד בחי' כח דאו\"ח שגדול יותר מאו\"י המשפיע, כאשה שתזריע במ\"נ להוליד ולד שלם וכח הצומח שבארץ שיש בו כח יתירה להצמיח ולגדול הזורע בה בכפלי כפליים כו' שנק' חידוש גמור מאין ליש יותר מחידוש של אור השפע דאור הזרוע ממקורו מאין, וראי' ממים שיורדי' מגבוה לנמוך שאינם עולים רק למקורם ולא למעלה ממנו אבל מים שמתחדשים בארץ כחם חזק לעלות הרבה יותר למעלה לפי שנק' מים חיים בחידוש מאין ממש כו', וכן בכל משפיע ומקבל דאו\"י ואו\"ח דיש כח במקבל יותר מבמשפיע כו' לפי שניתן כח בסוף יותר מבתחלה, שהרי הארץ בחי' דומם סוף הכל יש בה כח החידוש יש מאין לאין שיעור יותר מן המשפיע כו' כמ\"ש במ\"א בטעם דארץ קדמה לשמים וכמ\"ש והארץ אזכור שהרי הכל הי' מן העפר אפי' החי והמדבר כמ\"ש תוצא הארץ<sup data-n=\"795\">266</sup> כו'. וכך יובן בענין תושב\"כ ושבע\"פ, דבחי' או\"י דתושב\"כ ח\"ע שבה נק' מ\"ע ונתחב\"ס וסוב\"ת ולא יעלה יותר ממקורם, אבל בתושבע\"פ שנתקבל בכנ\"י שנק' ארץ חפץ שם נק' מים חיים שהוא חידוש גמור מאין דעצמות הא\"ס שלמעלה מחידוש דתושב\"כ אע\"פ שנמשך מאין דחה\"ק שזהו רק כמחדש שכל ע\"פ כח חכמתו העצמי' לבד כנ\"ל [ב]תושבע\"פ שנק' כלי אומנות או בזריעה בארץ שיצמיח בחידוש גמור כמפרנס א\"ע בעבודה ויגיע כפיו בארץ כנ\"ל, ע\"כ יצא מים חיים לים הקדמוני למעלה הרבה מהם, וזהו מצות העיון דתושבע\"פ שהוא לחדש ההלכות ע\"י פלפול בתלמוד שנק' חידוש דאו\"ח שאין מדה גדולה הימנו מטעם זה, אע\"פ שגם בתושבע\"פ אמרו בכל יום יהיו בעיניך כחדשים שאינו רק כמחדש דבר שכבר נאמר כמו שהי' במ\"ת בחידוש דח\"ע ממקיף דשעשועי' שבתוה\"ק בבחי' או\"י, אבל חידוש זה דפלפול מן החושך לאור בבחי' או\"ח יש בו כח תחלת כל התחלות שהוא העדן עצמו שלמעלה גם ממקיף דשעשועי' דתוה\"ק כנ\"ל וד\"ל (וזהו בראשית בשביל התורה<sup data-n=\"796\">267</sup> הקדומה שנקרא ראשית בבחי' או\"י ובשביל ישראל שנק' ראשי' שנק' או\"ח דח\"ת דתושבע\"פ שמצמיח מלמטה למעלה בלי שיעור למעלה ונק' ראשית תבואתו שלא הי' זה במ\"ת כנ\"ל). וזהו שבמ\"ת דאו\"ח נק' ישראל חתן בעיון ודיוק בפלפול שמתחדשים בתורה, אבל במה מתחדשים בתורה שהיא דבר ה' שניתן למשה בע\"פ שנק' מאורסה, והוא הלכה עצמה נק' כלה אותיות הלכה<sup data-n=\"797\">268</sup>, והוא בחי' חכמה שבסוף שבתושבע\"פ",[["795","266","<b>במ\"א בטעם דארץ קדמה לשמים. . והארץ אזכור. . הכל הי' מן העפר. . תוצא הארץ</b>: חגיגה יב, א [וראה לעיל אות כ\"ח]. ראה לעיל ד\"ה משמח חו\"כ [לפני פיסקא ”והנה יש עוד\"]. וש\"נ. בחוקותי כו, מב. קהלת ג, כ. בראשית א, כד."],["796","267","<b>בראשית בשביל התורה</b>: רש\"י ר\"פ בראשית."],["797","268","<b>כלה אותיות הלכה</b>: ראה לעיל סוף אות ט'. וש\"נ."]]],[1900420200,"שמקבל מחכ' שבראש דחכמי ישראל כמו גוף הצמיחה שצומח מכח הצומח שבארץ כו', ואע\"פ שנתחב\"ס זהו בבחי' או\"י שיורד מגבוה לנמוך, אבל באו\"ח נהפוך הוא דנסב\"ת, ע\"כ עיקר מצות קריאה בתושב\"כ ועיקר מצות העיון בתושבע\"פ כנ\"ל, וזהו מאורשה שאינה כורתת ברית<sup data-n=\"798\">269</sup> אלא כו', ועכ\"ז משמח חתן עם הכלה בשביל הכלה, דהלכה זו עיקר החידוש הבא מעצמות התענוג הפשוט שנק' עדן, וזהו ב' מדריגות דתושב\"כ ושבע\"פ דבבחי' או\"י נק' התורה כלה והקב\"ה נק' חתן שהיתה אצלו שעשועים וכמ\"ש משחקת לפניו בכל עת<sup data-n=\"799\">270</sup> (ואח\"כ ירדה להשפיע לישראל במ\"ת) ובבחי' או\"ח נק' ישראל חתן ותורה נק' כלה. וז\"ש משחקת בתבל ארצו ארץ החיים ארץ חפץ שהן כנ\"י שזהו גבורות דח\"ע וגבורות דח\"ת ב\"פ גבורה גימט' תבל<sup data-n=\"800\">271</sup> כו'. וזהו עוז והדר לבושה שהוא לאחר שלימות הבירור דאו\"ח הנ\"ל שעז\"א אשת חיל<sup data-n=\"801\">272</sup> כו' ואז ותשחק ליום כו', וכמו משחקת בתבל כו' ותשחק ליום אחרון שזהו צחוק שיעשה עם לויתן ושור הבר שהוא שלימות הבירורים דרפ\"ח ע\"י ח\"ת שיתחברו מ\"ת עם [מ\"ע] דלויתן זה יצרת כו' תושב\"כ מתענוג דאו\"י דח\"ע ושור הבר באו\"ח (וכמ\"ש ורב תבואות<sup data-n=\"802\">273</sup> כו'). וזהו מהרה ישמע קול כלה בבירור דאו\"ח בהלכות שבזה יש יתרון מעלה מאירוסין דמ\"ת שבשתיקה מתקדשת כמ\"ש במ\"א<sup data-n=\"803\">274</sup>.\n<b>וז\"ש</b> אשר ברא ששון ושמחה, דעכשיו ששון בדכורא ושמחה בנוק', ולע\"ל אשת חיל עטרת בעלה<sup data-n=\"804\">275</sup> יהי' ששון בנוק' כמ\"ש ושאבתם מים בששון ממעיני הישועה, שזהו ממים תחתונים שעולים באו\"ח שלמעלה משמחה דאו\"י דח\"ע כנ\"ל, בשאיבת מים בשמחת בית השואבה כמ\"ש במ\"א<sup data-n=\"805\">276</sup> לפי ששמחת חתן בעבור הכלה כשיתחדש ההלכה לאמיתתה ע\"י פלפול כו' וד\"ל.\n[לג] <b>ובזה</b> יובן גם כן בתוס' ביאור מ\"ש ועמדו רגליו כו' [ביום ההוא על הר הזתים כנ\"ל, דהנה לכאורה י\"ל במ\"ש ועמדו רגליו כו'] דמשמע מזה שע\"י עמידה זו יבקע ההר דוקא ועמידה זו ברגליו דמשפיע זהו בחי' או\"י דתורה הקדומה שירדה למטה בסוף העשי' ואיך יהי' בכח דאו\"י לבטל ההר הזה דבחי' או\"ח דמל' בבירור דתושבע\"פ כנ\"ל מאחר דכח דאו\"ח גדול יותר מכח",[["798","269","<b>שאינה כורתת ברית</b>: סנהדרין כב, ב."],["799","270","<b>משחקת לפניו בכל עת</b>: משלי ח, ל."],["800","271","<b>ב\"פ גבורה גימט' תבל</b>: ראה מאו\"א ת, יט — הובא באוה\"ת שמות ע' צח."],["801","272","<b>עוז והדר לבושה. . אשת חיל</b>: משלי לא, יו\"ד. כה."],["802","273","<b>דלויתן זה יצרת. . ורב תבואות</b>: תהלים קד, כו. משלי יד, יד."],["803","274","<b>שבשתיקה מתקדשת כמ\"ש במ\"א</b>: ע\"פ קידושין ה, ב. ראה להלן ד\"ה אשר ברא (השני). וד\"ה קול מצהלות (אות י\"ח). לקו\"ת צו ז, סע\"ג [ובהמ\"מ שם]. סידור עם דא\"ח קלב, ב. קלט, א. ס' מאמרי אדהאמ\"צ בראשית ע' ריט."],["804","275","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד."],["805","276","<b>ושאבתם מים בששון. . בשאיבת מים בשמחת בית השואבה כמ\"ש במ\"א</b>: ישעי' יב, ג. ראה סידור רסח, א ואילך. סה\"מ אתהלך-לאזניא ע' קלב ואילך."]]],[1900420201,"דאו\"י כנ\"ל אך הנה מבואר למעלה בענין הר הזיתים שהוא בחי' חכמה שבמל' ששמן זית זה בהר הזיתים היינו חכ' דתושבע\"פ שבא בהעלאה דאו\"ח כמו שצומח מן הארץ כארץ מגדלת כו' והוא בחי' צומח שבדומם לבד כנ\"ל שזהו כל מה שיהי' בכח החכמה דכנ\"י לחדש בדיוק ועיון במילין דחכ' להיות ריבוי התפשטות חידושי הלכות כו' מההעלם לגילוי מלמטה למעלה כמו שהי' באו\"י דח\"ע במ\"ת בתושב\"כ מלמעלה למטה עד שזרח משעיר כו' וד\"ל (וע\"כ יהי' ענין בקיעה זאת בהר הזיתים כמו שהי' בקיעה בים סוף סופא דכל דרגין מל' דאצי' בבי\"ע להפוך ים ליבשה שיהי' הכנה מזה לקבלת התו\"מ מאו\"י דח\"ע מהעלם לגילוי ביבשה בדיבור ומעשה, ולכך הי' בקיעה דים סוף מרוח קדים עזה בחי' רוח קדמין שלמעלה ממ\"ע דח\"ע כמ\"ש ורוח אלקים כו' שיצא האור בלי מסך ולבוש ח\"ע עד למטה בעשי', וכך יהי' בקיעה זו בהר הזיתים בדומם דמל' דעשי' בח\"ת דאו\"ח, וכמו שהי' המים דים סוף חומה מימינם כו'<sup data-n=\"806\">277</sup> כך ומש חצי ההר כו' שיהי' הכנה לעדן דעוה\"ב כו' וד\"ל.\n<b>וזהו</b> ועמדו רגליו היינו בחי' סוף הבירורים דאור ישר בעשי' דעשי' שזה בסוף מעשה עצמו שהוא עצם המעשה דמצות בלא טעם כלל ששרשו בעצם התענוג הפשוט שבמצות שלמעלה גם מטעם כמוס כו' כמו בדור האחרון הזה וממילא גם במקבלים גילוי הרצה\"ע בסוף מעשה שהן נש\"י אשר מקיימי' המצות בפו\"מ הוא בבחי' עשי' דעשי' רק בעצם המעשה לבד בלא טעם כלל גם בלא אוי\"ר כו', וזהו עד דמטו רגלין ברגלין כו' דבחי' רגל דדכורא בנה\"י דנה\"י ששרשו בפנימי' הכתר דגלגלתא ורגל דנוק' דכתר שבמל', וזה יהי' הכנה לעדן דעוה\"ב שלמעלה מן החכמה דטעמי המצות כידוע, וע\"כ עמידה זו דרגליו למעלה מענין מ\"ת בירידתו על ה\"ס גם שה\"ס עשן כולו כו' לפי שירד עליו שם הוי' דח\"ע הקדומה עד שהיפך חושך דק\"נ במדבר העמים כמ\"ש וזרח משעיר כו' שנתלבשה התורה בעה\"ד טו\"ר בלא תרצח כו', שכ\"ז הוא רק מקיף דתענוג דאו\"י בח\"ע שבא בקו המדה באו\"כ בציור האדה\"ע כמ\"ש וזאת תורת האדם כנ\"ל, וגם מה שנתקבל בכנ\"י באברים שבמל' בבחי' אדם תתאה במוחין ומדות עד סוף מעשה כמ\"ש פב\"פ כו' וכמו מים הפא\"פ<sup data-n=\"807\">278</sup> כן לב האדם כו' עד סוף כל הבירורים דח\"ע בח\"ת בימוהמ\"ש שזהו ענין הצמיחה בהר הזיתים אע\"פ שנק' חידוש גמור מאין דעצמות ממש, הרי מ\"מ זהו רק בבחי' חכמה שבמל' שקיבל מח\"ע דאו\"י, אבל בסוף מעשה עצמה שהוא בעצם הרצון ותענוג הפשוט למעלה אז יעמדו רגליו בהר הזיתים ויבקע ההר שיבוטל גם הדומם עצמה שלמעלה מהחכמה שבמל', להיות שגם המקבל יהי' בבחי' עצם ביטול הרצון העצמי למעלה מן הטעם ויהי' ממנו גיא גדולה שהוא השפלות לעומק תחת, כמו שהי' ביטול דחכמה ורצון בכנ\"י בה\"ס מצד קולות וברקים וכמו שנבקע",[["806","277","<b>ורוח אלקים. . חומה מימינם כו'</b>: בראשית א, ב. בשלח יד, כב."],["807","278","<b>פב\"פ. . מים הפא\"פ</b>: ואתחנן ה, ד. משלי כז, יט."]]],[1900420202,"המים והי' ליבשה כו', שזהו הי' רק בביטול הרצון שבטעם, ובהר הזיתים יהי' ביטול עצם הרצון שנק' דומם, וזהו שיהי' גיא גדולה היפך עלי' דהר בגובה כו', והוא מה שיתחבר אז בחי' עומק רום דשמים לרום במקיף דאו\"י דרצון ותענוג הפשוט עצמו שבמצות עד ארץ לעומ\"ת שבביטול עצם הרצון שבמצות, ועכ\"ז יהי' יחוד משפיע ומקבל ועלי' המקבל למעלה מן המשפיע דאו\"ח כו' נקבה תסובב גבר<sup data-n=\"808\">279</sup> כו' כתושבע\"פ שמקבל מתושב\"כ רק שתוסיף צמיחה כו', וכמו\"כ גם ברצון שלמעלה מן החכמה שהוא העוה\"ב שיהיו בנ\"י מקבלים מעצמות התענוג הפשוט שבמצות כמ\"ש להנחיל אוהבי יש ונק' ארץ חפץ<sup data-n=\"809\">280</sup> כו', אבל אח\"כ ונסתם הגיא כו' שזהו מדריגה הב' דעוה\"ב שלמעלה משכר המצות שהוא למעלה מתענוג ורצה\"ע שבמצות לגמרי כנ\"ל, ואז יבא ה' אלקי' וכל קדושיו שיהיו עולים בעילוי עד אין שיעור כו' עמך למטה כמו למעלה ממש לפי שזהו למעלה גם מבחי' מעלה ומטה דעומ\"ר ועומ\"ת אלא כמו שהוא בעצמות ממש שאין לומר בו למעלה עד אין כו' וד\"ל (וז\"ש ונבקע ההר מחציו מזרחה שהוא בחכ' בראש דמל' וימה בסוף, דגם מה שיחודש ע\"פ שכל חידושי הלכות הכל הוא למטה מעצם הרצון (רק שיגיע מזה לעדן העצמי כמ\"ש למחכה לו לבעה\"ר ומש ההר צפונה כו').\n[לד] <b>ועם</b> כל הנ\"ל יובן מ\"ש כיצד מרקדין לפני הכלה בש\"א כלה כמו שהיא ובה\"א כלה נאה וחסודה, א\"ל ב\"ש הרי שהיתה חיגרת כו' הלא נא' מדבר שקר תרחק<sup data-n=\"810\">281</sup>, א\"ל ב\"ה מי שלקח מקח רע מן השוק כו', הנה מבואר במ\"א ע\"פ ושמתי כדכד שמשותייך כו' שא' בגמרא מאי כדכד פליגי תרי מלאכי<sup data-n=\"811\">282</sup> ברקיע מיכאל וגבריאל ח\"א שוהם וח\"א ישפה כו' עד שא' להוי כדין וכדין שזהו בחי' צדיק עליון וצדיק תחתון שהוא בחי' או\"י ואו\"ח הנ\"ל כמ\"ש ועמך כולם צדיקים<sup data-n=\"812\">283</sup> צד\"ע וצד\"ת כידוע, והוא ההפרש בין קדושה לטהרה, שבחי' צ\"ע בחי' או\"י זהו האור הנמשך מעצמות התענוג הפשוט בחה\"ק דתורה אור וכן בשרש נש\"י שעלו במחה\"ק שנק' קדושי' בעצם הווייתן כמו שהאבן טוב דשהם הבהקתו בעצם וכמ\"ש אור זרוע לצד\"ע בבחי' יסוד דא\"ק דיסוד אבא שביסוד ז\"א למל' שזהו שהם אותיות משה<sup data-n=\"813\">284</sup> והוא בחי' יוסף צד\"ע כידוע וכמא' אורייתא",[["808","279","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["809","280","<b>להנחיל אוהבי יש. . ארץ חפץ</b>: משלי ח, כא. מלאכי ג, יב [וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רטז]."],["810","281","<b>כיצד מרקדין לפני הכלה. . מדבר שקר תרחק</b>: כתובות טז, סע\"ב. משפטים כג, ז."],["811","282","<b>במ\"א ע\"פ ושמתי כדכד. . פליגי תרי מלאכי</b>: ישעי' נד, יב. ראה ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תכ ואילך."],["812","283","<b>ועמך כולם צדיקים</b>: ישעי' סו, כא."],["813","284","<b>שהם אותיות משה</b>: ראה ס' מאמרי אדהאמ\"צ דברים ח\"א ע' פג. ח\"ב ע' תכ. ובהמ\"מ שם."]]],[1900420203,"קדישא וישראל קדישין<sup data-n=\"814\">285</sup> כו', והיינו כאשר נמשך אור דתו\"מ בנש\"י למטה כמו במ\"ת דחכמת אדם תאיר פניו בבחי' מקיף דתענוג הפשוט דאו\"י ברצון וחכמה דתורה שבאור פניך ממש נתת לנו כו' כמ\"ש פב\"פ כו', ובחי' צד\"ת הן נש\"י שבגופים שנזדככו מחומר גופם בביטול העצמות מכל וכל כשא' נעשה ונשמע כו', שזהו האור הבא מצד העלאה מלמטלמ\"ע בהתקשרות דמקבל אל המשפיע, והיינו כמו אבן טוב דישפה שנזדכך מחומריות שלו ונק' אבן ספיר כו', וזהו שנק' טהרה כמ\"ש ותחת רגליו כמעשה לבנת הספיר כו' (אבל באו\"י דתורה אור אז ראה ויספרה במספר דאותיות תורה שבכתב שהן מאירים בעצם שזהו ענין מצות קריאה בדיבור כנ\"ל שזהו בבחי' או\"י, אבל בירורים דאו\"ח בתושבע\"פ היינו כמו ישפה וכמו ותהי להם הלבינה לאבן<sup data-n=\"815\">286</sup> כנ\"ל). וזהו כדכד שכלול מב' מדריגות דאו\"י ואו\"ח יחד שלפי אופן ההעלאות בהזדככות החומר מן הצורה כך יש הזדככות הצורה מן החומר (וכמו נשמת אדה\"ר בגופו כמ\"ש במ\"א<sup data-n=\"816\">287</sup> דהיינו חיבור ויחוד דאו\"כ דמ\"ה וב\"ן שע\"י זיכוך הכלי ניתוסף האור וע\"י ריבוי האור נזדכך הכלי), וז\"ש ליהוי כדין וכדין וד\"ל.\n<b>וכך</b> יובן כאן במא' זה במחלוקת דב\"ש וב\"ה במחלוקת מיכאל וגבריאל שהן בחי' חו\"ג, כך ב\"ש וב\"ה, שרש ב\"ש בבחי' הגבורה, דשמאי לשון שומא ששם דרכו בהזדככות החומר בתכלית התיקון עה\"ד טו\"ר כמ\"ש ושם דרך אראנו בישע אלקים זהו השם אורחותיו<sup data-n=\"817\">288</sup> שמדקדק היטב בדרכיו בסו\"מ וע\"ט בתכלית לפי הצריך בבחי' העלאת מ\"נ וביטול המציאות בתו\"מ ותשובה בפו\"מ בכוונה טובה ורעותא דלבא אז זוכה ורואה בישועתו כו', שזהו בחי' המשכה דאו\"י בתו\"מ כמו שהן למעלה שנק' קדוש בעצם, וע\"כ בש\"א כלה כמו שהיא דוקא כך משבחים אותה, ואם אינה יפה בתורה ומצות ותשובה אלא להיפוך שפגמה באו\"כ דתו\"מ כמו חגרת בפגם דרגל בצדקה וסומא בראי' דחכ' שבראש בביטול ק\"ש ות\"ת וכה\"ג ה\"ז בעל מום ולא נק' יפ\"ת ויפ\"מ, דתואר יפה זהו בבחי' הציור דכלים דמעשה המצות ומראה יפה זהו בבחי' האורות דרצה\"ע שמלובש בהן וכמ\"ש ורחל היתה יפ\"ת ויפ\"מ שזהו בבחי' המל' כשקיבלה או\"מ ואו\"פ באופן ההתכללות דבחי' התיקון דאדה\"ע שזהו עיקר היופי כו' וכמ\"ש ומראך נאוה וכמ\"ש במ\"א<sup data-n=\"818\">289</sup>, ולזה אמרו ב\"ש לב\"ה הרי שהיתה חיגרת כו' הלא נאמ' מדבר שקר תרחק שזהו היפך דבחי' אמת דתורה שהוא בחי' התיקון ואיך יהפוך חושך לאור לומר על פגם מום שהוא נאה נגד התורה כו' וד\"ל. אבל ב\"ה שרשם מבחי' החסדים דאו\"י שיכולים להאיר גם את החשך",[["814","285","<b>אורייתא קדישא וישראל קדישין</b>: ראה זח\"ג מד, א. וראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' שסד. ח\"ב ע' תקלג [ובהמ\"מ שם נסמן לעוד מקומות]."],["815","286","<b>ותחת רגליו. . ותהי להם הלבינה לאבן</b>: משפטים כד, י. נח יא, ג."],["816","287","<b>וכמו נשמת אדה\"ר בגופו כמ\"ש במ\"א</b>: ראה גם תו\"א בראשית יט, ב ואילך."],["817","288","<b>ושם דרך. . השם אורחותיו</b>: תהלים נ, כג. מו\"ק ה, א."],["818","289","<b>ורחל היתה. . ומראך נאוה וכמ\"ש במ\"א</b>: ויצא כט, יז. שה\"ש ב, יד. ראה סה\"מ תקס\"ט ע' צג ואילך. תו\"ח ויצא לג, ג ואילך. ובכ\"מ."]]],[1900420204,"דק\"נ וזהו עיקר<sup data-n=\"819\">290</sup> כל התורה להפוך חשוכא לנהורא כו', ואע\"פ שהיא חיגרת וסומא יכול לומר כלה נאה וחסודה ואין זה שקר וטעות ממשל מי שלקח מן השוק כו'. ולכאורה זהו פלא דאין זו תשובה כלל על טענת ב\"ש דגם מי שלקח מקח כו' איך ישבחנו בשקר כו', ועוד דהלא גם בחי' או\"י דחסד עליון אינו מאיר רק לפ\"ע ההעלאה דאו\"ח בבירורים דעה\"ד בסו\"מ וע\"ט ואיך גם על חיגרת יאמר כלה נאה כו'. אך ע\"פ כל הנ\"ל בב' מדריגות דקריאה ועיון שבב' ברכות דמשמח חו\"כ ומשמח חתן עם הכלה כו' יובן גם זה. וצ\"ל תחלה מהו ענין הריקוד שאמר כיצד מרקדין לפני הכלה כו'. דהנה מבואר למעלה בענין דילוג האור דעצמות המאציל שמאיר כמו שהוא שלא ע\"י פרסא המפסיק בדרך בקיעה כו', והיינו שמאיר מעצמות התענוג הפשוט בחכ' כמו שהוא בבחי' אין דפנימי' הכתר בלי העלם ולבוש כלל, וכמו שהי' במ\"ת שמעצמות השעשועי' האיר בחכ' גם בחכ' שבדבור בא' אנכי כו', וזהו שנק' דילוג והוא ענין הריקוד דדילוג וריקוד א' הוא ברגל כמו הנה זה בא מדלג על ההרים כו', שהוא מעוצם השמחה והתענוג שיוצא חוץ לגדר כו'. וגם כאן בכל שמחת חו\"כ שהן בצלם דו\"נ שצריך לשמח את הכלה להעלותה למעלה מכפי ערכה ג\"כ בדילוג הערך ע\"י שמחה שפורץ גדר, והוא הריקוד דמקבל שתעלה למעלה מן הפרסא המפסיק בין אצי' לבריאה שזהו למעלה מן השכל באה\"ר בתענוגים כו', וע\"כ כל אנשי' חסידי' וצדיקים מרקדים לפני הכלה להללה ביותר שתשמח ותוכל לעלות בריקוד לגבי החתן העליון.\n[לה] <b>ולז\"א</b> כיצד מרקדין לפני הכלה, בש\"א כלה כמו שהיא דוקא, דהיינו לפ\"ע מעלתה ביופי בתואר ומראה בתו\"מ כנ\"ל, להיות כמו שמלמעלמ\"ט הדילוג בהמשכת החסדים דאו\"י דמשפיע ביתר מכפי המדה הראשונה דקו המדה המצומצם, כך מלמטה למעלה במקבל צ\"ל בהעלאה וביטול דאו\"ח למעלה מן המדה, והוא בבחי' העלאה דקבלת עומ\"ש באה\"ר שבעצם הרצון ותענוג הפנימי באה\"ר בתענוגים שאז נק' יפ\"ת ויפ\"מ במזיגה נכונה בהתכללות כמ\"ש נעשה כו', שזהו הכל כפי המדה בהעלאה והמשכה ע\"פ אמת דתו' במ\"ע ול\"ת בחו\"ג דאוי\"ר כפי הצריך לתיקון דעה\"ד טו\"ר דבחכמה דתורה אתברירו בבחי' שם מ\"ה דאדם כנ\"ל, ומטעם זה גם בשכר המצות בעוה\"ב שהוא בחי' גילוי התענוג הפשוט שברצה\"ע דמצות שלמעלה מן הטעם כמ\"ש כל ישראל יש להם חלק לעוה\"ב שנאמר ועמך כולם צדיקים בתו\"מ בפו\"מ בביטול עצם הרצון דאפי' פושעי ישראל<sup data-n=\"820\">291</sup> מלאים מצות כו' ולא לעוברי רצונו לגמרי כמ\"ש אלה לחיי עולם<sup data-n=\"821\">292</sup> ואלה לחרפות כו', וזהו כלה דלע\"ל",[["819","290","<b>וזהו עיקר כה\"ת להפוך חשוכא לנהורא</b>: ראה זח\"א ד, א."],["820","291","<b>כל ישראל. . ועמך כולם צדיקים. . דאפי' פושעי ישראל</b>: סנהד' ר\"פ חלק. ישעי' סו, כא.\nעירובין יט, א."],["821","292","<b>אלה לחיי עולם</b>: דניאל יב, ב."]]],[1900420205,"בעוה\"ב כמו שהוא דוקא באמת דתו\"מ, והן ב' צדיקים דצד\"ע וצד\"ת כו' דטהרה מביאה לידי קדושה דעוה\"ב כנ\"ל וד\"ל.\n<b>אבל</b> בה\"א כלה נאה וחסודה, כי אע\"פ שהתו\"מ ניתנו ע\"פ קו המדה בהתכללות דאו\"כ בתואר ומראה באו\"פ ואו\"מ שהוא בהעלאה והמשכה מזוגה מאו\"י ואו\"ח יחד בסו\"מ וע\"ט, כ\"ז אינו אלא בחי' חכ' דאדם שם מ\"ה דתיקון באו\"כ שזהו תומ\"צ שהוא אור הרצה\"ע בחכ' ומדות, וכמו שהי' במ\"ת שעז\"נ כמים הפנים א\"פ כן לב האדם העליון לאדם התחתון למהוי אחד באחד יחו\"ע ויחו\"ת דהוי' ואלקים קוב\"ה ושכינתי' (וכמו ב' חצאי כדורים שעליון מתרחב באמצע והתחתון עולה לנגדו להתחבר בו כו' כנ\"ל וד\"ל), אבל בבחי' עצם הרצון והתענוג שלמעלה מן החכ' לגמרי שם הוא למעלה מבחי' אדם, והוא בגלגלתא שע\"ג המוחין, ושם א' כולך יפה רעייתי<sup data-n=\"822\">293</sup> ומום אין בך כו', דאין המום רק באברים אבל במקיף דכתר שנק' יחידה למעלה מציור אדם וגם שהיא חיגרת ברגל אין זה מום כמ\"ש אז ידלג כאיל פיסח<sup data-n=\"823\">294</sup> כו', וגם לעוה\"ב יאיר מעצמות התענוג הפשוט וכל מי שהי' בו ביטול הרצון בעצם כו' יקום בתחה\"מ ויחי' בחיי העוה\"ב, וכמו ביוכ\"פ שנמשך מרעוא דכל רעוין לסלוח לעוברי רצונו למעלה ממשפט התורה כו', כי בבחי' עצמות התענוג והרצון הוא למעלה גם מעונג ושעשועי' שבתוה\"ק כנ\"ל שזהו מדריגה הב' דעוה\"ב שלמעלה מן המצות לגמרי כו'. וב\"ה סברי שגם עוה\"ב אע\"פ שהוא שכר המצות אבל המצות בטילות לעוה\"ב כמ\"ד מצות בטלות<sup data-n=\"824\">295</sup> לע\"ל כו' וכמ\"ש חנם בלא מצות<sup data-n=\"825\">296</sup> (רק בימוהמ\"ש שיהי' אז שלימות הבירורים דמצות בביטול עצם הרצון כמו שיעמדו רגליו בהר הזיתים שיתחברו רגלי דאו\"י בסוף מעשה ברגלי דאו\"ח כנ\"ל), והוא ענין העדן העליון דעין לא ראתה רק למחכה לו בדיוק דחכ' שמגיע לבעל הרצון כו', שזהו מה שת\"ח אין להם מנוחה בעליי' בעוה\"ב שעולי' בשעשועי המלך בעצמו בלי שיעור. והיינו דעת ב\"ה שהן מבחי' ורב חסד דעצמות התענוג הפשוט שלמעלה גם מקו המדה דתו\"מ כמו בעוה\"ב ויו\"כ לבע\"ת כו', ע\"כ או' כלה נאה וחסודה שמקבלת מעצמות רב חסד הפשוט שבעצמות התענוג הפשוט כנ\"ל שגם שהיא חיגרת ברגל נאה היא, כמו בי\"ג מדה\"ר דרעדכ\"ר נתמלא כל חסרון ופגם המוחין דבע\"ת כו' מטעם הנ\"ל שבמקיף דעצמות הכתר למעלה מציור אדם כו'), וכמ\"ש ואביוני אדם<sup data-n=\"826\">297</sup> שהן בע\"ת שאין בהם צלם אדם דתו\"מ כלל עכ\"ז בקדוש ישראל יגילו בקדושה",[["822","293","<b>כולך יפה רעייתי</b>: שה\"ש ד, ז."],["823","294","<b>אז ידלג כאיל פיסח</b>: ישעי' לה, ו."],["824","295","<b>מצות בטלות</b>: נדה סא, ב. וראה ס' מאמרי אדה\"ז נ\"ך ע' ה [ובהמ\"מ לשם]. ס' מאמרי אדהאמ\"צ נ\"ך ע' א ואילך [ובהמ\"מ]."],["825","296","<b>חנם בלא מצות</b>: ראה לעיל אות ז'. וש\"נ."],["826","297","<b>ואביוני אדם</b>: ישעי' כט, יט. וראה סה\"מ תקס\"ב ח\"א ע' נה ואילך. ס' מאמרי אדה\"ז נ\"ך ע' כז ואילך."]]],[1900420206,"העצמי' דא\"ס שלמעלה גם מקדושה דתומ\"צ כמ\"ש קדושים תהיו ע\"י תו\"מ יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם ע\"י תו\"מ כמ\"ש אין קדוש כה' גם דאורייתא קדישא<sup data-n=\"827\">298</sup> כו'.\n<b>וזהו</b> שהשיבו ב\"ה על טענת ב\"ש מדבר שקר תרחק שאין לה רק ע\"פ המדה דתורה שאינו רק להבדיל בין טו\"ר וגם זה במדה ושיעור כו', שזהו שנק' מקח מן השוק שהן קליפות הטמאות ברע דנוגה כמו אמצאך בשוק<sup data-n=\"828\">299</sup>, והוא כמו שלוקח דבר מן השוק דבר מכוער ועשאו כלי יקר ששוה יותר מן אבן טוב ששוה הרבה לפי עצם טובו כי הדבר שהביא מן השוק יקר בעיניו מאד מצד הפלאת הדבר שאינו בנמצא כלל, ומה גם שנעשה מדבר מכוער כלי יקר ביותר כו' שאין בזה מקח השוה לסוחרים כלל ע\"כ אין בזה שקר כלל אם ישבחנו ביותר משווי, וכך גם שהיא חיגרת יכול לומר כלה נאה וחסודה באמת דקמי' גם חושך לא יחשיך דזדונות נעשו כזכיות<sup data-n=\"829\">300</sup> ממש ע\"י תשובה וי\"ג מדה\"ר וד\"ל. וזהו בכלל ב' מדריגות דעוה\"ב, א' שכר המצות בצדיקים בפו\"מ, שזהו מ\"ש ואכלתם אכול<sup data-n=\"830\">301</sup> ושבוע בעונג המורגש בשביעה דוקא, כמ\"ש במ\"א במ\"ש ואכלת ושבעת ובנ\"י החמירו ע\"ע בפחות מכשיעור וע\"כ נושא פנים להם כמ\"ש ישא ה' פניו<sup data-n=\"831\">302</sup> כמו ביוכ\"פ, והמדריגה הב' דעוה\"ב למעלה מיאר ה' פניו בעוה\"ב בשכר המצות כי פחות מכשיעור זהו כאביון דבע\"ת הנ\"ל וד\"ל (כסעודת לויתן דאו\"י ושור הבר דאו\"ח שע\"י תשובה), והב' למעלה מאכילה ושתי' רוחני' ג\"כ רק בבחי' ביטול והתכללות למעלה בעילוי אחר עילוי בעצמות השעשועים כמו יהללוך סלה כנ\"ל, וזהו והללתם את שם ה'<sup data-n=\"832\">303</sup> הפלא ופלא למעלה מעונג שבתו\"מ, וכמו בע\"ת שנק' אביוני אדם שאינם רק בחיות נפשם בעצמו כו', וזהו בית הלל שמהללים תמיד כו', וזהו במקום שבע\"ת עומדים<sup data-n=\"833\">304</sup> צדיקים גמורים אין יכולים לעמוד כו' וד\"ל.",[["827","298","<b>קדושים תהיו. . יכול כמוני. . אין קדוש כה'. . דאורייתא קדישא</b>: קדושים יט, ב. ויק\"ר פכ\"ד, ט. שמואל-א ב, ב. זח\"ג מד, א — נסמן לעיל ריש אות ל\"ד."],["828","299","<b>אמצאך בשוק</b>: שה\"ש ח, א."],["829","300","<b>גם חושך לא יחשיך דזדונות נעשו כזכיות</b>: תהלים קלט, יב. יומא פו, ב."],["830","301","<b>ואכלתם אכול</b>: יואל ב, כו."],["831","302","<b>במ\"א במ\"ש ואכלת ושבעת ובנ\"י החמירו. . ישא ה' פניו</b>: עקב ח, יו\"ד. במדב\"ר פי\"א, ז. נשא ו, כו. ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' רכב ואילך."],["832","303","<b>והללתם את שם ה'</b>: יואל שם."],["833","304","<b>במקום שבע\"ת עומדים</b>: ברכות לד, ב. רמב\"ם פ\"ז ה\"ד."]]],[1900420207,"<h3>אשר ברא כו' לשון בריאה</h3>\n<b>בעז\"ה</b>\n<b>אשר</b> ברא<sup data-n=\"834\">1</sup> ששון ושמחה כו', ויש להבין איך יתכן בריאה שהיא מאין ליש בשמחה שהיא שמחת הנפש שבאה מעצמה ע\"י סיבה כמו ע\"י בשורה טובה או ע\"י היין וכה\"ג. והנה תחלה יש להקדים להבין מארז\"ל משחרב בהמ\"ק אין שמחה אלא ביין<sup data-n=\"835\">2</sup> והיינו משחרב בהמ\"ק דוקא אבל בזמן בהמ\"ק לא הי' השמחה ביין דוקא, וגם י\"ל מה שא' אלא ביין ולא א' מן היין או עם היין, כי הבי\"ת דביין משמעו במה שבתוך היין בא בהתלבשו' ובהעלם ולא מצד היין עצמו, וכידוע דלשון בי\"ת השימוש נופל בדבר עצמו ובמה שבתוכו ג\"כ כו'. אך הנה ידוע בענין מהות השמחה שהיא שמחת הנפש יש בה ב' מדריגות, א' שמחת הנפש מצד עצמה שאין לה חיבור עם הגוף כלל כו', והוא בבחי' יחידה כו', כמו ע\"י בשורה טובה ונפלאה ביותר כבשורה דיוסף ליעקב ויצחק לשרה וכשמחת לבו בחתונת<sup data-n=\"836\">3</sup> בנו וכה\"ג, והב' שמחת הנפש שמתחבר בגוף במוח ולב ונק' שמחה גופני' עד שמרקד ומפזז כו'. וכך יובן בשמחת הנפש באלקות שנק' שמחה אלקי' מצד עצם אלקו' בלבד וכמו ישמח ישראל בעושיו וישמחו בך<sup data-n=\"837\">4</sup> ישראל כו' שאין בה חיבור מצד הגוף החומרי, וזה הי' בזמן בהמ\"ק שהי' בנש\"י עיקר השמחה שמחה אלקי' דוקא ולא שמח' גופני' וגשמי' רק שהנפש האלקי' מצ\"ע תשמח בה' בגילוי אור בבחי' עצמי', וסיבת התפעלות שמחת הנה\"א בכללו' נש\"י בזמן בהמ\"ק הי' מצד גילוי אור אלקות בבהמ\"ק בהיכל קד\"ק ובקרבנות כו' (וכענין אשה בעלה משמחה<sup data-n=\"838\">5</sup> וכן שמח תשמח ריעי' האהובי' כו'), וע\"כ גם בירידת השמח' האלקי' דכנ\"י בגופים במועדים ורגלים כמ\"ש ושמחת בחגי\"ך<sup data-n=\"839\">6</sup> שמח' גשמי' הרי ז' ימים תחוג לה' אלקיך דוקא כו' ושמחתם לפני ה' אלקיכם דוקא אע\"פ שהיו שמחים גם בגשמי' ביין ובשר כו' לא הי' זה גרעון אור כלל בשמח' האלקי' בנפשם אדרבה הי' זה בחי' כלי ולבוש לשמח' האלקי' ממש, וכמ\"ש ונתת הכסף<sup data-n=\"840\">7</sup> בכל אשר תאוה נפשך כו' הרי בשר שלמים שאכלו נק' שלמי שמחה האלקי' כו' וכן היין הגשמי' המשמח הי' בו שמחה אלקי' כו', וראי' לזה ממה שהמועד והרגל נק' בשם ח\"ג כמ\"ש ושמחת בחגי\"ך",[["834","1","<b>אשר ברא</b>: המאמר מיוסד על ד\"ה זה בסידור עם דא\"ח קלז, ג [והוא משנת תקס\"ד — כנרשם בסוף סה\"מ תקס\"ד ע' שנג]. וראה עוד להלן בהוספות ברשימת הכתבי-יד.\n[עוד מאמרים בהתחלה זו ”אשר ברא\" — נדפסו בסה\"מ תקס\"ג ח\"א ע' רנט [והגהות עליו באוה\"ת סידור ע' רכ וע' רלו. ותוכן המאמר באריכות לעיל ח\"א ע' קסא]. סה\"מ תרל\"ד ע' טז. סה\"מ תרפ\"ט ע' 86 [על חתונת כ\"ק אדמו\"ר שליט\"א]. סה\"מ תרח\"ץ ע' קפג. ד\"ה זה תשל\"ט (בסה\"מ מלוקט ח\"ד ע' עט). ד\"ה זה תשמ\"ח]."],["835","2","<b>משחרב בהמ\"ק אין שמחה אלא ביין</b>: פסחים קט, א."],["836","3","<b>בחתונת בנו</b>: בכת\"י ב: בחתונתו."],["837","4","<b>ישמח ישראל בעושיו וישמחו בך</b>: תהלים קמט, ב. נוסח תפלת שבת."],["838","5","<b>אשה בעלה משמחה</b>: ר\"ה ו, ב."],["839","6","<b>ושמחת בחגיך. ֿ. ז' ימים תחוג. ֿ. ושמחתם לפני ה\"א</b>: דברים טז, יד-טו. אמור כג, מ."],["840","7","<b>ונתת הכסף</b>: דברים יד, כה."]]],[1900420208,"וכן מ\"ש שבעת ימים תחוג לי<sup data-n=\"841\">8</sup>, ופי' חג בלה\"ק הוא מענין רשפי אש בוער בהתלהבות כו' כידוע<sup data-n=\"842\">9</sup>, והיינו בחי' רשפי אש התלהבות השמחה של הנפש, ואע\"פ שהשמחה במועד שנק' מועדי' לשמחה היא רק שמח' אלקי' מצד עצם אלקו' שמתגלה בכל נשמה כמ\"ש אלה מועדי ה'<sup data-n=\"843\">10</sup> כו' ומאין יהי' התלהבות בשמח' הנפש מאחר שאין בה מחיבור הגוף, אלא מצד שהנשמה מתלבשת בשמח' גופני' להיות שגם שמח' הנשמ' עצמה היא בבחי' רשפי אש האה' אלקי' שכלול מחו\"ג שנק' שלהובא דרחימותא<sup data-n=\"844\">11</sup> היינו שהאהבה כלולה מחסדי' אה' בתענוגי' והתלהבות רשפי אש יחד ואז השמחה כלולה מחו\"ג יחדיו, וכמ\"כ נראה בשמח' גופני' התכללו' מחו\"ג יחד ברשפי אש התלהבות התענוג והשמחה כו', וזהו שנק' בשם ח\"ג דוקא ור\"ת ח\"ג חסד וגבור' שכלולי' יחד מפני שזהו עיקר ענין שמחת הח\"ג וד\"ל.\n[ב] <b>אך</b> הנה משחרב בית המקדש א\"א להיות בחי' השמחה אלקי' הנ\"ל בנש\"י בבחי' פנימי' ועצמי' כ\"כ עד שלא יגרע אורה כלל בשמח' גופני' מצד בחי' הסתלקות גילוי אור האלקי מכנ\"י וכמ\"ש ובפשעיכם שולחה אמכם<sup data-n=\"845\">12</sup> כו' וגם קוב\"ה בגלותא כו', וגם בכל מועד ורגל שנק' מועדי' לשמחה כו' מפני שהוא מאיר בהעלם בכאו\"א אע\"פ שאין אנו יכולי' לעלות וליראות כו' מ\"מ אנו אומרי' בקידוש ומועדי קדשך בשמחה הנחלתנו וישמחו בך ישראל כו', אך שהשמח' אלקי' דמועדי ה' בא בהתלבשו' בלבוש זר דוקא כי לא תוכל להיות השמחה אלקי' לבדה כמו שהיא למע' בשרשה בנש\"י למטה בלתי לבוש ומכסה היינו השמחה הגופני' המסתרת ומעלמת לאור שמח' האלקי' כי השמח' הגופני' הוא הגבהת וגסות הלב היפוך גמור מן השמחה האלקי' שהוא בחי' ביטול עצמי עד כלותה כו', וזהו מצד בחי' גלות השכינה בע' שרים דק\"נ שמתלבשת בלבושי' והעלמות רבות וזרות ע\"כ לבושי' זרים דשמח' גופני' מלבשת לשמח' האלקי' שיש בכאו\"א גם עכשיו בגלות כמא' גלו לאדום שכינה עמהם<sup data-n=\"846\">13</sup> וגם בג' מועדי' כו'. ולזה א' משחרב בהמ\"ק דוקא אין שמח' אלא ביין",[["841","8","<b>שבעת ימים תחוג לי</b>: בכת\"י ב ליתא תיבות ”שבעת ימים\" רק ”וכן מ\"ש תחוג לי\". [ונראה כבכת\"י ב, דבפסוק נאמר רק ”שלש רגלים תחוג לי\" (משפטים כג, יד), או ”שבעת ימים תחוג לה'\" (דברים טז, טו). וכן הובא לעיל בסמוך ובסידור עם דא\"ח קלז, ג]."],["842","9","<b>ופי' חג בלה\"ק. ֿ. בהתלהבות כו' כידוע</b>: ראה גם סידור רכא, ג: ועל כן נקרא חג מלשון חגים ינקפו שהוא לשון התלהבות אש שלהבת שנקרא חג. וס' מאמרי אדה\"ז ”אתהלך-לאזניא\" ע' מט. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קלב. במדבר ח\"ג ע' תתקסט. ח\"ה ע' א'תרנז. דברים ח\"ג ע' תתי [ובהמ\"מ שם]."],["843","10","<b>אלה מועדי ה'</b>: אמור כג, ד."],["844","11","<b>שנק' שלהובא דרחימותא</b>: ראה זח\"ג לג, ב. פד, א. וראה סה\"מ תקס\"ד ע' כא."],["845","12","<b>ובפשעיכם שולחה אמכם. ֿ. קוב\"ה בגלותא</b>: ישעי' נ, א. ראה זח\"א רי, א. זח\"ב נח, ב. זח\"ג כ, ב. וראה ס' מאמרי אדהאמ\"צ דברים ח\"א ע' קעז. ובכ\"מ."],["846","13","<b>גלו לאדום שכינה עמהם</b>: מכילתא בא יב, מא. ספרי בהעלותך י, לה. מסעי לה, לד. וראה לקו\"ש ח\"ז ע' 210."]]],[1900420209,"ששמח' היין המשמח הלב בגשמי' הוא בחי' כיסוי ולבוש לשמח' האלקי' שתתעלם ותתלבש בה מטעם הנ\"ל וד\"ל.\n<b>אך</b> עדיין א\"ז מובן דהלא מ\"ש ושמחת בחגיך הי' ג\"כ ע\"י השמחה שביין ובשר שהוא בחי' נוג\"ה ולמה דוקא משחרב בהמ\"ק אין שמחה אלא ביין כו'. אך הנה ידוע דכל אור ושפע עליונה נמשך ע\"י שלוחים ממוצעי' והן המלאכי' העליוני' כו' עד שאין לך כל עשב<sup data-n=\"847\">14</sup> ועשב שאין לו מזל ומלאך כו', וא\"כ גם היין שגדל בגפן שרשו ברוחני' המזל המגדל מאין הרוחני' ליש כו', ולפ\"ז גם מה שיש בכח היין לשמח את הנפש שמחה גשמי' זהו ג\"כ בא מבחי' שפע רוחני' דמלאכי' העליוני' דעולם העשי' כו' שפועלי' שפע המשכו' דצח\"ם להיות כח התהוות שמח' גשמי' דיין המשמח כו' והוא מעורב טו\"ר כי יש ביין רתיחה וכעס ורציחה כמו רבה דשחטי' לר\"ז<sup data-n=\"848\">15</sup> כו' והגבהות וגסות ביותר כנ\"ל, וכידוע בענין אשכול של ענבים סחטה לו<sup data-n=\"849\">16</sup> כו'. אך ודאי שרש ומקור לשפע התהוות שמח' האלקי' בנה\"א בא מפנימי' האור והשפע דשמח' העליונה שבמלאכי' העליוני' הרבה יותר שפועלים התהוות שמחה אלקי' זו מאין ליש וכמ\"ש ויספו ענוים בה' שמחה (וכמ\"ש במ\"א<sup data-n=\"850\">17</sup>) (וכמו במועדי' לשמחה שנמשך שפע שמח' האלקי' הנ\"ל בכאו\"א מאין ליש וכן בשמח' ש\"מ ושמח' בד\"ת וכמשי\"ת), ואין בשמחה זו שום שמץ רע כלל ולא דברים המסתעפי' לרע כלל להיותה באה מפנימי' המלאכי' שאין בהם תערובו' טו\"ר כו', וגם בהיותה מתלבשת בשמחה הגשמי' מן היין המשמח הגוף אע\"פ שמעורב טו\"ר כנ\"ל מתאחד בחי' הטוב שביין בשמח' האלקי'<sup data-n=\"851\">18</sup> ונק' יין המשמח אלקי' כו' (כמו אגברו חמרא אדרדקי, וכיין ישן שדעת זקנים נוח הימנו וכמו שא' חמרא וחיי לפום רבנן וכן חמרא וריחא פקחין וכה\"ג). וזה הי' בזמן בהמ\"ק שהי' שמח' אלקי' מתאחד ומתחבר בשמח' גשמי' דיין ואדרבה נכנס יין יצא סוד שמח' האלקי' מן ההעלם לידי גילוי יותר ובלתי לבוש זר כלל, אבל משחרב בהמ\"ק שבה שפע שמח' הגשמי' שביין מעורב רע יותר מצד שבא מבחי' פסולת ושמרי' של שפע חיצוני' מלאכי' ומזלות דעשי' שנפלו למטה בעה\"ד טו\"ר כמ\"ד גפן הי'<sup data-n=\"852\">19</sup> כו', אז הוא להיפוך גמור שנתעלם ונתלבש הפנימי' דשמח' אלקי' ביין המשמח שמח' גשמי' ונתאחדו יחד עד שהשמחה גשמיי' מסתרת ומעלמת מאד לשמח'",[["847","14","<b>שאין לך כל עשב</b>: ב\"ר פ\"י, ו. ועוד."],["848","15","<b>רבה דשחטי' לר\"ז</b>: מגילה ז, א."],["849","16","<b>אשכול של ענבים סחטה לו</b>: ראה ב\"ר פי\"ט, ח. זח\"א לו, א."],["850","17","<b>ויספו ענוים בה' שמחה (וכמ\"ש במ\"א)</b>: ישעי' כט, יט. ס' מאמרי אדהאמ\"צ על נ\"ך ע' כז ואילך [וע\"ש בהמ\"מ בתחלת המאמר]."],["851","18","<b>יין המשמח אלקי'. ֿ. אגברו חמרא אדרדקי. ֿ. וכיין ישן שדעת זקנים. ֿ. חמרא וחיי. ֿ. חמרא וריחא פקחין</b>: שופטים ט, יג. סנהדרין לח, א. מגילה טז, ב. שבת סז, ב. יומא עו, ב."],["852","19","<b>גפן הי'</b>: ברכות מ, א."]]],[1900420210,"האלקי' גם במועדי' ורגלי' מטעם הנ\"ל שהשכינה בגלות ונתלבשה בלבושי' זרים דק\"נ בבחי' העלם גדול ע\"כ הפנימי' מתעלם מאד עד שאין השמחה אלקי' נגלית רק ע\"י לבוש זר דיין הגשמי' שהוא מעורב טו\"ר כנ\"ל וד\"ל. והיינו ב' פי' דביין, א' עם היין או מן היין שהוא בחי' הלבוש ומכסה ומסתיר מאד לשמח' האלקי' כאלו אין השמח' רק מן היין מצ\"ע, והב' ביין במה שבתוכו גנוז ונעלם והוא בחי' השמחה האלקי' שבנפש שבהעלם ביין. והוא מ\"ש דדוקא משחרב בהמ\"ק אין שמחה אלא ביין, פי' אין שמח' האלקי' בא' כ\"א ע\"י אמצעי' ולבוש היין גם במועד ורגל, משא\"כ בזמן בהמ\"ק שהעיקר הי' השמח' אלקי' והיין הי' טפל ובטל רק בבחי' כלי לבד להיות יוצא הסוד יותר כנ\"ל וד\"ל.\n[ג] <b>והנה</b> מעתה י\"ל מ\"ש אשר ברא כו' איך יתכן לשון בריאה מאין ליש בשמח' הנפש כו'. דהנה אנו רואים שיש ב' מיני שמחה, א' שמחה שיש לה כלי ומכון בתחלה ששם תתגלה אור מציאותה והתפשטותה, כמו שמחה שבמוח בהתבוננו' הרי שמחה זו נעשי' ע\"י הטו\"ד שמשיג בשכל כמו שישמח האדם בשכל וסברא טובה וחדשה כו' מפני שיש בה כבר תענוג ושמחה בשכל והשגה, וה\"ז לפי\"ע הגבול של השכל והשגה כמו בכאו\"א לפי\"ע שכלו והשגתו, וגם אין זה נק' יש מאין כלל אלא יש מיש והוא מה שיהי' העונג והשמחה בשכל, יצא לידי גילוי לבד ובבחי' הכלי דוקא שהוא כלי המוח שלו כו', וכן בשמחה שבלב כמו במדות האה' וחסד והתפארו' וכה\"ג זהו ג\"כ בא בבחי' כלי ובהכנה מקודם שהוא לפ\"ע המדה באור האה' כו' כאהבת איש לרעהו ואיש לאשתו כו' שישמח באהבתו כו' ונק' שמח' הלב וא\"ז ג\"כ יש מאין רק יש מיש ובגבול וכלי כנ\"ל וד\"ל (וכן שמחה שבמחדו\"מ הכל בא במדה וגבול ובכלי דוקא ואין זו שמח' עצמי' רק מורכבת, וגם שמח' שבתענוג ורצון פרטי לדבר מה כמו בממון ומאכל ולבוש וכה\"ג אע\"פ שתשמח כל נפשו בזה אבל בא בדרך והדרגה באו\"כ במוח וממוח ללב כו'). והשמחה הב' הוא שאין לה בחי' כלי ומכון בתחלתה כלל וכלל בכל כלי' ואברי הגוף ולא במוח ולב וגם לא ברצון ותענוג כו', והוא השמח' הבאה בפתע פתאום ברגע ע\"י בשורה טובה ונפלאה ביותר עד שמגיע לו בעצמי' נקודת חיי נפשו ממש כבשורה דיוסף ליעקב דכתי' ותחי רוח יעקב<sup data-n=\"853\">20</sup> כו' וכה\"ג, שאז בלתי תמצא לשמחה זו שבעצמות הנפש ממש שנק' שמח' הנפש דיחידה ממש שום כלי ומכון שתוכל להתיישב שם, שלא הוכן לה בתחלה כלל שום כלי לא במוח ולא בלב, מפני שהשמחה הזאת באה ונמשכת מבחי' אין ממש דהיינו מהעלם נקודת עצמי' הנפש (שנק' מזלא ויחידה כו') פתאום, שזהו הנק' מאין ליש שלא הי' במציאו' כלל בתחלה רק שאין הרוחני' הנעלם בא בהתגלות (כמו בהיפוכו הלב יודע מרת נפש שבהעלם דמזל\"א כך יש שמחת הנפש במזל\"ו וצלמו בהעלם ממש כו'), וע\"כ אין כלי מיוחד אלי' כלל בגוף רק מתפשטת במוח ולב יחד",[["853","20","<b>ותחי רוח יעקב</b>: ויגש מה, כז."]]],[1900420211,"בשוה ברגע א' מבלי סדר והדרגה כלל ממוח ללב כשמח' שבהשגה כו' מאחר שכלי המוח והלב אין ערך אלי' ולא יכילוה כלל מפני שביאתה והמשכתה הוא מבחי' אין הנעלם שאין שייכות למוח ולב שם כלל ע\"כ ממילא מתפשטת במוח ולב בשוה שלא בדרך או\"כ כלל (והוא ענין הסיפוק בידים שבא משמחה פתאומי' דוקא כידוע מפני שלא יכילנה כלי הלב והמוח ובידים יש הארה מבחי' יחידה שבנפש, וכידוע בענין נשיאת כפים ומבואר ע\"פ בצאת ישראל ממצרים<sup data-n=\"854\">21</sup> כו').\n<b>וזהו</b> שא' על שמחה האלקי' הזאת שבנפש עצמה אשר ברא דוקא ולא א' יצר או עשה, לפי שהבריאה היא יש מאין דוקא ולא יצי' ועשי' שהוא יש מיש כידוע בענין אם בריאה יברא ה'<sup data-n=\"855\">22</sup> כו' (וגם בנפש האדם עצמו א' אשר יצר את האדם כמ\"ש וייצר ה' אלקי'<sup data-n=\"856\">23</sup> כו' אבל בשמח' הנפש שבא ממקור העליון שלמע' מיצי' הנפש א' אשר ברא כו'). אבל גילוי אור שמח' זו בנפש נק' בחי' נוק' מקבל, ומקור השפע הזאת כמו שהוא הוא בחי' דכר, והוא ההפרש שבין ששון לשמחה ששון בדכורא ושמחה בנוק', כמ\"ש כמשוש חתן על כלה כן ישיש עליך אלקיך הרי הששון בחתן ואשה בעלה משמחה הוא הנק' שמחה בה\"א, ובאשר ברא אמר משמח חתן עם הכלה בשביל הכלה שהכלה עיקר, אך בפתיחת הברכה אמר אשר ברא ששון ואח\"כ ושמח\"ה חת\"ן ואח\"כ כל\"ה כו' כמ\"ש במ\"א באריכות<sup data-n=\"857\">24</sup>.\n[ד] <b>והנה</b> ידוע ההפרש בין תענוג לשמחה, שהתענוג הוא בעצם הנפש (כאשר אין העונג נמשך עדיין בדבר פרטי רק מתענג בעצם הנפש ממש שהוא הנק' שעשועי עצמי' הנפש בבחי' יחידה שבה ממש שהיא למע' מעלה מכל מהות מציאו' כחות הנפש דרצון ושכל ומדות עד ששם יכולי' להתהפך מקצה לקצה ממש כידוע), והשמחה העצמי' הנ\"ל היא הבאה ונמשכת מבחי' העלם עצם התענוג שבעצם הנפש הנ\"ל. והנה הלא מבואר למע' שיש הפרש בין זמן בהמ\"ק לזמן הגלות באופן התלבשו' שמח' האלקי' בשמח' היין הגשמי'. והענין הוא בהיות שיש ב' אופני' בבחי' התגלו' אור השמחה העצמי' הנ\"ל, א' כמו שהיא נמשכת מלמעלמ\"ט בפתע פתאום כמו ע\"י בשורה טובה ונפלאה וכה\"ג, והב' ע\"י העלאה מלמטלמ\"ע והוא ע\"י היין המשמח הלב שביכולתו",[["854","21","<b>וכידוע בענין נשיאת כפים ומבואר ע\"פ בצאת ישראל ממצרים</b>: ד\"ה בצאת ישראל — בס' מאמרי אדה\"ז עה\"ת ח\"ב ס\"ע תקל ואילך. וראה תו\"ח בשלח רצו, א. ס' מאמרי אדהאמ\"צ שמות ח\"א ע' פו. ויקרא ח\"א ע' ריח. במדבר ח\"א ע' קלד. ח\"ב ע' שמט ואילך. דברים ח\"ד ע' שצג."],["855","22","<b>כידוע בענין אם בריאה יברא ה'</b>: קרח טז, ל. ראה תו\"ח שמות תכה, ב ואילך."],["856","23","<b>וייצר ה' אלקי'</b>: בראשית ב, ז."],["857","24","<b>חתן ואח\"כ כלה כו' כמ\"ש במ\"א באריכות</b>: ראה לעיל ח\"א ע' כד, ובהנסמן באריכות בהמ\"מ לשם. לעיל ד\"ה שמח תשמח (השני) סוס\"ח, וד\"ה משמח חתן וכלה, וריש ד\"ה להבין ענין מה שבברכה ראשונה. ובד\"ה להבין שינויי הברכות בסה\"מ תקס\"ח ח\"א ע' מד. ובכ\"מ."]]],[1900420212,"לעורר בחי' השמח' העצמי' שבנפש ממש הנ\"ל, וראי' ממש\"א נכנס יין יצא סוד<sup data-n=\"858\">25</sup> הרי יצא כל בחי' סוד והעלם דשמחת הנפש בעצמה לגילוי ביתר מכפי מדת המוח והלב ע\"י שמחת היין דוקא כו', וראי' ממה שיצא סוד החכמו' בזקני' ודרדקי מיין הישן שהוא מפני שיין המשמח את הלב עולה לשמח עצם הנפש ממש כו' שמזה יבא לפתוח בחי' מקור החכמו' הרבה יותר מכפי המדה שלו והיינו להוסיף כח רב בעצם כח השכל להמציא שכליי' חדשים שנק' סוד ממש, שז\"ש נכנס יין יצא סוד שהוא רזא דרזין שכל הנעלם כו' שלא הי' בא בגילוי לעולם כמ\"ש במ\"א ע\"פ כי טובים דודיך מיין<sup data-n=\"859\">26</sup> כו', והוא רק מצד שהיין משמח לנפש עצמה והשמחה של הנפש עצמה עושה גילוי ההעלם גם מה שבהעלם ביותר כי טבע השמחה לגלות הצפון ונעלם ובשמחה העצמי' נגלה כל בחי' הפנימי' והעצמי' שהוא בהעלם גדול כו' וממילא יוסיף כח התגלות השכל כו'. אך זהו מלמטלמ\"ע מהשמח' שבלב דיין ישמח לבב אנוש הרבה יותר משמח' שבמדות ושכל הנ\"ל שהרי עושה קיבוץ הדמים בפנים הרבה יותר מהארת הפנים שבאמצעות החכ' החדשה שחכ' אדם תאיר פניו מלמעלמ\"ט כמ\"ש במ\"א ע\"פ ויין ישמח<sup data-n=\"860\">27</sup> כו' להצהיל פני' כו' לפני שפנימי' השמחה שבלב מגיע בשמחת עצם הנפש ממש כמו השמח' העצמי' הבאה פתאום מלמעלמ\"ט כו' (וכמו במ\"ת שעל כל דיבור<sup data-n=\"861\">28</sup> פרחה נשמתן מרוב שמחה ותענוג שבלב באו\"ח מלמטלמ\"ע, וכן האירו פניהם בשמח' דאור פניך כו' שזהו מלמעלמ\"ט בפנימי' המוח שנמשך ללב משום דפנימי' המוח מתאחד עם פנימי' הלב יחד בין בשמח' שמלמעלמ\"ט ובין בשמח' שמלמטלמ\"ע ובמ\"ת היו שניהם יחד כו' דבאור פניך כו', וכך הוא השמחה בד\"ת ובשמח' של מצוה או\"י ואו\"ח יחד והן בלתי מורכבי' ומוגבלי' כלל וד\"ל).\n<b>וזהו\"ע</b> ההפרש בין שמח' שביין בזמן בהמ\"ק לזמן הגלות, דע\"י היין המשמח שמעורר לשמח' האלקי' שיצא מן ההעלם לגילוי הנ\"ל הי' בזמן בהמ\"ק בתכלית ההתכללו' שגם יין המשמח בבחי' העלאה מלמטלמ\"ע נתאחד בשמחה האלקי' בלי שום הפרש כלל, וע\"כ גם על השמחה שנכנס יין יצא סוד הנעלם בשמחה האלקי' בבחי' או\"ח שייך לומר אשר ברא מאין האלקי ליש כמו בשמח' הבאה מלמעלמ\"ט ממש, וכמו השמח' על היין בניסוך היין בשיר הלוים על הקרבן כו' שהוא ע\"י שמחה של מצוה דקרבן והיין בו נגלה שמחה האלקי' ממש, אבל משחרב בהמ\"ק נתעלם ונתלבש השמח' אלקי' בלבוש זר",[["858","25","<b>נכנס יין יצא סוד</b>: עירובין סד, א."],["859","26","<b>במ\"א ע\"פ כי טובים דודיך מיין</b>: ראה תו\"א נב, ד. ס' מאמרי אדה\"ז על כתובים ח\"ב ע' קו ואילך. ס' תקס\"ה ח\"א ע' רב ואילך."],["860","27","<b>במ\"א ע\"פ ויין ישמח</b>: תהלים קד, טו. ד\"ה צאינה וראינה — בסה\"מ תקס\"ז ע' קעה ואילך וע' קפא ואילך. ומקבילו בלקו\"ת שה\"ש כו, א ואילך. ס' מאמרי אדהאמ\"צ נ\"ך (שה\"ש) ע' רסו ואילך."],["861","28","<b>במ\"ת שעל כל דיבור</b>: שבת פח, ב."]]],[1900420213,"דשמחה גשמי', ואע\"פ שעושה התעוררו' השמחה אלקי' מאין האלקי' ליש אבל הוא בדרך התלבשות בהעלם גדול בשמח' היין שבלב הגשמי כנ\"ל, ועכ\"ז הרי עכ\"פ ישנה לשמח' האלקי' ביין כנ\"ל בפי' ביין במה שיש בגניזה ובהעלם ביין כו', ולזה שייך לומר אשר ברא יש מאין גם עכשיו בשמחת היין שבשמחה של מצוה דחתן וכלה לפי שעכ\"פ ודאי נכנס יין יצא סוד שהוא שמחה האלקי' להתלבש בלבוש דשמחה זו שביין שזהו ג\"כ מאין ליש רק שהוא בא בהעלם והתלבשות בשמחה שביין אבל בנה\"א יצא מן ההעלם לגילוי כו' וד\"ל.\n[ה] <b>והנה</b> עדיין י\"ל למה מברכי' אשר ברא ששון ושמחה בשמחת חו\"כ דוקא וכמ\"ש אשר ברא שו\"ש חו\"כ כו' דמשמע שיש להם שייכות זע\"ז כו'. אך הנה כל ענין הנ\"ל בענין וטעם התגלות השמחה האלקי' הנ\"ל שנק' בריאה מאין ליש הוא ע\"י בחי' שמח' דחו\"כ דוקא. ותחלה י\"ל פי' וענין חתן וכלה, להיות ידוע בפי' כל\"ה מל' כלתה נפשי<sup data-n=\"862\">29</sup> וגם פי' כל\"ה כל ה\"א כלולה מנש\"ב כו'. והנה ענין כלתה נפשי הוא בחי' התשוקה והתכללות בבחי' רצוא כמ\"ש והחיות רו\"ש<sup data-n=\"863\">30</sup>, והן כללות נש\"י שהן מוסרים נפשם בבחי' רצוא באחדות פשוטה כניצוץ העולה מאלי' ליכלל במקור האש היסודי, וכמ\"ש בזוהר ע\"פ אלקי' אל דמי לך דנהורא תתאה קארי תדיר<sup data-n=\"864\">31</sup> לנהו\"ע ולא שכיך לעלמין, וכאור הנר שיש בו עלי' והסתלקות תמיד וחוזר ושב אל הפתילה כו', וכך הוא בחי' נשמ' האלקי' בפרט ובכלל וכמ\"ש במדרש למה נק' נשמה<sup data-n=\"865\">32</sup> ל' נשימ\"ה לפי שעל כל נשימ\"ה ונשימה רוצה הנשמה ליפרד מהגוף וכמ\"ש והחיות רו\"ש אך כאשר הנשמה רואה השכינה למטה בבחי' רו\"ש אומר' דיו לעבד להיות כרבו כו'. וביאור הדברי' ידוע דנשמה כללי' הוא בחי' מל' דאצי' שמתלבשת בכל העולמו' כמו התלבשות הנפש האלקי' בגוף וכמא' מה הקב\"ה ממלא<sup data-n=\"866\">33</sup> כו' כך הנשמה כו', והנה מקום משכן הנשמ' במוח החכ' ומתפשטת באף וכמ\"ש ויפח באפיו נ\"ח<sup data-n=\"867\">34</sup> וגם מתפשט' ברוח החיים שבלב כו', וזהו שע\"כ נשימה כו' רוצה כו' שהוא החפץ והתשוקה ליכלל במקורה כאור הנר שעולה לשרשו (באויר המקור לאור), אך מפני שגם מקור חוצבה שהוא בחי' המל' המחי' הכל ג\"כ בבחי' רו\"ש היינו שאחר הצמצום והסתלקות דוקא חוזר ונמשך ומתפשט בעולמו' וכמ\"ש והחיות רו\"ש בכללות וכמ\"ש כברייתו של עולם<sup data-n=\"868\">35</sup> ברישא חשוכא כו'",[["862","29","<b>כלתה נפשי</b>: תהלים פד, ג."],["863","30","<b>והחיות רו\"ש</b>: יחזקאל א, יד."],["864","31","<b>בזוהר ע\"פ אלקי'. ֿ. דנהו\"ת קארי תדיר</b>: תהלים פג, ב. ראה זח\"ב קמ, א. זח\"א קעח, ב. עז, ב. פו, ב."],["865","32","<b>במדרש למה נק' נשמה. ֿ. שעל כל נשימה</b>: ראה ב\"ר פי\"ד, ט [וראה גם לעיל ח\"א ע' קלב. דברים ח\"ג ע' תת. סה\"מ תש\"ד ע' 254. וש\"נ]."],["866","33","<b>מה הקב\"ה ממלא</b>: ראה ברכות י, א. ויק\"ר פ\"ד, ח. מדרש תהלים קג, א. וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשצה: ”כדמיון הנשמה שממלא כו' ובגמרא אמרו להיפך מה הקב\"ה ממלא כו'\"."],["867","34","<b>ויפח באפיו נ\"ח</b>: בראשית ב, ז."],["868","35","<b>כברייתו של עולם</b>: שבת עז, ב."]]],[1900420214,"דכך היא המדה של המל' שנק' נהו\"ת דלא שכיך בבחי' רו\"ש ובזה דוקא מחי' הכל מאין ליש כידוע, וע\"כ אומר' הנשמו' דיו לעבד להיות כרבו שבצלם אלקים עשה את האדם<sup data-n=\"869\">36</sup> שהוא הנשמה מנש\"י כמ\"ש ואתה נפחת בי<sup data-n=\"870\">37</sup> ואתה משמרה בקרבי לבלתי תפרד ותצא כמו ע\"כ אתה חי<sup data-n=\"871\">38</sup> כו' כדי שיהי' גילוי אלקו' בתומ\"צ בבחי' שוב כמא' אם רץ לבך שוב לאחד כו' שהוא להיות בחי' בית קיבול להכיל ולקבל גילוי אור אלקי שבתומ\"צ היפוך ההסתלקו' וכליון דכלתה נפשי דרצוא הנ\"ל. וזהו ענין כלה בכליון דרץ לבך למס\"נ ואח\"כ שוב בבחי' כלי לקבל השפע, והוא פי' כל\"ה כל ה\"א שכלולה מכל אור ושפע דנש\"ב<sup data-n=\"872\">39</sup>* כמשי\"ת וד\"ל.\n<b>והנה</b> ידוע בפי' חת\"ן ל' חו\"ת דרגא<sup data-n=\"873\">40</sup> שהוא ירידת אור השפע מן המשפיע אל המקבל לבחי' כלה הנ\"ל, והוא בחי' שפע אור השמח' העליונה שנמשך מן ההעלם לגילוי בכלי המקבל שהיא הכלה, עד\"מ בנה\"א מה שתתמלא שמח' האלקי' זהו בא מכח אור המשפיע עלי' מלמע' והוא ירידת השמחה מבחי' ההעלם שנק' אין ובאה ונתלבשה בנה\"א בגילוי ובמורגש גדול, כך הוא למע' בכלה עליונה שמקבלת אור שמחה עליונה מהמשפיע שנק' חתן דאשה בעלה משמחה, והוא בהיות שכמו שיש יחוד חו\"כ בגשמי' כך יש יחוד חו\"כ ברוחניו' והוא בשרשם בבחי' המקיף תחלה והוא ביחוד חו\"כ תחת החופה דוקא אז יוכלו להתייחד אח\"כ בגשמי' להוליד בנים, ולזה גזרו או' דאין שמח' אלא בחופה<sup data-n=\"874\">41</sup> דוקא שזהו בחי' השמחה רוחני' שבבחי' מקיף דוקא שלא שייך לומר בה אשר ברא כו' יש מאין כו', ע\"כ מברכי' אשר ברא שתצא מן ההעלם לגילוי דוקא מאין ליש כמו ענין שמח' היין שמגלה הצפון שא' אין שמחה אלא ביין כנ\"ל, וזהו והוא כחתן<sup data-n=\"875\">42</sup> יוצא מחופתו ישיש כו' דבשעה שעומד בחופתו עם הכלה השמחה בהעלם ומקיף וכשיוצא מחופתו באה לידי גילוי אור להשפיע לכלה וכמ\"ש כמשוש חתן על כל\"ה כו', אבל השמחה שבחופה הוא המקור לגילוי שמחת חו\"כ אח\"כ.\n[ו] <b>ותחלה</b> י\"ל שרש ענין החופה כמ\"ש כי על כל כבוד חופה<sup data-n=\"876\">43</sup>, כבוד הוא ל\"ב נתיבות חכמה ויש כבוד עילאה וכבוד תתאה חכמה עילאה וחכמה",[["869","36","<b>שבצלם אלקים עשה את האדם</b>: בראשית א, כז."],["870","37","<b>ואתה נפחת בי</b>: ברכת ”אלקי נשמה\" [שם הנוסח: ”אתה נפחתה בי\" (אתה — בלא ו', נפחתה — בה'), וראה הנסמן ע\"ז באריכות בהמ\"מ בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'רעז]."],["871","38","<b>ע\"כ אתה חי. ֿ. אם רץ לבך שוב לאחד</b>: ע\"פ אבות פ\"ד מכ\"ב. ס' יצירה פ\"א מ\"ח, ובהנסמן עוד באוה\"ת יתרו ע' תתקעח וע' תתקפא ובהערת כ\"ק אדמו\"ר שליט\"א בסה\"מ תרנ\"ט ע' ריא."],["872","39","<b>דנש\"ב</b>: בכת\"י ב: דנש\"ב דחו\"ב."],["873","40","<b>חתן ל' חו\"ת דרגא</b>: ראה יבמות סג, א."],["874","41","<b>דאין שמחה אלא בחופה</b>: סוכה כה, ב."],["875","42","<b>והוא כחתן</b>: תהלים יט, ו."],["876","43","<b>כי על כל כבוד חופה</b>: ישעי' ד, ה. וראה לעיל ח\"א ע' א ואילך."]]],[1900420215,"תתאה ועל כל כבוד יש חופה בפ\"ע וכמ\"ש שאו שערים ראשיכם<sup data-n=\"877\">44</sup> ויבא מלך הכבוד כבוד נאצל כו' מי הוא זה כו' ה' צבאות הוא מה\"כ כו' בחי' כבוד נברא ח\"ת דמל' כו'. והענין הוא כידוע דהחכ' מאין תמצא<sup data-n=\"878\">45</sup> בבחי' מזל ונוצר דכתר ונוצר אותיות צנו\"ר שהולך האור בצמצום והעלם מבחי' אין כו', והטעם לזה הוא מפני שכל דבר הבא מבחי' אין והעלם צריך שיתעלם ויוסתר תחלה בלבוש מקיף והוא כמו החופה החופף מלמע' ואח\"כ יוצא לגילוי, וזהו שכ' על כל כבוד חופה כבוד דחכ' יוצא לגילוי ע\"י הסתר לבוש מקיף דחופה. ויובן זה עד\"מ במה שאנו רואים כאשר יעמיק אדם בדבר שכל וחכ' עמוקה ביותר מכלי שכלו שמפני עומקו ודקותו מאד אז לא יוכל להבין אותו עדיין בכלי מוחו וכ\"ש שלא יוכל להביאו בדיבור לזולתו, רק עכ\"ז לעצמו משיג אפס קצהו היינו רק שיש מציאות אור ואותיות שכל חדש וסברא חדשה וכמו ברק מבריק על כלי ההשגה ולא נכנס בכלי מוחו עדיין כי לא יוכל להמשיכו מן ההעלם והאין לגילוי בהשגה כו', והיינו מפני שאותו אור השכל העמוק ודק ביותר נסתר ונתעלם בבחי' מקיף דחכ' הנק' חופה שהוא לבוש המכסה מלמעלה מבלתי יוכל לבא לגילוי גמור רק בהעלם דמקיף נשאר עיקר נקוד' השכל כו', והטעם הוא לפי שזהו הכלל שכ\"ד הנמשך מבחי' אין והעלם לבא לידי גילוי נמשך עמו בתחלת יציאתו לבוש מקיף מלמע' להעלימו ולעכבו מלצאת אל הגילוי ואח\"כ יבא לידי גילוי כו' (וכמו על ראשי החיות רקיע<sup data-n=\"879\">46</sup> בחי' מקיף להעלים האור ואח\"כ בא לידי גילוי כו', וכמו\"כ יש לכל צדיק חופה בפ\"ע כו'), וכך הוא בהתהוות גילוי אור החכמ' מן ההעלם יש חופה תחלה כו', וכך הוא בגילוי חכ' שבדיבור שנק' כבוד תתאה כו' כמו עד\"מ גם לאחר שמבין לעצמו א\"א להביא בדיבור כ\"א ע\"י הסתר והעלם האור במדות בלב כו'. ועד\"ז יובן ג\"כ בענין השמחה שבחופה להיות מבואר למע' שהשמח' אלקי' שבבחי' עצם הנפש ממש היא באה ונמשכת מן ההעלם לגילוי והיינו מבחי' העלם עולם התענוג העליון, כידוע דהשמחה העצמי' היא גילוי התענוג העצמי והוא הנק' תענוג הפשוט ועצמי' שהוא בהעלם העצמי' ממש, וטרם שבאה השמחה בנפש בגילוי הי' תחלה כלולה בעצם התענוג הנעלם ונק' אין בעצם, ואי אפשר שיהי' גילוי השמחה כי אם ע\"י שיהי' לה לבוש מכסה שתתלבש ותתעלם תחלה כפי הכלל הנ\"ל שכל דבר הנמשך מבחי' אין הנעלם נמשך עמו בחי' לבוש להעלימו כו', ומלבד שהוא מעלימו ומסתירו עוד זאת שהלבוש ימנע אותו ויעכבהו מלבא אל הגילוי שלא יבא מאין ליש כ\"א ע\"י הלבוש שנק' חופה כו', וכך הוא בצאת השמחה העצמי' מהעלם התענוג הפשוט שבנפש יוצא עמה לבוש דחופה להסתירה ולעכבה מלצאת לגילוי כו' וד\"ל. ונמצא מובן עכ\"פ דבחי' השמחה",[["877","44","<b>שאו שערים ראשיכם</b>: תהלים כד, ז ואילך."],["878","45","<b>דהחכ' מאין תמצא. ֿ. ונוצר אותיות צנור</b>: איוב כח, יב. ראה תו\"א סט, ב. לקו\"ת מטות פג, א. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רמג. במדבר ח\"א ע' תלו. אגרות קודש מכ\"ק אדמו\"ר שליט\"א ח\"א ע' קכ."],["879","46","<b>על ראשי החיות רקיע. ֿ. יש לכל צדיק חופה בפ\"ע</b>: יחזקאל א, כב. ב\"ב עה, א."]]],[1900420216,"עליונה שבחופה היא בהעלם ועיכוב דוקא כדי שאח\"כ תצא לגילוי, והוא כאשר יוצא מחופתו שבאה השמחה העצמי' הזאת בגילוי שיהי' הכח ועוז מזה ביחוד חו\"כ בגשמי' להוליד כו', ולזה אמרו אין שמחה אלא בחופה דוקא דהיינו במה שגנוז ונעלם בחופה מבחי' ההעלם והאין דתענוג הפשוט (שהחופה הוא בחי' לבוש מסתיר לגבי העליון שהוא העלם עצם התענוג והשמחה העצמי וגם הוא חופף ומקיף על התחתון שהן חו\"כ שנעלמי' ומוסתרים יחד תחת החופה, ומזה היחוד דוקא יאיר אור השמח' ותענוג מורגש בגילוי אח\"כ כמו בבחי' המזל דונוצר כו' בעצם כח החכ' כו' שמזה יומשך כח התולדה ביחוד הגשמי כו' וד\"ל).\n<b>ויובן</b> זה בתוס' ביאור במה שאנו רואים בשמחה ותענוג המורכב שבא בחכ' שבמוח שגם הוא א\"א שיבא לגילוי בלב שנק' שמחת לבו כ\"א שיוסתר ויתעלם תחלה אור השמחה ועונג בכח השכל עצמו שהכח השכל עצמו יעכבנו ויעצרנו מלבא לגילוי ויסתירנו מעין כל רואה עד שאינו ניכר שיש שמח' ותענוג, שהרי אנו רואים שכל מי שכח שכלו חזק יותר יותר יוכל להעלים ולהסתיר לבחי' התפעלות השמחה והעונג שבמוח שתהי' בהעלם גדול, והוא מצד שיש בחי' לבוש ומכסה להעלימו ולעכבו מלצאת בגילוי בלב כלל כנ\"ל בשמח' העצמי', וגם להתפעלות שמח' הנפש בעצמה יש בכח השכל והרצון להעלימו ביותר, כמו שמחה עצמי' מבשורה טובה ביותר כשירא לגלות לזרים יעלימה ויסתירה בתכלית (אבל מי שאין כח שכלו חזק אין בכחו להעלים ולעצור השמח' והתענוג כמו הקטן וכה\"ג לפי שיגבר על כלי מוחו עוצם התפעלות השמחה). וכמו שאנו רואים בשמחה אלקית בעבודת ה' שיש ב' מיני שמחה, א' הבאה בגילוי ובמורגש רק לפי אופן ההתבוננות שז\"ש אם הבנים שמחה<sup data-n=\"880\">47</sup>, אבל השמחה הב' שבאה מבחי' ההעלם ואין שבעצמות הנפש שלמעלה מן כלי ההשגה הנה נהפוך הוא שהשגה וחכמה מכסים ומעלימים אורה לגמרי כי איך ישיג השכל והשגה לשמחה ועונג האלקי' שלמעלה מן השכל דלית מחשבה ושכל תפיסא בי' ואדרבא התפעלות זו שבשכל והשגה מסתירים אותה ומתעכב מלצאת משם לגילוי להיותה באה מבחי' ההעלם העצמי מטעם כלל הנ\"ל (וכל שכח שכלו חזק ביותר בהשגה אלקית יותר יעלימה ויסתירנה כנ\"ל, משא\"כ מי שדעתו וכח שכלו בהשגה אלקית קטן לא יוכל להסתירה כ\"כ ותצא לגילוי בלב מיד, וזהו סיבת התפעלות יתירה מעצמות הנפש שתמצא בלב קטני הדעת הרבה יותר מערך ההשגה שבמוח כו', אך גם בחזקי הדעת כשיגביר ויצא השמח' ועונג העצמי' יבא מזה התפעלות יתירה כמשי\"ת). וזהו מ\"ש אז תתענג על ה'<sup data-n=\"881\">48</sup> וי\"ל איך יתכן העונג על ש' הוי', אך ידוע דש' הוי' י\"ה הוא חו\"ב כו' ושמח' ועונג העצמי הוא למע' מי\"ה ומכוס' ונעלם בי\"ה, וע\"כ הוא",[["880","47","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["881","48","<b>אז תתענג על ה'</b>: ישעי' נח, יד."]]],[1900420217,"מתענג על הוי' בבחי' העלם בלבוש דחו\"ב ואח\"כ יוצא לגילוי מן הלבוש דחו\"ב שהקיפוה ועכבוה מלצאת בגילוי בלב כו' (והוא משום דבחי' שמח' ועונג הפשוט ה\"ז בבחי' עצמו' אא\"ס שלמע' מש' הוי' דלית מחשבה תפיסא בי' כלל כידוע).\n[ז] <b>ובכ\"ז</b> יובן מ\"ש והוא כחתן יוצא מחופתו ישיש כגבור כו'. דהנה מבואר למעלה בענין אין שמחה אלא בחופה שהטעם הוא לפי שבחי' השמחה העצמית היתה כלולה בהעלם התעה\"פ ונתעלמה ונתכסה בלבוש דחופה ויוצא לגילוי מהעלם ואין, וזהו הכלל בכ\"ד הבא מההעלם ואין כו' כאשר מתכסה ונעלם ומתעכב מלצאת לגילוי אח\"כ כשיוצא מן ההעלם הוא יוצא בתגבורת גדולה ביותר, כמשל זריחת אור השמש בשחר שיבקע את החשך שברקיע שקדם לו שהוא מאיר בתוקף וגבו' יתירה, כי מצד ההכבה<sup data-n=\"882\">49</sup>* והמנעת אורו בתחלה גורם ריבוי אור ההתגברות בצאתו, וכמו ואוהביו כצאת השמש בגבורתו<sup data-n=\"883\">50</sup> והוא בצאת השמש על הארץ בשחר שבוקע ויוצא מן הרקיע (וכמשל החץ בקלע וכו'), וכמו עד\"מ כשמעמידים מסך בפני מים רבים זמן רב אז כאשר יסירו המסך יצאו בשאון ורעש גדול ובהתגברות מאד לפי שנתעכבו הרבה כו', וכך כ\"ד המעוכב ביותר בהעלם כשיבא לגילוי בא בתגבורת והתפעלות יתירה כמו היוצא מן המאסר כו', וכמו בחכמה חדשה כל שנתעכב תחלה בהעלם כח המשכיל יוצא לגילוי ההשגה בתגבורת יתירה, והוא כמו המעיין המתגבר ביותר מצד רוב העיכוב בהעלם כו' וד\"ל. ועוד טעם שני והכל אחד לפי שכ\"ד הבא מבחי' אין והעלם להיות בחי' האין המוחלט הוא דבר חידוש גדול ונורא מאד כשבא לגילוי ע\"כ צריך שיתעלם בעיכוב רב, וכמו קולות וברקים שהי' במ\"ת קודם יו\"ד הדברות שהי' בהם בהעלם כל יו\"ד הדברות שאח\"כ לפי שהי' אז גילוי אא\"ס מן ההעלם בא' אנכי כו' שזהו חידוש גדול ונורא מאד בגילוי יש מאין המוחלט כאשר אין המוחלט יבא לידי גילוי לעיני בשר כו' ע\"כ הי' קולות וברקי' תחלה וקול השופר הולך וחזק כו', וכה\"ג אנו רואים בכל התחדשות מופלגת בדבר נס נפלא שרואה אדם שהוא למעלה מעין שכלו ונתגלה לו פתאום שזהו בחי' ההתחדשות יש מאין האלקית יבא לכלל התפעלות קול רעש גדול מאד כו' להיות הדבר בא מבחי' אין והעלם דוקא וד\"ל.\n<b>וכך</b> יובן ג\"כ בענין השמחה העצמית הנ\"ל מפני שנתעכבו בהעלם לבוש דחופה ע\"כ כאשר החתן יוצא מחופתו אז הוא בא בהתגברות אור השמחה ביותר, והוא מב' טעמים הנ\"ל וד\"ל. וז\"ש ישיש כגבור לרוץ אורח בחי' נוק' שזהו עוצם גבו' אור השפע דמשפיע למקבל מצד שנתעכב בחופתו ויוצא",[["882","49","<b>ההכבה</b>: כן הוא בכת\"י המעתיק. ואוצ\"ל: ההעכבה."],["883","50","<b>ואוהביו כצאת השמש בגבורתו</b>: שופטים ח, לא."]]],[1900420218,"מחופתו כו' וכמ\"ש לשמש שם אהל במכסה ולבוש להעלימו בתחלה ע\"כ בצאתו יתגבר ביותר, וז\"ש והוא כחתן דקאי על השמש דסמיך לי' וכמ\"ש במ\"א<sup data-n=\"884\">51</sup>. וזהו כמשוש חתן<sup data-n=\"885\">52</sup> על כלה שזהו בצאתו מחופתו כו' ישיש עליך אלקיך, והוא לע\"ל דוקא שתתגלה השמחה מן ההעלם דלבוש דחופה המסתיר, וכידוע בענין ביום חתונתו זה מ\"ת שנק' אירוסין בחופה וקידושין וביום שמחת לבו לע\"ל דוקא שנק' נשואין ביחוד גמור וע\"כ אז נא' כמשוש חתן כו' ישיש עליך אלקיך וכמ\"ש ישיש כגבור כו' וכ' ביום ההוא תקראי לי אישי כו' ועתה השמחה דחו\"כ בהעלם דחופה כו' וד\"ל. וזהו והוא כחתן יוצא מחופתו דהיינו הקב\"ה שנק' חתן וכנ\"י נק' כלה כידוע וקאי לע\"ל שיוצא מחופתו דעתה וישיש כו'.\n[ח] <b>וזהו</b> מה שאו' קול מצהלות חתנים מחופתם כו', פי' מצהלות דהיינו קול צהלה ורנה כמו צהלי ורוני בת ציון<sup data-n=\"886\">53</sup> כו' וכמו והעיר שושן צהלה ושמחה כו', שזהו\"ע תגבורת השמחה והחדוה שיבא מזה לקול רנה וצהלה, והוא בא מצד העיכוב דחתן בהעלם דחופה כנ\"ל ע\"כ א' קול מצהלות חתנים מחופתם שזהו כשיוצאים מחופתן דוקא מטעם הנ\"ל וד\"ל. אך מ\"ש חתנים ל' רבים, הענין הוא, דכמו שבחי' השמחה האלקית העצמית שבעצם הנפש שבאה מן העלם התענוג הרי היא באה מאין בדרך עיכוב כו' (ולע\"ל תצא לגילוי כשיהי' גילוי אא\"ס למטה כמו למע' ממש כמ\"ש שם נשמחה בו<sup data-n=\"887\">54</sup> בו ממש, והוא בחי' גילוי השמחה העצמי' בבחי' יחידה דכנ\"י כו'), כך הוא גם למטה יותר, והוא בבחי' התענוג והשמחה האלקית שבא במוחין דחו\"ב בשכל והתבוננות, ג\"ז מתעכב ונסתר ונעלם ביותר כנ\"ל שכח השכל יעצור ויעכב כו' וגם עצם ההשגה מעלים ומסתיר כו', וכפי כלל הנ\"ל דכ\"ד המעוכב ביותר והוא בא מבחי' אין והעלם כו' אח\"כ כשיוצא לגילוי הוא יוצא ובא בתגבורת יתירה כו', וכך הוא ביציאת השמחה האלקית שנסתר ומתעכב במוחין דחו\"ב כשבא לגילוי בלב זהו ג\"כ כמו חידוש יש מאין שבא בתגבורת גדולה בלב ביתר מכפי המדה מאד כידוע. וזהו ג\"כ ענין כחתן יוצא מחופתו דחו\"ב לגילוי בלב ויוצא ל' הוה כו' שזהו גם עכשיו כו', אך מפני שיוצא מתגבורת יתירה לא הי' כח במדות שבלב להכיל כל השמחה האלקית שהי' בהעלם בחו\"ב שנק' חתן שיורד ומשפיע ללב, וזהו שנק' כלה כלתה נפשי שהיא באה לכלות הנפש, כמו עד\"מ שרה שפרחה נשמתה מבשורת יצחק<sup data-n=\"888\">55</sup> וכה\"ג, אך הכח שבלב להכיל",[["884","51","<b>והוא כחתן דקאי על השמש דסמיך לי' וכמ\"ש במ\"א</b>: ד\"ה לסוסתי, נדפס לעיל ח\"א ע' מז ואילך."],["885","52","<b>כמשוש חתן. ֿ. ביום ההוא תקראי לי אישי</b>: ע\"פ ישעי' סב, ה [ופיוט ”לכה דודי\"] הושע ב, יח."],["886","53","<b>צהלי ורוני בת ציון. ֿ. והעיר שושן צהלה ושמחה</b>: ע\"פ ישעי' יב, ו. אסתר ח, טו."],["887","54","<b>שם נשמחה בו</b>: תהלים סו, ו."],["888","55","<b>שרה שפרחה נשמתה מבשורת יצחק</b>: כן הוא הלשון בסה\"מ תרמ\"ט ע' רמח, וכותב ע\"ז בהערת כ\"ק אדמו\"ר שליט\"א שם: אינו מפרט האם מבשורה המצערת שנעקד (ב\"ר פנ\"ח, ה. וראה פדר\"א פל\"ב) — שגם מזה ראי' להמבואר בפנים — או (כדמשמע קצת מההמשך) מרוב שמחה (כפירוש ריב\"א עה\"ת (ר\"פ חיי\"ש). — ומביא דוגמא מכתובות סב, ב — או כמסופר בס' הישר). ע\"כ. בכתובות שם: רבי חנניה בן חכינאי כו' אזל יתיב תרי סרי שני בבי רב עד דאתי אישתנו שבילי דמתא כו' הוה יתיבא דביתהו כו' חזיתי' כו' פרח רוחה כו'. ובס' מאמרי אדה\"ז ענינים ע' קנט מביא ג\"כ מהגמ' בכתובות. וראה לעיל קרוב לתחילת המאמר."]]],[1900420219,"הוא מצד שרשה בעצם יחידה שבנפש שמשם באה גם השמחה העצמי' מן ההעלם לגילוי וכ\"ש שמחה שבחו\"ב כו' ע\"כ תוכל להכיל גם לע\"ל וכמ\"ש וביום שמחת לבו<sup data-n=\"889\">56</sup> דוקא שמתיישב בלבו כו' וד\"ל. וזהו מה שנק' כלה ע\"ש שכלולה מהכל והיינו מכל אשר בעצם הנפש בהעלם התענוג ורצון כו', וזהו ג\"כ פי' כלה כל ה\"א היינו נש\"ב שמקבלת מה\"א דבינה והוא מ\"ש אז תתענג על ה'<sup data-n=\"890\">57</sup> שבא בגילוי בהבל הלב<sup data-n=\"891\">58</sup>*, וזהו שמסיים באשר ברא משמח חתן עם הכלה בשביל הכלה דוקא וד\"ל.\n[ט] <b>ומעתה</b> י\"ל מ\"ש עוד ונערים ממשתה נגינתם, דהנה מ\"ש חתנים ל' רבים היינו בחי' נר\"ן ח\"י שראשית הירידה דשמחה העצמית מהעלם התענוג דבחי' חי' יחידה, והוא בחי' חתן ראשון שיורד מהעלם לגילוי, ועד\"ז בחי' חתן שני מההעלם דחו\"ב למדות שבלב שזהו מן הנשמה שבמוח לרוח שבלב, וכן ברוח המדות שבלב מתעלם ואח\"כ יוצא לגילוי במחשבה וממחשבה לדבור כו', ולמעלה היינו חתנים בבחי' נר\"ן דאצי' עד מאצי' לבריאה שעז\"א כחתן יוצא מחופתו ג\"כ. אך בחי' נערים היינו בחי' מחשבה ודבור מסטרא דבריאה וסנדל דיצירה כו' כידוע, וע\"ד הנ\"ל בחופתן דחתנים דנר\"ן דאצי' כך הוא בבחי' נערים דבריאה ויצירה, רק שהחופה הוא בא מן ההעלם לגילוי מלמעלמ\"ט בבחי' או\"י דמשפיע אל המקבל בבחי' חו\"כ כנ\"ל, ונערים ממשתה נגינתם הוא בבחי' או\"ח שבא מלמטלמ\"ע בבחי' השמחה שבמשתה היין, כנ\"ל בענין אין שמחה אלא ביין לפי שנכנס יין יצא סוד, וכמו אגברו חמרא אדרדקי דוקא כי היכי דלימרו כו' שמפני שדרדקי הן בקטנות המוחין מאד ונק' אנפי זוטרי שהן בחי' נערים כו' א\"א שיאיר בהן תוס' אור חדש ממקור השכל הנעלם מלמעלה למטה כחכמת אדם גדול שבא מאין ליש ע\"י שמחה שבחופה בחתנים, אלא ע\"י יין המשמח הלב ועולה מלמטה למעלה במוח ועושה שמחת הנפש כו' עד שיצא מן ההעלם לגילוי בתוס' אור רב ביותר, וכמ\"ש במ\"א בענין יין ישמח לבב אנו\"ש<sup data-n=\"892\">59</sup> דוקא אנוש דקטנות שהן בחי' נערים הנ\"ל, וכנ\"ל בפי' ביין במה שגנוז ונעלם בתוך היין שיצא סוד ה\"ז ג\"כ בבחי' עיכוב והעלם, וכפי כלל הנ\"ל שכ\"ד שבא מן ההעלם מלמעלמ\"ט בדרך עיכוב יתגבר אח\"כ ביותר, וכך הוא בבחי' או\"ח דמשתה היין מלמטלמ\"ע (כמו החץ שמתעכב",[["889","56","<b>וביום שמחת לבו</b>: שה\"ש ג, יא."],["890","57","<b>אז תתענג על ה'</b>: ראה לעיל סו\"ס ו."],["891","58","<b>הלב</b>: בכת\"י ב: הלב לשון להב."],["892","59","<b>במ\"א בענין יין ישמח לבב אנוש</b>: ד\"ה צאינה וראינה — בסה\"מ תקס\"ז ע' קע ואילך. ומקבילו בלקו\"ת שה\"ש כה א ואילך (וע\"ש כו, א). ס' מאמרי אדהאמ\"צ נ\"ך (שה\"ש) ע' רסו ואילך."]]],[1900420220,"בקלע וכה\"ג, וכמים תחתונים שעולין בהתגברות מלמטלמ\"ע כו'). וז\"ש ונערים ממשתה היינו שיוצאי' ממשתה נגינתם שיתגברו במעלה יתירה בתוס' אור חדש בכח החכמה משום שנכנס יין יצא הסוד היותר נעלם, ודוקא מצד בחי' קטנות שלהם במשתה נגינתם בשיר שע\"י היין ששם גנוז ומתעלם כל מה שיצא אח\"כ לגילוי כו', וכנ\"ל הטעם במצהלות חתנים מחופתן בהתגברות קול צהלה ורנה כו', כך הוא בנערים בקול משתה נגינתם משום דקאי אדסמיך לי' שא' מהרה ישמע כו' קול ששון וקול שמחה קול חתן וקול כלה, משום דעכשיו הקול ששון ושמחה חתן וכלה בהעלם דחופה כנ\"ל ואינו נשמע כלל, רק לע\"ל ישמע קול ששון ושמחה בגילוי מן ההעלם וכן קול חו\"כ (וכידוע שזהו טעם שתיקת הכלה כשאומר הרי את כו'), וכן ישמע קול מצהלות חתנים כשיוצאים מחופתן ברעש והתגברות ביותר, וכן ישמע קול משתה נגינת הנערים כשיבא לגילוי מן ההעלם שביין כשיצא הסוד, רק שזהו בבחי' או\"ח ויש לו יתרון על בחי' או\"י וכמ\"ש במ\"א ע\"פ ויין ישמח להצהיל<sup data-n=\"893\">60</sup> כו' וד\"ל (ומכל הנ\"ל יובן בשמחה שבחופה ושמחה שביין ששמחה שבחופה הוא בחי' מקיף דאו\"י ושמחה שביין הוא מקיף דאו\"ח, וזהו ששני מאמרים הללו דאין שמחה אלא בחופה ואין שמחה אלא ביין [אין] סותרין כלל שזהו בבחי' או\"י וזהו בבחי' או\"ח ושניהם אמת וד\"ל).\n[י] <b>והנה</b> אחר שמובן מכ\"ז ענין קול מצהלות חתנים שהוא מלמעלמ\"ט ומשתה דנערים מלמטלמ\"ע כו', מעתה י\"ל הטעם שנק' בשם נערים והלא אמרו ע\"פ נער הייתי<sup data-n=\"894\">61</sup> גם זקנתי שרו של עולם אמרו עכ\"פ א' גם זקנתי ונערים אלה משמע שהם נערים לעולם כו'. הענין הוא כידוע בזוהר ע\"פ אנוש כחציר ימיו<sup data-n=\"895\">62</sup> שזהו בחי' ששת יומין דחול שנקראים ו' ימי המעשה<sup data-n=\"896\">63</sup>. דהנה ידוע בענין ששת ימים עשה כו' שהן ו' יומין עילאין דאצי' שכוללים ו' אלפי שנין כו' כמ\"ש כי אלף שנים בעיניך כיום כו', ולמטה היינו ו' יומין דחול שבכל יום מחדש מעשה בראשית, וכידוע דו\"ק דמל' דאצי' יורדין בבי\"ע לחדש בכל יום כל העולמות מאין ליש ממש, ובחי' מדות שבמל' דאצי' כשיורד לבחי' עולם המחשבה שהוא בחי' עולם הבריאה נק' בשם מט\"ט שהוא ו\"ק דבריא' כו', ומבחי' ו\"ק דבריאה יורד עוד ונמשך לבחי' יצירה שהוא בחי' עולם הדבור ונקרא סנדל והן הנקראים נערים ע\"ד שרו של עולם עד עולם העשי' כו'. והנה ידוע שאור האלקי' דאצי' שבא בעולם הבריאה ויצירה שהן בחי' נערים הנ\"ל הוא בא במדה ושיעור וגבול, והוא נק' ו' ימי המעשה שהוא רק בשביל חידוש מע\"ב מאין ליש בכל עולם לפי ערכו עד עולם העשי', ואור שפע זו מתחדש",[["893","60","<b>וכמ\"ש במ\"א ע\"פ ויין ישמח להצהיל</b>: ראה הנסמן בהערה הקודמת."],["894","61","<b>נער הייתי. ֿ. שרו של עולם אמרו</b>: תהלים לז, כה. יבמות טז, ב ותוס' שם."],["895","62","<b>בזוהר ע\"פ אנוש כחציר ימיו</b>: תהלים קג, טו. וראה זח\"ג רטז, ב. ריז, ב."],["896","63","<b>ששת ימים עשה. ֿ. כי אלף שנים</b>: יתרו כ, יא. תהלים צ, ד."]]],[1900420221,"בחידוש גמור בכל יום, וביום השבת ששובת ונח ממלאכתו כו' הוא בחי' עלי' המל' מבי\"ע כידוע ואז הוא כמו שבת בראשית כידוע, וא\"כ כל בחי' ההשתלשלות דששת ימים במחשבה ודיבור שנקראים נערים שהן מט\"ט וסנד\"ל חוזרים למקורם באצי' ומתבטלים שם ממציאותן כו' וחוזרין ויורדין בו' ימים דחול שאחר השבת ומתחדשים מחדש ממש כאלו באו מאין ליש בקרוב, כמו עד\"מ המחשבה ודבור שמתחדשים ממדות שבלב וכה\"ג. ונמצא מובן שמצד בחי' ההתחדשות שמתחדשים בחי' ו\"ק דבריאה ויצירה בכל ו' יומין דחול ומדי שבת מתבטלים ועולים וחוזרים ומתחדשים נקראים נערים בתמידות שאין להם זמן שיזקינו כלל רק ו' ימים לבד כו' ולא יבואו לכלל זקנה לעולם מאחר שבכל שבת מתחדשים בבחי' בריאה מאין ליש כו', וזהו אנוש כחציר כו', וע\"כ נקראים נערים תמיד, כמו עד\"מ הנער שמתחדש ימיו שמקרוב בא ונולד מבחי' האין ליש כו' (שבזה יש בו יתרון מעלה מן הזקן שנתרחק יותר מבחי' האין כו').\n<b>אך</b> הנה אין זה רק בבחי' מט\"ט וסנדל דבריאה ויצירה או דיצירה ועשי' שהן מתחדשים ממל' דאצי' כנ\"ל, אבל בבחי' מל' דאצי' עצמה הגם שיורדת בבריאה בהיכל קד\"ק להיות שם יחו\"ע דזו\"נ דאצי' (כמ\"ש בכוונת היחוד דגאולה לתפלה<sup data-n=\"897\">64</sup>), הרי נק' בשם חו\"כ, והן כנ\"י שנק' כלה, ולפעמים נק' בשם בנים, ובחי' נערים הנ\"ל נק' בשם עבדים כמ\"ש בזוהר עמ\"ש עבדו זקן ביתו המושל כו' שהוא בחי' מט\"ט דבריאה ויצירה כו', ולפעמים מקבלים כנ\"י מבחי' נערים הנ\"ל וכמ\"ש ונתתי נערים שריהם<sup data-n=\"898\">65</sup>, שזהו בזמן הגלות דכנ\"י בע' שרים שמקבלים מחיצוניות דחיצוניות דמלכות דבריאה ויצירה, דנערים הנ\"ל בירידת ההשתלשלות מאד עד מל' דמל' דעשי' דמלך אלקים על גוים כו' אז נק' ג\"כ כנ\"י בשם עבדים כמ\"ש כי לי בנ\"י עבדים<sup data-n=\"899\">66</sup> ואנו אומרים מלכנו כי אנו עמך כו', וכאשר מקבלים כנ\"י מבחי' מל' דאצי' כמו שהוא מאיר מאצי' לבריאה בשבת שנק' יחוד חו\"כ וכל ה\"א וכה\"ג אז נק' כנ\"י בשם בנים ונקראים בני מלכים ולא בשם עבד כו' ואו' אבינו כו' וד\"ל.\n<b>אך</b> הנה לע\"ל יהי' עלי' גדולה לנערים הנ\"ל שיעלו למקור חוצבם בו\"ק דז\"א דאצי', ומשם למע' מעלה בבחי' או\"ח דיין שיצא סוד במשתה נגינתן כנ\"ל כמו שיוצאים החתנים מחופתן מלמעלה למטה בצהלה ורנה כו'. וז\"ש בקול מצהלות חתנים ישמע לע\"ל וכן ישמע קול נערים ממשתה נגינתם ממש בבחי' או\"ח כו', אזי מה שהי' בזמה\"ג דנערים היו שריהם בתכלית הקטנות יצאו",[["897","64","<b>כמ\"ש בכוונת היחוד דגאולה לתפלה</b>: ראה פע\"ח שער הק\"ש פכ\"ט. ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תז [ובהמ\"מ שם]."],["898","65","<b>בזוהר עמ\"ש עבדו זקן ביתו. ֿ. ונתתי נערים שריהם</b>: זח\"א קכו, ב. חיי\"ש כד, ב. ישעי' ג, ד."],["899","66","<b>כי לי בנ\"י עבדים. ֿ. בני מלכים</b>: ויקרא כה, נה. שבת צז, ב."]]],[1900420222,"ממשתה נגינתם למעלה בקול שיר בגילוי אור השמחה ושירה חדשה בתוס' אור רב וגדול, והוא מ\"ש לע\"ל דוקא נער הייתי גם זקנתי זה הפ' שרו של עולם הבריאה ויצירה אמרו שהוא בחי' מט\"ט וסנדל שהיו בבחי' נער דקטנות בו' אלפי שנין בכל ו' יומין דחול כו' כנ\"ל, גם זקנתי בבחי' גדלות המוחי' דחו\"ב למע' מעלה באלף הז' שאז עליי' כל העולמות עד שיבא לכלל זקנה זקן שקנה חכמה היפך מה שהי' בבחי' נער תמיד, וזקנתי זה לא בא מרוב ימים דו' אלפי שנין כו' רק מצד בחי' העלי' בשיר חדש במשתה נגינתם כשיוצאים בבחי' או\"ח, וזהו ונערים ממשתה נגינתם וד\"ל.\n[יא] <b>ולהבין</b> זה בתוס' ביאור ומה שייך לסמוך משתה נגינתם דנערים לקול מצהלות חתנים דוקא כנ\"ל, הנה ארז\"ל ע\"פ זה נער הייתי<sup data-n=\"900\">67</sup> גם זקנתי דאי אפשר לומר דקודב\"ה אמרו דמי איכא זקנה קמי' אלא שרו של עולם אמרו כו', ויש לדקדק דמצינו במ\"ת שנדמה להם כזקן<sup data-n=\"901\">68</sup> וגם מקרא מפורש ועתיק יומין יתיב כו' ולמה לא יתפרש פסוק זה בקודב\"ה כו', וידוע דקוב\"ה הוא בחי' ז\"א דאצי' ובמ\"ת הי' בבחי' גדלות המוחין דא\"א בחי' זקן שקנה חכמה כו' וד\"ל. ויש להקדים תחלה ענין נערים הנ\"ל במ\"ש ונתתי נערים שריהם בזמה\"ג דוקא. דהנה מבואר למעלה בבחי' מט\"ט וסנדל דבריאה ויצירה או יצירה ועשי' שבהם ועל ידם מתנהג כל אור ושפע דאצי' בעולמות דיצירה ועשי' עד עוה\"ז השפל דע' שרים דנוג\"ה כו', והיינו מה שאנו רואים בחי' הסתר אלקות ביותר בעוה\"ז שמוסתר אור ההשגחה אלקית בתכלית הצמצום וההעלם אחר העלם במאד והוא במה שבא בהתלבשות בדרכי הטבע האנושי' (וכידוע דאלקים גימטריא הטב\"ע<sup data-n=\"902\">69</sup> וכמ\"ש אתה אל מסתתר<sup data-n=\"903\">70</sup> כו'), ואע\"פ שנאמר משמים הביט כו' ממכון שבתו השגיח על כל כו' וכתיב עיניך פקוחות כו' וגם בצבא השמים א' וכמצביי' עביד כו', אך כ\"ז מלובש בהסתר גדול מאד, וראי' לזה ממ\"ש אותותינו לא ראינו<sup data-n=\"904\">71</sup> כו' וזה קאי בזמה\"ג כידוע. דהנה באמת יש להפליא בזה שהרי באמת לגדולתו אין חקר<sup data-n=\"905\">72</sup> למעלה ולמטה כלל דהיינו שבחי' התפשטות אא\"ס למטה מטה ג\"כ עד אין תכלית כמו שהוא למעלה ממש וכמ\"ש המגביהי לשבת<sup data-n=\"906\">73</sup> המשפילי לראות בשמים ובארץ כו', וא\"כ ודאי ההתנהגות גם בעולם היותר תחתון הוא מבחי' א\"ס עצמו שהוא מבחי' גדולתו",[["900","67","<b>ארז\"ל ע\"פ זה נער הייתי</b>: ראה לעיל ריש ס\"י. וש\"נ."],["901","68","<b>במ\"ת שנדמה להם כזקן. ֿ. ועתיק יומין יתיב</b>: ראה מכילתא בשלח טו, ג [ובהנסמן עוד בס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שפה. ח\"ד ס\"ע א'שיב]. דניאל ז, ט."],["902","69","<b>דאלקי' גימט' הטבע</b>: פרדס שי\"ב פ\"ב. שער היחוד והאמונה ריש פ\"ו. ועוד."],["903","70","<b>אתה אל מסתתר. ֿ. משמים הביט. ֿ. עיניך פקוחות. ֿ. וכמצביי' עביד</b>: ישעי' מה, טו. תהלים לג, יג. ירמי' לב, יט. דניאל ד, לב."],["904","71","<b>אותותינו לא ראינו</b>: תהלים עד, ט."],["905","72","<b>לגדולתו אין חקר</b>: תהלים קמד, ג."],["906","73","<b>המגביהי לשבת</b>: תהלים קיג, ה."]]],[1900420223,"העצמי' וברצונו הפשוט שבעצמותו ממש, וכמו שהי' נראה לעין כל בדורות הראשונים בנסים ונפלאות גדולות שעשה בעוה\"ז בקי\"ס והירדן ואותות ומופתים שבמצרים כו' וכל הנפלאות שעשה במדבר וגם כל הנפלאות שבדורות הנביאים עד זמן בית שני, וגם אחר בית שני בימי התנאים ואמוראים ששמשו בב\"ק וכו' הי' גילוי נפלאות אותות ונסים רבים שיצאו מגדרי הטבע, והי' זה האור האלקי בא מן ההעלם לגילוי גמור עד שהי' מתקבל ונגלה לעין כל אדם מפני שהי' הדבר בא בגילוי גדול עד שהי' הדבר נאמן ומתאמת ומקובל אצל הכל ממש כמו עכשיו שנתאמת אצל הכל דרכי הטבע בגילוי גמור, משא\"כ עכשיו בזמה\"ג דכתיב אותותינו לא ראינו פי' אותותינו היינו אותן הנסים ונפלאות גדולות עצמן שהי' בימי הקדמונים ממש אין אנו רואים כלל בגילוי כמו שהי' אז כמו גילוי הטבע כו', והטעם הוא לפי שגם כל חפץ ורצה\"ע הפנימי בהנהגתו בעולמות בהשגחות האלקי' ג\"ז בא בהתלבשות והסתר גדול מאד שאינו נגלית רק ע\"פ לבוש דדרך הטבע שזהו הסתר גדול מאד מאד, ולבד זה מאד עמקו מחשבותיו ית' בהנהגות העולמות בענין עלי' וירידה במלכים וצבא השמים ובגלגולים דנשמות לפי אופן הרצון שלו בבחי' הבירורים דרפ\"ח ניצוצים כו' שנק' כבשי דרחמנא<sup data-n=\"907\">74</sup> כו', שהרי מאד מוסתר ענין וטעם הגליות הקשות ואשר ניתן רוב שפע לאומות העולם כו', וכן בפרטיות מאשר הרשעים מצליחים והצדיקים וכשרים נלחצים ויש ג\"כ נספה בלא משפט וכה\"ג כמ\"ש בזוהר על דמעת העשוקים<sup data-n=\"908\">75</sup> כו' וד\"ל. אך הנה כ\"ז מצד רוב ההשתלשלות עו\"ע בריבוי הצמצומים והעלמות עד שיבא ההנהגה וההשגחה ע\"י לבוש ש\"ק דטבע כמ\"ש אלביש כו' ושק אשים<sup data-n=\"909\">76</sup> כו' וד\"ל. ושרש הענין הוא מפני שירד אור האלקי' בצמצום וקטנות דנערי' דיצירה ועשי' שהוא בחי' קטנות המדות העליונות בחי' אנפי זוטרי כנ\"ל והן שרים על עולמות העליונים דיצירה ועשי' עד ע' שרים דק\"נ דעשי' כנ\"ל ונק' ו' יומין דחול דקטנות שנק' ו' ימי המעשה כנ\"ל ששרש שרשם בו' יומין דאצי' כנ\"ל ובחול יורדים ו\"ק דאצי' ומתלבשים בהם כנ\"ל וד\"ל.\n[יב] <b>והנה</b> מ\"ש ונתתי נערים שריהם בזמה\"ג שהן בתכלית הקטנות והירידה, הנה לע\"ל שיתעלו כל העולמות בכלל ובפרט בכל עו\"ע לפי ערכו הרי אז יתעלו גם בחי' נערים הנ\"ל, והיינו שיתעלו לשרש שרשם בבחי' ו' יומין דאצי' ותהי' אז הנהגת העולמות כולם במדות דז\"א דאצי' שהן ו' יומין עילאין בכל וימה\"מ דחול כמו שעכשיו בעולמות עליונים ותחתונים ע\"י בחי' הקטנות דנערים הנ\"ל. אך א\"כ אי\"ז עלי' כלל וכלל לנערים הנ\"ל מאחר שתהי' לע\"ל ההנהגות באמצעות המדות דאצי' ממש בעולם הנפרד א\"כ אין מקום כלל",[["907","74","<b>כבשי דרחמנא</b>: ברכות י, א."],["908","75","<b>בזוהר על דמעת העשוקים</b>: ראה זח\"ב קיג, א ואילך. זח\"ג רג, א."],["909","76","<b>אלביש כו' ושק אשים</b>: ישעי' נ, ג."]]],[1900420224,"לנערים להנהגות העולמות כי הרי יהיו בטלים ונכללים במדות דאצי' כטפה בים ולא יהיו נחשבים במציאות כלל כמו שנער קטן אין לו מקום כלל לגבי האדם הגדול כו', אין הענין כן, אלא הענין הוא שלא ישארו הנערים בבחי' הקטנות שלהם עד שלא יהי' שום שליטה והנהגה אז לנערים שא\"כ יבוטלו במציאות לגמרי, אלא אדרבא שיהי' עלי' לנערים דעכשיו להיות במדריגות מדות דאצי' ממש בבחי' מוחין דגדלות דחו\"ב שבמדות עליונות דז\"א כו' וע\"י דוקא יהי' הנהגות כל העולמות דבי\"ע כמו שעכשיו ההנהגות ע\"י בבחי' הקטנות לבד, ונמצא שאותן מדריגות דקטנות שלהם עכשיו זה עצמו יתעלה להיות בבחי' הגדלות המוחין דמדות דאצי', והוא ענין הבירור לאמיתתו שאותו הדבר עצמו שהי' בבחי' נפילה וקטנות הוא עצמו יתעלה להיות בעילוי גדול וינהג דרכו במוחין דגדלות ביותר (עד\"מ התינוק שמנהגיו במדותיו ושכלו בקטנות מאד כשחוק התינוקות, וכשמגדיל יעלו מדותיו ושכלו הן עצמן לבחי' תכלית הגדלות כו'), משא\"כ אם היו הנערים נשארים בקטנות שלהם אין זה בירור ועלי' כלל וד\"ל. וזש\"א נער הייתי גם זקנתי שאותו בחי' נער עצמו דבחי' הקטנות הוא שיעלה במדריגות דבחי' הזקנה שקנה חכמה שהוא גדלות המוחין דאו\"א שבמדות דז\"א כידוע ונקרא עבדו זקן ביתו כו', וכן הוא מ\"ש ישכיל עבדי<sup data-n=\"910\">77</sup> כו' ואע\"פ דקאי במשיח שנקרא בן אבל נקרא עבד שלמעלה מבן וזהו שישכיל עבדי וירום ונשא וגבה מאד למעלה מעלה שהוא בבחי' פנימיות ע\"י שנחשב מעולם הא\"ס כידוע וד\"ל. וזהו שאמר נער הייתי כו' שרו של עולם אמרו כו' דהיינו בבחי' העלי' דאו\"ח שנערים דקטנות יעלו לבחי' הגדלות דזקנה כנ\"ל, אבל בקוב\"ה שהוא בחי' ז\"א דאצי' עצמו מי איכא זקנה קמי' כו'. דהנה מבואר למעלה בענין קול מצהלות חתנים כו' שזהו בחי' הירידה דאו\"י מלמעלמ\"ט, והוא ענין אין שמחה אלא בחופה היפך משתה היין דנערים, והוא למעלה גם מבחי' זקנה כי בחי' זקנה אינו שייך רק בחכמה ומדות כמו וע\"י יתיב כו' אבל במהו\"ע המאציל ליכא זקנה קמי' שהוא למעלה מבחי' אדם, והיינו בחי' שמחה העצמי' שירד מהעלם עצמות התענוג הפשוט שנק' שעשועי המלך בעצמותו, רק שבמ\"ת נדמה להם כזקן שקנה חכמה משום דאורייתא מחכמה עילאה נפקת<sup data-n=\"911\">78</sup> וד\"ל.\n<b>ובכ\"ז</b> יובן מ\"ש אז תשמח בתולה במחול<sup data-n=\"912\">79</sup> בחורים וזקנים יחדיו, דאין הפרש בין בחורים וזקנים קטנות וגדלות בעצמות אא\"ס שיתגלה למטה כמו למעלה דליכא זקנה קמי' כנ\"ל, אז גם השמחה לא יומשך בדרך השפעה דמשפיע ומקבל דחו\"כ רק שמחה פשוטה ועצמית שלמעלה משמחת נשואין בחופה כו', והוא מ\"ש אז תשמח בתולה במחול דוקא, כי יש ב' מיני ריקוד, א'",[["910","77","<b>ישכיל עבדי</b>: ישעי' נב, יג."],["911","78","<b>דאורייתא מח\"ע נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. זח\"ג פא, א. קפב, א. רסא, א."],["912","79","<b>אז תשמח בתולה במחול</b>: ירמי' לא, יב."]]],[1900420225,"זה כנגד זה להתקרב ולהתרחק וחוזרים ומתקרבים כידוע, וזהו כמו בחי' הריקוד דלבנה לגבי השמש שהן בבחי' משפיע ומקבל שיש בזה ריחוק וקירוב כמ\"ש כשם שאני רוקד כנגדך כו', והוא מיעוט הלבנה ופיגומה בריחוק וחוזרת ומתקרבת במילואה כידוע, וזהו בחו\"כ ביחוד איש ואשתו שלפעמים ועתים בקירוב כו' ובימי נדותה תתרחק וחוזרת ומתקדשת מטומאתה ומתייחדת כו', והריקוד הב' הוא בעיגול שנק' מחו\"ל שאין בו קירוב וריחוק כלל רק שמסבבים וחוזרים לנקודה הראשונה וחוזרים ומסבבים כו', והוא כמו ריקוד הבתולות במחולות. וכך יובן למעלה בבחי' שמחה דכנ\"י לע\"ל שיהי' בבחי' עצמית בעצמות אא\"ס ממש שהוא למעלה מבחי' שמחה דמשפיע ומקבל שנקרא חו\"כ שזהו בבחי' עיגול שהוא מקיף הכללי שלמעלה מבחי' אדם וכמ\"ש שם נשמחה בו<sup data-n=\"913\">80</sup> בו ממש, ה\"ז כמו הריקוד במחול וכמ\"ש יהללו שמו במחול, כי כנ\"י יהי' בחי' בית קיבול להכיל שמחה ותענוג הפשוט שבעצמות ממש דלית מחשבה תפיסא בי' כלל שנקרא שמו הגדול כמו שהוא קודם הצמצום דקו\"ח כידוע, וע\"כ יהי' הריקוד דכנ\"י מלמטה כלפי מעלה במחו\"ל דוקא שהוא הסיבוב והריקוד בעיגול דוקא. וז\"ש א\"ז תשמח בתולה א\"ז דוקא לע\"ל שיתגלה עצמות אא\"ס כמו שהוא למעלה כו' תשמח בתולה ולא בעולה להיות אז למעלה מבחי' יחוד דחו\"כ בנישואין מטעם הנ\"ל וד\"ל.",[["913","80","<b>שם נשמחה בו. ֿ. יהללו שמו במחול</b>: תהלים סו, ו. קמט, ג."]]],[1900420226,"<h3>אשר ברא כו' להבין הדקדוקים</h3>\n<b>אשר</b> ברא<sup data-n=\"914\">1</sup> ששון ושמחה חתן וכלה כו' מהרה ישמע כו' קול חתן וקול כלה כו'. הנה להבין הדקדוקים בנוסח ברכה זו רבים הם, א' מהו אשר ברא ששון [האיך] מצינו לשון בריאה יש מאין בששון ושמחה והלא אמר כשמחך יצירך כו' הרי מקדם אשר לא נעשה נברא האדם או השמחה ואם הפי' שברא השמחה באדם מה שייך לכללות בריאת האדם לשון להבא ולא עכשיו הרי גם עכשיו נמצא בערי ישראל בכל מושבותיהם קול ששון קול חתן כו', ועוד מה שייך הרמת קול לחתן וכלה בשמחתם וזה עצמו ישמע לע\"ל דוקא כו', וגם מה שכפל לומר קול חתן וקול כלה ובגמרא אמרו בענין הנהנה מסעודת חתן<sup data-n=\"915\">2</sup> כו' שעובר בה' קולות היינו קול ששון וקול שמחה וקול חתן כו', ועוד מ\"ש קול כלה הרי בחתימה מסיים משמח חתן עם הכלה דהכלה עיקר ובשמח תשמח מסיים חתן וכלה ומאחר שלא שינה כאן מלשון המקרא קול חתן<sup data-n=\"916\">3</sup> תחילה ואח\"כ קול כלה א\"כ למה מסיים חתן עם הכלה הול\"ל חתן וכלה כו'.\n<b>אך</b> הנה כ\"ז יובן בהקדים שרש ענין ארוסין ונשואין, דהנה כתיב ביום חתונתו וביום שמחת לבו דיום חתונתו זה קאי במ\"ת דכחתן יכהן פאר<sup data-n=\"917\">4</sup> כו' ויום שמחת לבו קאי לע\"ל בימות המשיח דאז כתיב כי בועליך עושייך כו' ובמ\"ת א' וארשתיך לי כו' וכמ\"ש מורשה מאורשה<sup data-n=\"918\">5</sup> כידוע. וענין ההפרש בין אירוסין לנשואין הנה תחילה ילה\"ק ענין פנימי' וחיצוני' שבתורה דהיינו אורייתא סתים וגליא<sup data-n=\"919\">6</sup> כו' ובדיבור זה ודאי נכלל כל עונג העצמי שבפנימי' חכמתו ורצונו עכ\"ז לא בא בגילוי לבנ\"י רק חלק הנגלה שהן יו\"ד הדברות, והפנימי' שהוא הנק' טעמי תורה לא יבא בגילוי רק לע\"ל דוקא כמ\"ש רש\"י ע\"פ ישקני מנשיקות פיהו<sup data-n=\"920\">7</sup> כו' כידוע, ובמ\"ת הי' כל פנימי' ועצמיות השעשועים גנוז ונעלם בתוך הדיבור ומה שהי' קול השופר חזק קולות וברקים וכל העם רואים כו' ועל כל דיבור<sup data-n=\"921\">8</sup> פרחה נשמתן ממש ואם הי' הנ\"ל בהעלם והגילוי בבחי' הנגלה למה הי' הרעש הגדול",[["914","1","<b>אשר ברא</b>: מיוסד על ד\"ה מהרה ישמע בסידור עם דא\"ח קלח, ב. ונמצא ג\"כ בשינויים ובאריכות להלן בד\"ה קול מצהלות (אות י\"ג ואילך). תוכן המאמר נמצא ג\"כ בתו\"א ס\"פ ויגש (מד, ד) ד\"ה ”ולתוספת ביאור כו' מהרה ישמע\". [מאמר התו\"א נדפס גם בס' עבודת הלוי ח\"ג — ליקוטים פו, א, ושם מתחיל: מהרה ישמע]. ועם הגהות באוה\"ת על סידור ע' רכב ואילך.\nמאמר זה נמצא תח\"י רק בכת\"י מעתיק אחד, ובכ\"מ בו ניכר שהכת\"י משובש וחסרים בו תיבות וכיו\"ב."],["915","2","<b>הנהגה מסעודת חתן</b>: ברכות ו, ב."],["916","3","<b>לשון המקרא קול חתן</b>: ירמי' לג, יא."],["917","4","<b>ביום חתונתו. . במ\"ת. . דכחתן יכהן פאר</b>: שה\"ש ג, יא. תענית כו, ב. ישעי' סא, יו\"ד."],["918","5","<b>כי בועליך. . וארשתיך לי. . מורשה מאורשה</b>: ישעי' נד, ה. הושע ב, כא. ברכה לג, ד. ברכות נז, א."],["919","6","<b>אורייתא סתים וגליא</b>: זח\"ג עג, א."],["920","7","<b>רש\"י ע\"פ ישקני מנשיקות פיהו</b>: שה\"ש א, ב: ומובטחים עוד מאתו להופיע עליהם לבאר להם סוד טעמי' ומסתר צפונותי' ומחלים פניו לקיים דברו וזהו ישקני מנשיקות פיהו. וראה גם ביאור ד\"ה כי על כל כבוד חופה, בסידור עם דא\"ח קלא, א ואילך."],["921","8","<b>קול השופר חזק. . וכל העם. . על כל דיבור</b>: יתרו יט, יט. כ, טו. שבת פח, ב."]]],[1900420227,"הזה, ואמנם באמת אמרו מה להלן<sup data-n=\"922\">9</sup> באימה כו' דדבריו חיים וקיימים, וגם אז הי' בחי' אור עצמות המאציל בגילוי בכל דין ובפרט לנש\"י שעמדו וראו כו', רק לא בא זה האור בבחי' כלי ולבוש בהשגה לדורות הבאים עד ימות המשיח מאחר דכתיב ישקני מנשיקות פיהו שהן טעמי תורה הנסתרות להוי' כו' שנשיקות הללו מכל פנימי' ועצמות השעשועים שלפניו ממש כמ\"ש משחקת לפניו<sup data-n=\"923\">10</sup> (ואמנם עכ\"ז בחי' אירוסין ע\"ש בחי' ההעלם דמקיף כמשי\"ת לפי שלא קבלו [רק בבחי' מקיף] מבחוץ כמשי\"ת).\n<b>והנה</b> ידוע דבחי' פנימי' וחיצוני' שבתורה הנ\"ל הוא בחי' פנימי' עתיק יומין וחיצוני' עתיק יומין או בחי' עתיק יומין ועתיקא דעתיקא שזהו ידוע שהתענוג העצמי שבעצמות המאציל נק' בשם שעשועי המלך בעצמותו והוא הנק' ע\"י דע\"י, ובחי' ירידת שפע אור התענוג בח\"ע דאצי' שנק' עדן וכה\"ג נק' חיצוני' התורה בבחי' הנגלה והיינו מ\"ש ג' נובלות הן<sup data-n=\"924\">11</sup> נובלות חכמה שלמעלה תורה, שנובלות הללו חיצוני' הנובלות מעצמות השעשועים ומ\"ש ואהי' אצלו שעשועי' וכן משחקת לפניו ממש כנ\"ל הוא הנק' תורה שלמעלה או חכמה שלמעלה בחי' סתים דאורייתא שלא בא לברר בעה\"ד כו' וכאשר לע\"ל יתגלה טעמי תורה כנ\"ל היינו שיתגלה מבחי' פנימי' עתיק יומין שבעצמות ממש, כי הטעמים שרשם בפנימית עתיק יומין שנק' פנימי' הכתר כידוע בענין טנת\"א<sup data-n=\"925\">12</sup> כו'.\n<b>ומעתה</b> י\"ל בענין מ\"ת דודאי בי' הדברות דכתיב אנכי שהוא בחי' עצמות המאציל וכתיב וירד הוי'<sup data-n=\"926\">13</sup> דמשמע שיורד עם כל מה שבעצמותו גם מפנימית התענוג העצמי, אך ורק שלא בא כל זה הפנימי' לידי גילוי בכנס\"י בבחי' אור פנימי אלא נשאר עליהם האור בבחי' מקיף כמו האור המקיף השורה עכ\"פ על בחי' אור פנימי ומקיפו מכל צדדיו וכך כפה עליהם הר כגיגית<sup data-n=\"927\">14</sup>. וזהו ענין האירוסין, שבמ\"ת נאמר ביום חתונתו לבד כנ\"ל וכמו עד\"מ האירוסין למטה הנה אנו רואים בענין הקדושין שמקדש האיש בטבעת העגולה שהוא מקיף לאצבע היד ונותן על האצבע שלה טבעת קדושין העגול ואומר הרי את מקודשת בטבעת זו כו', והענין הוא כידוע דפי' מקודשת מלשון קדושה עליונה שזהו בחי' קדש העליון דח\"ע שבה מאיר בהעלם מבחי' מקיף דכתר ופי' מקודשת מזומנת וראוי', ועוד שתהי' מיוחדת אליו, ולכך אומר לי דוקא והוא בחי' המשכת המקיף בעיגול הטבעת על אצבעה להיות מוכנת וראוי' ומיוחדת אליו ליחוד וזיווג שהוא גילוי השפע במקבל בבחי' או\"פ שהוא העוזר לאו\"פ.",[["922","9","<b>מה להלן</b>: ברכות כב, א."],["923","10","<b>משחקת לפניו</b>: משלי ח, ל."],["924","11","<b>ג' נובלות הן</b>: ב\"ר פי\"ז, ה."],["925","12","<b>כידוע בענין טנת\"א</b>: ראה תקוני זהר בהקדמה (ז, ב). תס\"ט (קה, א). פרדס שכ\"ט פ\"ה. ע\"ח שער טנת\"א (ש\"ה). ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שפח. וש\"נ."],["926","13","<b>אנכי. . וירד ה'</b>: יתרו כ, ב. יט. כ."],["927","14","<b>כפה עליהם הר כגיגית</b>: שבת פח, א."]]],[1900420228,"<b>והיינו</b> ענין החופה שהוא בחי' מקיף מקפת על חתן וכלה יחד (כמ\"ש במ\"א בענין כי על כל כבוד חופה כו' והוא כחתן<sup data-n=\"928\">15</sup> יוצא מחופתו) ע\"י עיגול טבעת<sup data-n=\"929\">16</sup> הקדושין באמרו הרי את מקודשת כו'. וזהו פי' מקדש עמו ישראל ע\"י חופה וקדושין דמשמע דשניהם ענין אחד ממש שהוא בחי' המקיף שבאירוסין (ובאמת יש הפרש בין חופה לקדושין שהחופה עיקר בחי' הנשואין כמ\"ש בנוסח הברכה והתיר לנו הנשואות לנו ע\"י חופה כו' והארוסות שבימים הקדמונים היינו קדושין בלא חופה ואסר לנו הנשואות לנו כ\"א ע\"י חופה כו' וגם עכשיו שהקדושין בשעת החופה [מ\"מ] יש הפרש גדול בין מקיף דקדושין למקיף דחופה כמו שיש הפרש בין אירוסין לנשואין בכלל, ומ\"ש מקדש עמו ע\"י חופה וקדושין קאי במקיף הכולל שניהם מפני שזה הי' במ\"ת, ועכ\"פ עיקר בחי' נשואין שבבחי' יחוד גמור [יהי'] לע\"ל דייקא), וכמו\"כ יובן דבמ\"ת הי' בחי' אירוסין שקידש עמו ישראל בחופה וקדושין וכמ\"ש וארשתיך לי כו' כי האשה נקנית בג' דרכים בכסף כו' וכנ\"י נק' אשה יראת ה'<sup data-n=\"930\">17</sup> כו' והיינו שנמשך עליהם בחי' או\"מ כמו בטבעת קדושין הנ\"ל (והוא ענין ב' כתרים אחד כנגד נעשה ואחד כנגד נשמע שעל זה נאמר בחטא העגל ויתנצלו בני ישראל את עדיים כו' וכן ותבואי בעדי כו' וכן מ\"ש וככלה תעדה<sup data-n=\"931\">18</sup> את כליה וכה\"ג), ובחי' נשואין שהוא כמו הזיווג שהוא יחוד משפיע ומקבל בגילוי כמו כי בועליך כו' היינו לעתיד בהתגלות טעמי תורה למטה ועין בעין יראו כו' וגם שבמ\"ת נאמר עין בעין כו' זהו רק בבחי' אין דחכמה שנק' ראי' כידוע אבל בבחי' העצמות ממש אינו אלא לע\"ל דכתיב ואמר הנה אלקינו זה<sup data-n=\"932\">19</sup> כו' וכמ\"ש במ\"א יבוא טוב<sup data-n=\"933\">20</sup> ויקבל טוב כו' וזהו ביום שמחת לבו.\n<b>והנה</b> ביום חתונתו נאמר בעטרה שעטרה לו אמו דוקא. והענין הוא כידוע דחתן לשון חות דרגא<sup data-n=\"934\">21</sup> שהוא בחי' משפיע למקבל והיינו בחי' המדות שבז\"א, דאורייתא מחכמה עילאה נפקת<sup data-n=\"935\">22</sup>, אבל [לגבי] עצם התורה הן כמו מ\"ט פנים טמא<sup data-n=\"936\">23</sup> כו' להורות ולהבדיל כו' ושרש המדות הללו נמשך מאור הבינה",[["928","15","<b>במ\"א בענין כי על כל כבוד. . והוא כחתן</b>: ישעי' ד, ה. תהלים יט, ו. ראה סידור עם דא\"ח קלא, ג ואילך. לעיל ח\"א ע' א ואילך. ס\"ע כב ואילך."],["929","16","<b>ע\"י עיגול טבעת הקידושין</b>: ראה סידור שם קלא, ג [ומקבילו בסה\"מ הנחות הר\"פ ע' נא]. שם קלח, ד. ס' מאמרי אדהאמ\"צ בראשית ע' ריט. רכט."],["930","17","<b>האשה נקנית. . אשה יראת ה'</b>: קידושין ב, א [וראה עוד על מארז\"ל זה לקו\"ת בתחילתו א, ג. ובהנסמן בהמ\"מ לשם — בהוצאת ה'תשד\"מ. ובס' מאמרי אדהאמ\"צ נ\"ך ע' תקל]."],["931","18","<b>ב' כתרים. . ויתנצלו. . ותבואי בעדי. . וככלה תעדה</b>: שבת פח, א. תשא לג, ו. יחזקאל טז, ז. ישעי' סא, יו\"ד."],["932","19","<b>עין בעין. . הנה אלקינו זה</b>: ישעי' נב, ח. כה, ט."],["933","20","<b>במ\"א יבוא טוב</b>: מנחות מג, ב [וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תיב. וש\"נ]."],["934","21","<b>דחתן לשון חות דרגא</b>: ראה יבמות סג, א."],["935","22","<b>דאורייתא מח\"ע נפקת</b>: זח\"ב פה, א. ועוד."],["936","23","<b>מ\"ט פנים טמא</b>: ירושלמי סנהד' פ\"ד ה\"ב. ובכ\"מ."]]],[1900420229,"שנק' אמו, ומ\"ש בעטרה שעטרה לו אמו אינו בשביל עצמו רק כדי שיהי' לו כח להיות משפיע והוא בחי' מקיף דעטרה זו ע\"ג הראש ונק' כתר תורה כידוע שזהו ת\"ת דאימא שנעשה כתר לז\"א<sup data-n=\"937\">24</sup> בשעת מ\"ת דוקא שהוא ביום חתונתו וז\"ש כחתן יכהן פאר כמ\"ש במ\"א וכל המקיפים מבינה דוקא ולא מאבא לכך א' שעטרה לו אמו דוקא וד\"ל.\n<b>אך</b> כ\"ז אינו אלא עכשיו שהמל' מקבל מז\"א שנק' חתן כו' אבל לע\"ל כתיב אשת חיל עטרת בעלה שהמל' תתעלה למעלה מבחי' ז\"א עד שתהי' עטרת בעלה לפי שבחי' ב\"ן יעלה בבחי' ס\"ג<sup data-n=\"938\">25</sup> שלמעלה משם מ\"ה וא\"כ יהי' המל' במקום בינה דעכשיו שהוא בחי' ס\"ג כידוע, ולכך לא יהי' עטרה זו כמו שהי' במ\"ת מאמו אלא מבחי' המל' שתהי' לו עטרה מצד בחי' הבירורים דרפ\"ח כו' שיבורר ע\"י בחי' ב\"ן ונעשה מזה עטרה לז\"א או משום שהמל' יהי' למעלה ומה שהמל' יהי' עטרה הוא יותר גבוה מעטרה שעטרה לו אמו לפי שנעוץ תחלתן בסופן וסופן כו' דסוף מעשה<sup data-n=\"939\">26</sup> עלה במחשבה תחלה שהוא הרצון דמחשבה הקדומה שלמעלה מעלה מן החו\"ב ועטרה שנמשך מרצון ומחשבה הקדומה בעצמות יותר נעלה גם מרצון שבימ\"ב<sup data-n=\"940\">27</sup> שזהו עטרה שעטרה לו כו' דכפל [חסרים כמה תיבות] הכתר הכללי בבחי' ת\"ת שבה כו' והטעם הוא [לפי] דכצינה רצון תעטרנו<sup data-n=\"941\">28</sup> יש בזה ב' מדריגות מקיף דאור ישר שבא מלמעלה למטה ברצון שבחו\"ב כו' דתורה הנגלית כו' ובחי' מקיף דאור חוזר<sup data-n=\"942\">29</sup> שמן הבירורים מקיום המצות הרי עולה למעלה בעצמות ממש.\n<b>אמנם</b> לפ\"ז שבחי' ז\"א מקבל העטרה מבחי' המל' אינו עולה כפי הפשט שבמקרא זה שאמר צאינה וראינה כו' בעטרה כו' ביום חתונתו וביום שמחת כו' הרי מ\"ש שעטרה לו אמו קאי על שני הזמנים הללו ביום חתונתו ושמחת לבו שהוא לעתיד כנ\"ל אלא מוכרח לומר כנ\"ל דגם עטרה דמל' הוא בבחי' עטרה דבינה שהוא ב\"ן שעולה בס\"ג כו' ולפ\"ז יוכל להיות שגם ענין התגלות טעמי תורה יבא לעתיד מעטרה שעטרה לו אמו ביום שמחת לבו בבחי' אור חוזר וכמשי\"ת בע\"ה וד\"ל<sup data-n=\"943\">30</sup>.",[["937","24","<b>ת\"ת דאימא שנעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם רפ\"ה ורפ\"ז. ובכ\"מ."],["938","25","<b>אשת חיל. . ב\"ן יעלה בבחי' ס\"ג</b>: משלי יב, ד. ע\"ח שער טנת\"א פ\"א. [ובהנסמן עוד בהמ\"מ בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' תתקב]."],["939","26","<b>שנעוץ תחלתן. . דסוף מעשה</b>: ס' יצירה פ\"א מ\"ז. פיוט לכה דודי."],["940","27","<b>שבימ\"ב</b>: שבימי בראשית. ואולי יש כאן טעות מעתיק."],["941","28","<b>דכצינה רצון תעטרנו</b>: ע\"פ תהלים ה, יג."],["942","29","<b>מקיף דאו\"י. . מקיף דאו\"ח</b>: ראה לעיל ח\"א ע' יו\"ד ואילך."],["943","30","<b>וכמשי\"ת בע\"ה וד\"ל</b>: ראה להלן בהוספות ברשימת הכת\"י למאמר זה."]]],[1900420230,"<h3>קול מצהלות</h3>\n[א] <b>קול</b> מצהלות<sup data-n=\"944\">1</sup> חתנים מחופתן ונערים ממשתה נגינתם. הנה חתנים ל' רבים ונערים ל' רבים ויש להבין תחלה ענין נערים שהן ב' נערים (והוא בחי' נער מט\"ט מיט\"ט ביו\"ד ומט\"ט בלא יו\"ד שהוא בינה ותבונה, כי יש בחו\"ב ב' מדרגו' או\"א עילאי' וישראל סבא ותבונה וע\"כ גם חתנים שנים שהוא אבא עילא' וישראל סבא כמו שנערים שנים וד\"ל). דהנה ביהושע כתיב נער לא ימיש מתוך האהל וידוע דפני משה כפני חמה<sup data-n=\"945\">3</sup> ופני יהושע כפני לבנה וע\"כ נק' נער לא ימיש כו' כמו הלבנה שאין לה אור עצמותה רק מה שמקבלת מאור השמש כך יהושע קיבל אור תורה ממשה בתמידו' באורו הי' לו אור, ובזה יש מעלה וחסרון, כי נער ל' משרת כמו ויאמר שאול אל נערו וכמו נערי יואב כו' ויהושע נק' נער משרת משה מבחוריו<sup data-n=\"946\">4</sup> שהוא בחי' טפל ובטל לגמרי לגבי משה ואינו נחשב למהות בפ\"ע כלל וכלל וכתלמיד לפני רבו שהוא תמיד בתכלית הביטול ממציאותו עד שלא יוכל להיות משפיע כלל דאיידי דטריד למיבלע לא פליט כלל<sup data-n=\"947\">5</sup>, והנה זהו עצמו הנותן שיש בו מעלה יתירה להיותו דבוק בעצמות אור המשפיע והי' כמוהו ממש, וע\"כ הי' ביהושע מבחי' ומדרגת משה ממש כמ\"ש משה קיבל תורה מסיני ומסרה ליהושע ויהושע לזקנים<sup data-n=\"948\">6</sup> אע\"פ שזקינים קיבלו ושמעו ממשה ג\"כ אך קיבלו ע\"י יהושע משרת משה אחר שהי' בחי' מקבל כנ\"ל נעשה בחי' משפיע וכמ\"ש ונתת מהודך עליו<sup data-n=\"949\">7</sup> הוד\"ך ממש שהי' עליו זיו הודו של משה ולא במדרג' למטה מזה כלל, משא\"כ הזקיני' אף שנאצל מן הרוח של משה עליהם לא היו במדרגתו, וכל זה ההפרש רק מצד שהי' יהושע משרת משה ונק' נע\"ר לא ימיש מתוך אהלו של משה אפילו רגע ואהל תורתו של משה זרח עליהם יחד בבחי' מקיף כאהל שמאהיל על שניהם יחד בתמידו' וזהו לא ימיש מתוך האהל דוקא וד\"ל, אך בתנאי שלא ימיש אף רגע ואם ימיש מתוך האהל שאין אורו של משה עליו אז לית לי' מגרמי' כלום, כלבנה שאין לה אור עצמותה כלל רק כאשר",[["944","1","<b>קול מצהלות</b>: חלק מקונטרס זה (עד להלן אות י\"ג) מיוסד על ד\"ה ונערים ממשתה נגינתם, בסה\"מ תקס\"ח ח\"ב ע' תרכב ואילך. [ובתוס' הגהות מאדמו\"ר הצ\"צ שם בהוספות ע' תשל-תשמב].\nוראה עוד בביאור נוסח קול מצהלות כו': לעיל ד\"ה אשר ברא (הראשון) אות ח' ואילך. סידור קלח, ב. לקו\"ת צו ט, ב ואילך. ד\"ה קול מצהלות בסה\"מ תקס\"ה ח\"א ע' מו.\nקונטרס זה מיוסד על כמה מדרושי אדה\"ז, ונסמנו בפרטיות להלן בהוספות ברשימת הכתבי-יד."],["945","3","<b>נער לא ימיש. . דפני משה כפני חמה</b>: תשא לג, יא. ב\"ב עה, א."],["946","4","<b>ויאמר שאול אל נערו. . נערי יואב. . משרת משה מבחוריו</b>: ע\"פ שמו\"א ט, ז. שמו\"ב כ, יא. בהעלותך יא, כח."],["947","5","<b>דאיידי דטריד למיבלע לא פליט כלל</b>: ע\"פ חולין קח, ב: דמבלע בלע מפלט לא פליט (ובפרש\"י: דמה שבולע אינו פולט שכל זמן שאינו נח מרתיחותיו אינו פולט). ושם ח, ב: איידי דטרידי סימנין לאפוקי דם לא בלעי. וכהלשון כאן מובא ג\"כ בכ\"מ בדא\"ח (תו\"א וישב כח, א. ביאוה\"ז קמב, ג. סה\"מ תקס\"ה ח\"א ע' תקיב (בשם מארז\"ל). ועוד)."],["948","6","<b>משה קיבל. . ויהושע לזקנים</b>: אבות בתחילתו."],["949","7","<b>ונתת מהודך עליו</b>: פינחס כז, כ."]]],[1900420231,"עומדת מקרוב לקבל אור השמש ואור השמש הוא שמאיר בה ולא אור עצמותה.\n<b>והנה</b> יש דעת האומרים דאור הלבנה אינו אור מקבל לבד<sup data-n=\"950\">8</sup> אלא הוא אור משפיע וכמו ממגד גרש ירחים<sup data-n=\"951\">9</sup> שזורחת אור עצמותה ודוקא בריחוק מקום מן השמש רק כאשר מקבלת מאור השמש מרחוק דוקא אז תתמלא במילוא' וכשעומדת מקרוב חשך אורה כשרגא בטיהרא כו', הרי לפ\"ז יתפרש המא' פני משה כפני חמה כו' לא בשעה שהי' יהושע משרתו באהל משה דא\"כ איך הי' ליהושע אז אור עצמו כפני לבנה הרי מתחשך אורה בקירוב לשמש אלא לאחר הסתלקות משה שמלך יהושע קאי ואך הוד דמשה ממש ניתן לו הרי זה כמו שאור השמש מאיר בלבנה בריחוקה ומ\"מ נק' אור הלבנה אור משפיע כנ\"ל וזהו פני לבנה דכל פנים ל' אור, והיינו כאשר נעשה יהושע ראש ומשפיע היפך בחי' מקבל כשהי' באהל משה בטל כו' וכמ\"ש ויהושע מסר לזקיני'. וזהו מדרג' הב' בנערים שזהו כמו תלמיד שנפרד מרבו ואינו מקבל עוד אך אור תורת רבו זורח בו מרחוק תמיד וממנו הוא נובע כמעיין המתגבר להיות משפיע אור והשפעה זו מאור עצמותו כאור הלבנה, ומ\"ש סיהרא לית [לה] מגרמה כלום<sup data-n=\"952\">10</sup> היינו דלית לה בחי' כח המוליד ומשפיע מגרמה בלתי קבלת אור השמש, וכמו אשה כי תזריע<sup data-n=\"953\">11</sup> וילדה כו' וע\"י קבלת מ\"ד דוקא וד\"ל.\n<b>והנה</b> לפי כל הנ\"ל יובן דאין ערך לבחי' משפיע דפני לבנה דיהושע לאחר מות משה אע\"פ שסמך ידיו עליו ונתן מהודו ממש עליו לגבי בחי' מקבל דיהושע כשהי' נער לא ימיש בחיי משה כו' אע\"פ שהי' טפל ובטל כאילו אינו במציאו' כלל וגם אם הי' נפרד ממשה אף רגע אין לו כלום, משא\"כ כשמלך יהושע הוא במהו' יש ודבר בפ\"ע בחי' משפיע וא\"צ להיות מקבל תמיד כו'. אך הנה באמת אור שפע דמשה ביהושע גם לאחר מותו הי' כמו בחייו ממש דאל\"כ לא הי' כח ליהושע להשפיע כלל וכנ\"ל כסיהרא דלית כו', וזהו ע\"י שסמך ידיו עליו והי' כמוהו כהוד של משה ממש כמו שהי' מקבל באהל משה, וא\"כ למה אמרו הזקנים שבאותו הדור אוי לאותה בושה<sup data-n=\"954\">12</sup> כו' מפני שידעו וראו מעלת ומדרג' משה שהוא כפני חמה ואין לפני לבנה",[["950","8","<b>דעת האומרים דאור הלבנה אינו אור מקבל לבד</b>: ראה ס' פירוש המלות לאדהאמ\"צ בענין ב' הדיעות אם הלבנה משפיעה אור עצמה או רק אור השמש, בשם חכמי התכונה וס' נחמד ונעים [לר\"ד גאנז, יעסניץ תק\"ג. ע\"ש שער ח' סי' ר\"ט]. ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' קח. [ובהמ\"מ שם נסמן לעוד מקומות]."],["951","9","<b>ממגד גרש ירחים</b>: ברכה לג, יד."],["952","10","<b>סיהרא לית לה מגרמה כלום</b>: זח\"א רמט, ב. זח\"ב רטו, א. ועוד."],["953","11","<b>אשה כי תזריע</b>: תזריע יב, ב."],["954","12","<b>אוי לאותה בושה</b>: ב\"ב עה, א: ונתת מהודך עליו ולא כל הודך זקנים שבאותו הדור אמרו פני משה כפני חמה פני יהושע כפני לבנה אוי לה לאותה בושה אוי לה לאותה כלימה, ורש\"י: שבזמן מועט נתמעט הכבוד כ\"כ שהרי יהושע הי' נביא ומלך כמשה ולא יכול להגיע לכבודו."]]],[1900420232,"דיהושע ערך לזה ע\"כ היו מקונני' והיו מתביישי' לקבל אור פני לבנה דיהושע, וזה פלא דגם אם היו הזקנים במדרג' משה כיהושע בחייו הרי גם הם לא קיבלו ממשה רק ע\"י יהושע ומה גם שלא היו ממדרג' משה כנ\"ל א\"כ מה זה גרעון להם פני לבנה דיהושע גם אחר מות משה מאחר שסמך ידיו עליו ואורו של משה ממש הוא המאיר בו וכמו שקיבלו מיהושע כשהי' נער לא ימיש כו' וד\"ל.\n[ב] <b>אך</b> הנה עיקר הענין הוא כידוע דשרש משה מבחי' פנימי' יסוד אבא כמ\"ש ונחנו מ\"ה דחכמ' וכמ\"ש ותרא אותו כי טו\"ב הוא כו' ונק' מחוק\"ק<sup data-n=\"955\">13</sup> כו' שממנו נובע מקור שפע אור תו\"מ לכנ\"י ויהושע נער לא ימיש כו' ביחוד תדירי היינו בחי' פנימי' יסוד אימא שמקבל תמיד מיסוד אבא דאו\"א זווגייהו תדיר<sup data-n=\"956\">14</sup> כו', וע\"כ הוסיף לו משה יו\"ד דחכמ' וקראו יהוש\"ע שהוא התגברו' החסדי' דאבא, וז\"ש ונתת מהוד\"ך עלי\"ו היינו בהסתלקו' משה פנימי' אור אבא ונמשך רק מהוד דאבא באימא שהוא בחי' בינה ומשם מאיר אור ושפע לזקנים דכנ\"י שהן בחי' כח\"ב דמל' כידוע בענין זקן שקנה חכמ' ממקורה שהוא ח\"ס וזקנים לנביאי' בחי' נו\"ה כו'. וזהו שא' הזקנים שבאותו הדור אוי לאותה בושה כו' כי בחיי משה קיבלו מפנימי' אור אבא באימא שהוא יהושע כו' ועכשיו הן מקבלי' מנו\"ה דאבא המוסתר בבינה, דמה שא' פני משה כפני חמה היינו בבחי' יסוד אבא שנק' שמשא ופני יהושע כפני לבנה באור אימא, והיינו בשעת יחודם הפנימי באהל אחד, ואמנם בהסתלקו' אור אבא שנק' פני חמה אזי בחי' פני לבנה בריחוק מקום ומרחוק בהעלם יאיר אור אבא כו' לזקנים שהן כחב\"ד דכנ\"י. וכך יובן גם בכל דור ודור הרי א' בזוהר דאתפשטות' דמשה<sup data-n=\"957\">15</sup> בכל דור שנק' פנים מאירו' אך הוא בהעלם גדול והוא כח מ\"ה דנה\"א בחי' הביטול העצמי לבחי' אי\"ן האלקי שבכל ניצוץ מישראל ושורה בהעלם בבחי' בינה רחובו' הנהר פנים מסבירות<sup data-n=\"958\">16</sup> כו', וכאשר בחי' מ\"ה העצמי בגילוי אזי כל אשר יש בקליטת אור הבינה נכלל בחכמ' כח מ\"ה הזה, אך לאחר שנשאר בהעלם מ\"מ כחו נראה ברחובו' הנהר דבינה להתפעל בשכל והשג' האלקי' כאו\"א לפי ערכו וכמ\"ש ביהושע שנק' איש אשר רוח בו שיכול להלוך נגד רוחו של כאו\"א<sup data-n=\"959\">17</sup> והן ס\"ר דיעות והשגו' דכנ\"י באלקו' ויוצאי' ממקור א' הוא בחי' בינה אם הבנים שכולל ס\"ר דיעו' ע\"כ יכול להלוך לנגד רוחו של כל א' וכמ\"ש נודע בשערים בכל חד לפום שיעורא דילי'<sup data-n=\"960\">18</sup> כו', ומה שנק' איש",[["955","13","<b>ונחנו מ\"ה. . ותרא אותו כי טוב הוא. . ונק' מחוקק</b>: בשלח טו, ז-ח. שמות ב, ב. ב\"ב טו, א [וראה לעיל ח\"א ע' רפד וע' רצב]."],["956","14","<b>דאו\"א זיווגייהו תדיר</b>: ע\"ח שער או\"א (שי\"ד) פ\"ז. וראה ס' מאמרי אדה\"ז הקצרים ע' תלא-ב."],["957","15","<b>בזוהר אתפשטות' דמשה</b>: תקוני זהר תס\"ט (קיב, א. קיד, א)."],["958","16","<b>שנק' פנים מאירו'. . פנים מסבירות</b>: ראה לעיל ח\"א ע' טו. וש\"נ."],["959","17","<b>איש אשר רוח בו. . רוחו של כאו\"א</b>: פינחס כז, יח. ספרי עה\"פ."],["960","18","<b>נודע בשערים בכל חד לפום שיעורא דילי'</b>: משלי לא, כג. ראה זח\"א קג, ב."]]],[1900420233,"אשר רוח בו רוח זה שיכול להלוך כו' נעשה מאשר סמך משה ידיו עליו והיינו מבחי' נו\"ה דאבא שבבינה כמ\"ש ונתת מהוד\"ך עליו. ועכ\"ז יתורץ הכל דגם לפ\"ד האו' דלבנה ברחוקה דוקא מתמלאת היינו ג\"כ מאור אבא דוקא שהוא הוד דמשה ואין לזה ערך לבחי' יחוד פנימי דאו\"א כשהי' נער לא ימיש כו' וזהו טעם הזקנים שאמרו וכו' וד\"ל.\n[ג] <b>והנה</b> מבואר שבאצי' יש ב' מדרגו' בבחי' נער א' נער לא ימיש כו' (שזהו יחוד או\"א עילאי' כנ\"ל) והב' כאשר מלך יהושע אחרי משה (שזהו בבחי' מל' פני לבנה, והיינו ב' ההי\"ן בינה ומל', וזהו בן נו\"ן נו\"ן כפופה ונו\"ן פשוטה (וכידוע שנו\"ן כפופה במל' ונו\"ן פשוטה בבינה<sup data-n=\"961\">19</sup>), כך יש ב' מיני נער א' באצי' והב' בבריא' והוא בחי' נער מט\"ט מיט\"ט ביו\"ד הוא כמו נער לא ימיש דיהושע, והוא מארז\"ל ע\"פ נער הייתי גם זקנתי שרו של עולם אמר, ופי' נער הייתי כשהוא בבחי' אצי' וכשיורד בבריא' נק' עבדו זקן ביתו המולך בכל<sup data-n=\"962\">20</sup> כו', וכמו הפרש הנ\"ל ממש ביהושע ומשה דכאשר הי' נער משרת הי' טפל ובטל ולא נחשב למהו' כלל כו', וכך בחי' מיט\"ט דנק' נער באצי' לגבי בחי' ז\"א דאצי' כאנפי זוטרי לגבי אנפי רברבי, והן בחי' קטנו' המדו' עליונו' בקטנו' המוחי' מאד ואמנם מקבל תמיד מבחי' ז\"א ונק' נער בבחי' האצי', והמדרג' הב' בחי' נער מט\"ט בבריא' שנק' שרו של עולם הבריא' (ונכלל בו יצי' ועשי'), וזהו כמו בחי' יהושע אחרי מות משה כנ\"ל שהוא יש ודבר בפ\"ע ונק' שר העולם, ואין לזה ערך לגבי מדרגתו כשעולה באצי' ונק' שם נער, וכנ\"ל שבחי' מקבל דנער לא ימיש כו' למעלה הרבה מבחי' משפיע שנעשה אח\"כ מטעם הנ\"ל וד\"ל.\n<b>(וביאור</b> ענין מט\"ט דאצי' ובירידתו לבריא' נק' עבדו זקן ביתו כו' ידוע דשם הוי' דז\"א היינו בחי' מדו' דאצי' שבחי' אורות ומוחי' דאו\"א מאירי' בהן ומלובשי' בבחי' גדלו' המוחי', שזהו כמו התפעלו' מדו' שבלב אדם למטה שנק' דו\"ר שכליי' כידוע, וכמו בחי' דו\"ר טבעיי' שהמוחי' דחו\"ב אין מאירי' שם רק בקטנו' מאד כתינוק שמדותיו טבעיי' להתפעל מדבר קטן נק' נע\"ר מט\"ט דאצי', ואמנם בחי' קטנו' המוחי' הללו מקבלי' תמיד ממדו' דגדלו' המוחי' וטפילים ובטילים ונכללי' בהם בלי נחשב למהו' בפ\"ע כלל, והיינו כמו שאנו רואי' בחוש שגם בהתפעלו' טבעי' הלב יתפעל גם הוא מהתפעלו' השכל האלקי שבבחי' חו\"ב, וכמו בינה לבא הלב שומע והלב רואה ראיי' השכל האלקי וכמ\"ש לבי ובשרי ירננו כו' בכל לבי דרשתיך<sup data-n=\"963\">21</sup>, ואדרבה כל החכמ'",[["961","19","<b>וכידוע שנו\"ן כפופה במל' ונו\"ן פשוט' בבינה</b>: פרדס שכ\"ז פי\"ז ובסוד\"ה ענין האותיות, בסה\"מ תקס\"ג ח\"א ע' עג: נו\"ן פשוטה בכתר נו\"ן כפופה במל'. והוא ע\"פ פרדס שם בשם ס' התמונה: כי צורתה בבינה ורומז אל שער החמישים."],["962","20","<b>עבדו זקן ביתו המולך בכל</b>: ע\"פ חיי\"ש כד, ב. וראה לעיל ד\"ה אשר ברא (הראשון) אות י'."],["963","21","<b>לבי ובשרי ירננו. . בכל לבי דרשתיך</b>: תהלים פד, ג. קיט, י."]]],[1900420234,"שבמוח שם הוא ונק' חכ\"ם ל\"ב, וע\"כ ממילא מובן שגם בחי' נער זה דאצי' שנק' אנפי זוטרי כמו אנפי רברבי דז\"א הוא בהיותו טפל ומחובר בו לקבל מוחי' דגדלו' דאו\"א כו' רק בהפרדו ה\"ז בבחי' קטנו', וכמו דמיון דו\"ר טבעיי' לבדם בלא הארת המדו' דגדלו' כו', והוא ענין ירידת מדות דקטנו' הללו מאצי' לבריא' שהוא עולם המחשבה, והן כמו מדו' טבעיי' דקטני' שמהרהר אותם במחשבה שנעשין בבחי' אותיו' המחשבה נפרדי' מן עצם מהותם כמו שהמה בלב. ומזה יובן ערך מט\"ט דבריא' שהן ו\"ק דבריא' לגבי מיט\"ט דאצי' שהן מדו' דקטנו' שבאצי'. ונמצא ג' מדרגו' כאן א' כשנק' נער שדבוק בז\"א והב' כשנפרד והוא בבחי' האצי' עדיין והג' בירידתו לבריא' ונק' שרו של עולם הבריא'. ולפ\"ז מה שבירידתו לבריא' נק' עבדו זקן ביתו המושל כו' לפי שאברהם הי' מרכבה לבחי' חסד דז\"א עצמו, וענ\"ר אשכול וממרא נק' נערי\"ם כמ\"ש בלתי חלק הנערים<sup data-n=\"964\">22</sup> כו', ואליעזר נק' עבד\"ו זקן בית\"ו בבחי' חסד דבריא' ויצי' כו' שמושל בכל אשר לו, וכמ\"ש גם זקנת\"י שהן בהיותו בבי\"ע שקטנו' דאצי' נק' שם בתכלית הגדלו' בבחי' זקנה, כמו יהושע שהי' נער לגבי משה ואח\"כ נעשה ראש וגדול הדור (דבחי' קטנו' שבו לגבי משה הוא הגורם בחי' הגדלו' שלו אח\"כ כנ\"ל).\n[ד] <b>והנה</b> בכל זה יובן מ\"ש בחטא העגל ושלחתי לפניך מלאך וגרשתי החתי כו', מלאך זה הוא בחי' מט\"ט דבריא' (דבחי' מיט\"ט דאצי' יש בו כל הארו' המוחי' דגדלו' דאו\"א כנ\"ל). וזהו שא' במא' הנני שולח כו' השמר בו<sup data-n=\"965\">23</sup> כי שמי בקרבו וארז\"ל זה מט\"ט ששמו כשם רבו<sup data-n=\"966\">24</sup>, הענין הוא דשם הוי' דז\"א שנק' שמי בקרבו בהעלם גדול והוא בבחי' הקטנו' מאד ע\"כ השמר בו ואל תמר בו כי לא ישא לפשעיכם להיותו בבחי' מדו' דקטנו' שלא יסבול כו' כמו שתינוק מלא דינין וכעס וכקפידא אשר היא במחשבה דוקא שלא יוכל לסבול כו' אבל מדו' שבלב שמאירי' מן הדעת והחכמ' יכול לסבול ההיפוך וירבה לסלוח כו'. ולפי שבחטא העגל פגמו בהוי' דז\"א רצה להסתלק מהם לגמרי וא' שילך מלאך שהוא מט\"ט דבריאה בחי' קטנות בתכלית ורצה ה' שכל בחי' גילוי אלקות שיהי' בכנ\"י גם לעתיד כמו בבנין בהמ\"ק הכל ע\"י מלאך זה (ובאמת הרי שרשו באצי' בבחי' נער עכ\"פ שיוכל להיות בו הארת שם הוי' בהעלם עכ\"פ כמ\"ש כי שמי בקרבו ששמו כשם רבו בבחי' שם הוי' רק שבבריאה<sup data-n=\"967\">25</sup>* נק' עבדו זקן ביתו המושל והוא שר צבא הוי'<sup data-n=\"968\">26</sup> כו') (ועוד יש לפרש דשמו כשם רבו",[["964","22","<b>בלתי חלק הנערים</b>: ע\"פ לך לך יד, כד."],["965","23","<b>ושלחתי לפניך מלאך. . הנני שולח כו' השמר בו</b>: ע\"פ תשא לג, ב. משפטים כג, כ."],["966","24","<b>זה מט\"ט ששמו כשם רבו</b>: סנהד' לח, סע\"ב."],["967","25","<b>שבבריאה</b>: תיבה זו נרשמה בגוכי\"ק בין השורות. ואולי מקומה לפני\"ז, וצ\"ל: בבחי' שם הוי' בבריאה רק שנק' עבדו כו'."],["968","26","<b>שר צבא ה'</b>: יהושע ה, יד-טו."]]],[1900420235,"היינו שם הוי' בגילוי ולא בהעלם בהיותו באצי' וזהו כי שמי בקרבו ממש, רק שנק' נע\"ר כנ\"ל ולא ישא לפשעיכם והיינו בירידתו לעולם הבריאה שנק' שר העולם, והכל ענין וטעם א' גם אם יתפרש על בחי' מט\"ט דאצי' באשר הוא שם בבחי' נע\"ר). אך הנה משה לא רצה במלאך זה ואמר לה' אם אין פניך הולכים<sup data-n=\"969\">27</sup> כו', לפי ששרש משה מבחי' אור אבא שבז\"א שנק' פני חמה כנ\"ל, וכמ\"ש למשה ושמי הוי' לא נודעתי להם<sup data-n=\"970\">28</sup> שהאבות הן המרכבה לחג\"ת דז\"א כמו שהוא רק בבחי' מוחין דאימא בקטנות ולא מגדלות דאור אבא כו', ומשמע דשמי הוי' זה נודע למשה כי הי' משרש זה ממש, וע\"כ לא חפץ במלאך זה דהוא מט\"ט (היינו גם במיט\"ט דאצי' שנק' נער), ואע\"פ ששמו כשם רבו שהוא שם הוי' אך אור דהוי' בו בקטנות מאד, ולכך אמר משה אם אין פניך הולכים שנק' בחי' אנפי רברבי כו' בחי' א\"א דאצי' שמלובש באור אבא שבז\"א (וזה מ\"ה שמו מה שם בנו כו' וכידוע<sup data-n=\"971\">29</sup>) שנק' אל רחום כו' נושא עון כו' מצד בחי' תכלית הגדלות כו'.\n<b>אבל</b> ביהושע כשהי' נפרד ממשה בכיבוש א\"י בא אליו מלאך הזה מט\"ט דבריאה ששרשו בחי' נער באצי' כנ\"ל, והוא מ\"ש יהושע אליו הלנו אתה כו' והשיבו שר צבא הוי' אנכי עתה באתי כו' וארז\"ל בדבריך באתי<sup data-n=\"972\">30</sup> כו', כי פני יהושע כפני לבנה באותו הדור שהוא בחי' מל' דאצי' (וכמ\"ש במ\"א ע\"פ עשה לך חרבות כו' הנדפס בסידור במ\"ש אז ידבר יהושע כו' שגזר התלמיד על הרב כו' ע\"ש באריכות<sup data-n=\"973\">31</sup>), וא\"ל המלאך שהוא יהי' לו לעזר בכיבוש (יריחו שהיא מנעולה של א\"י<sup data-n=\"974\">32</sup> בחי' יסוד דמל' שהאיש דרכו<sup data-n=\"975\">33</sup> כו'), ואע\"פ שמשה לא חפץ בו מפני שהי' גבוה ממנו הרבה, אבל יהושע אחר מות משה שהוא בחי' מל' בהסתלקות אור אבא שבז\"א הנק' שמשא כו' הרי בחי' נע\"ר זה שבאצי' גבוה ממנו אע\"פ שהוא בחי' הקטנות דז\"א אבל הקטנות דז\"א למעלה מבחי' הגדלות דמל', וכידוע דשם אלקים שבז\"א גדול משם הוי' שבמל' וז\"ש כי הוי' שבמל'",[["969","27","<b>אם אין פניך הולכים</b>: תשא שם טו."],["970","28","<b>ושמי ה' לא נודעתי להם</b>: וארא ו, ג."],["971","29","<b>מה שמו מה שם בנו כו' וכידוע</b>: משלי ל, ד. ראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קצז. דברים ח\"ב ר\"ע תכא. ובכ\"מ."],["972","30","<b>הלנו אתה. . עתה באתי. . בדבריך באתי</b>: יהושע שם יג-יד. כ\"ה גם בסה\"מ תקס\"ח ח\"ב ע' תרכג [המקביל לכאן] ואולי צ\"ל כאן בדורך באתי. ראה תנחומא משפטים פיסקא יח: אני הוא שבאתי בימי מנשה רבך ודחה אותי שלא רצה שאלך עמו ועתה באתי. ועד\"ז בב\"ר פצ\"ז, ג. שמו\"ר פל\"ב, ג. ועוד."],["973","31","<b>במ\"א ע\"פ עשה לך. . הנדפס בסידור במ\"ש אז ידבר יהושע. . שגזר התלמיד. . ע\"ש באריכות</b>: יהושע י, יב. סידור קמד, ג ואילך."],["974","32","<b>יריחו שהיא מנעולה של א\"י</b>: בבמדב\"ר פט\"ו, יב: יריחו נגרא של א\"י אם נכבשה יריחו מיד כל הארץ נכבשת [ובמפרשים שם: נגרא — בריח וחוזק שהיא מנעולה כו']. ובתנחומא ס\"פ בהעלותך: יריחו היתה סוגרה של א\"י כו'. ועד\"ז עוד. וראה גם לעיל ח\"א ע' קמ."],["975","33","<b>שהאיש דרכו</b>: יבמות סה, ב."]]],[1900420236,"הוא האלקים דז\"א, ומכ\"ש שם הוי' דז\"א שהרי א' כי שמי בקרבו ושמו כשם רבו שהוא בחי' הוי' דז\"א רק שהוא קטנות דהוי' כו'. ומ\"ש בדברך באתי היינו מפני שדבר מלכות תשבע\"פ דיהושע אע\"פ שנסתלק משה הוא מאור אבא שזהו כמו שהי' יהושע נער לא ימיש כו' שזהו למעלה גם מבחי' שם הוי' דז\"א כי הוא בחי' פנימי' בינה כנ\"ל, ולזה אמר כדבריך באתי, אך מ\"מ לאחר מות משה צריך יהושע עזר ממלאך זה דוקא מפני שנק' שר צבא הוי' דז\"א שהוא למעלה משר צבא אלקים דבריאה שנק' זקן ביתו המושל כו' והוא בחי' מיט\"ט ביו\"ד דאצי' שלמעלה ממט\"ט דבריאה שנק' שרו של עולם ולא שר צבא הוי' וד\"ל. וזהו שהשתחו' לו יהושע. ועי\"ל דשר צבא הוי' זה הוא בבחי' חסד דאבא שהוא מיכאל שר של ישראל שנק' צבא הוי' כדפרש\"י<sup data-n=\"976\">34</sup> והוא כהנא רבא שכל צבא הוי' דז\"א בידו כו'. אך א\"כ למה לא רצה בו משה כו', ואפשר היינו מט\"ט והוא הי' נער לא ימיש כו' ונעשה שר של ישראל צבא הוי' וזהו אוי לך ארץ שמלכך נער<sup data-n=\"977\">35</sup>.\n[ה] <b>והנה</b> אחר שמבואר למעלה בענין ב' מיני נערים הנ\"ל יש להבין מ\"ש ונתתי נערים שריהם<sup data-n=\"978\">36</sup> דמשמע שאין זו לטובה, ואם הכונה על בחי' נער מיט\"ט שבאצי' ודאי מעלה הוא ואם משה לא קיבלו הרי יהושע קיבלו והשתחוה לו על פניו כו'. אך הנה באמת מ\"ש ונתתי נערים שריהם הוא בחי' נער זה שבאצי' כאשר הוא יורד לבריאה ונפסק ממנו אור האצי' (ולא נקרא אז בשם שר צבא הוי' אלא בצבא מחנה אלקי' כו') ונק' שרו של עולם כנ\"ל, והיינו בזמן הגלות דוקא, שבזמן בהמ\"ק דקיימא סיהרא באשלמותא<sup data-n=\"979\">37</sup> שהן ע\"ס דמל' בבחי' האצי' לקבל פב\"פ מז\"א בהיכל ק\"ק וכן בכנ\"י בעלותם ברגל לקבל פני האדון הוי' צבאות שבאצי' כמו דכתיב יראה כל זכורך<sup data-n=\"980\">38</sup> אז ודאי אין ממשלה ושליטה לבחי' נערי\"ם דאצי' שהן מט\"ט וסנד\"ל דאצי' כי משם הוי' דז\"א פא\"פ ידבר בכנ\"י וכמ\"ש יאר ה' פניו אלי\"ך<sup data-n=\"981\">39</sup> ממש ולא ע\"י מלאך ושום אמצעי בעולם, אך בזמן הגלות דגלות השכינה באוה\"ע וכמאמר גלו לאדום<sup data-n=\"982\">40</sup> שכינה עמהם ואתתא אתתרכא<sup data-n=\"983\">41</sup> מבעלה, ואמר בזוהר דקודב\"ה בגלותא אסתלק<sup data-n=\"984\">42</sup> לעילא לעילא פי' לעילא באצי' ומאצי' עוד למעלה וזהו לעילא לעילא שזהו",[["976","34","<b>כדפרש\"י</b>: יהושע שם טו: שר צבא ה' — ישראל שהוא צבא לה' ומיכאל הי' שנאמר ומיכאל שרכם."],["977","35","<b>אוי לך ארץ שמלכך נער</b>: קהלת י, טז."],["978","36","<b>ונתתי נערים שריהם</b>: ישעי' ג, ד."],["979","37","<b>דקיימא סיהרא באשלמותא</b>: ראה זח\"א קנ, א. רכה, ב. רמג, א. ועוד."],["980","38","<b>יראה כל זכורך</b>: משפטים כג, יז."],["981","39","<b>יאר ה' פניו אליך</b>: נשא כו, ה."],["982","40","<b>גלו לאדום</b>: מכילתא בא יב, מא. ספרי בהעלותך י, לה. מסעי לה, לד."],["983","41","<b>ואתתא אתתרכא</b>: זח\"ב רטז, ב."],["984","42","<b>בזוהר דקודב\"ה בגלותא אסתלק</b>: ראה זח\"א רי, א. זח\"ב נח, ב. זח\"ג כ, ב. וראה ס' מאמרי אדהאמ\"צ דברים ח\"א ע' קעז. ובכ\"מ."]]],[1900420237,"בחי' דורמיטא בחי' שינה הסתלקות המוחין, כאדם הישן שעיניו סגורות וכלי שכלו עם מדותיו מסתלקים במקור ועצמות הנפש ולא נשאר רק רושם בעלמא במדות שבלב שהוא תכלית הקטנות כו', כך עד\"מ א' עורה למה תישן הוי' כו' שהוא ז\"א דאצי', שז\"ש אסתלק לעילא דקודב\"ה הוא בחי' ז\"א וכמ\"כ מ\"ש ואנכי הסתר אסתיר פני ביום ההוא שבזמן הגלות הוא בהסתר והעלם אחר העלם וכמ\"ש אלכה אשובה אל מקומי<sup data-n=\"985\">43</sup> כו' (וכדוגמא שאמרו בלילא שהוא הגלות רוכב הקדב\"ה על כרוב אחד (שהוא המל') ושט בח\"י אלף כו' וכמ\"ש במ\"א<sup data-n=\"986\">44</sup>).\n<b>וזהו</b> ונתתי נערים שריהם שאז ניתן הממשלה וההנהגה דכל העולמות ודוקא על ישראל בפרט ע\"י בחי' נער מט\"ט שיורד מאצי' לבריאה ונק' שרו של עולם בכלל כנ\"ל בפי' נער הייתי גם זקנתי כו' וגם נק' עבדו זקן ביתו המושל כו', ומה שמשמעו שאין זו לטובה היינו שאם הי' בחי' נער זה כמו שהוא באצי' דשם איהו וחיוהי חד כו' שלא נפסק עדיין אור האצי' ע\"י פרסא וגם הנה הוא בטל שם ונכלל בז\"א כנער משרת בעוד שעומד לפני רבו ה\"ז ממש כמו שהי' ההנהגה ע\"י בחי' ז\"א עצמו, וכיהושע שהי' משרת משה כנ\"ל, אך כאשר בגלותא אסתלק לעילא לעילא בבחי' שינה כו' אז נעשה בחי' הנער זה שהוא בחי' קטנות המדות דאצי' בבחי' גדלות למטה בבריאה כמו גדולת השר שממשלתו ביש ודבר בפ\"ע, וכמשל כאשר המלך הלך למרחוק אז יגדל הנער הקטן משרתו ויהי' נחשב לשר ומושל, אבל כשהמלך במסיבו בהיכלו נק' נערו משרתו כו'. וגם זאת אם הי' ההנהגה מבחי' נער זה בעוד שהוא בבחי' האצי' (שנק' שר צבא הוי') כמו שר שבא ליהושע ודאי כל החסדים העליונים שבאור פני מלך באצי' הי' הכל נמשך על ידו והי' עוזר לישראל בכל צרה (והוא מיכאל כה\"ר), אבל כשיורד מאצי' לבריאה ששם נפסק אור האצי' (ונתמעט ביותר אור האצי' עד שבא לכלל בריאה יש מאין שיפול בו שכר ועונש כמו שא' אפקוה למט\"ט כו' ואפשר הי' בחי' מט\"ט דיצירה והכל אחד), והוא תכלית הקטנות דמדות עליונות דאצי' בבי\"ע עד עוה\"ז שנק' שרו של עולם העשי', ע\"כ א' ונתתי נערים שריהם בזמן הגלות דוקא והוא מטעם זה דאז בחי' שינה למעלה וכמשל הנ\"ל וכנ\"ל בענין הנני שולח מלאכי כו' וד\"ל.\n[ו] <b>אך</b> הנה באמת הרי יש סתירה לזה ממ\"ש הנה לא ינום<sup data-n=\"987\">45</sup> ולא יישן שומר ישראל ששומר לישראל בכל צרה עוזרם ומושיעם כו', ואם הי' ח\"ו בחי' שינה למעלה בשם הוי' דאצי' איך הי' שומר ישראל ובפי' א' לא ינום ולא",[["985","43","<b>עורה למה תישן. . ואנכי הסתר. . אלכה אשובה אל מקומי</b>: תהלים מד, כד. וילך לא, יח. הושע ה, טו: אלך אשובה אל מקומי עד אשר יאשמו ובקשו פני גו'."],["986","44","<b>בלילא. . רוכב הקדב\"ה על כרוב א'. . וכמ\"ש במ\"א</b>: ע\"ז ג, ב. ראה סה\"מ תקס\"ט ע' קפ ואילך. שערי אורה ס, ב. עא, א. תו\"ח תרומה תנג, ב. ועוד."],["987","45","<b>הנה לא ינום</b>: תהלים קכא, ד."]]],[1900420238,"יישן כו'. הענין הוא דאע\"פ שבחי' נער מט\"ט זה יורד מאצי' לבי\"ע אבל הנה הוא מיוחד לישראל דוקא ונקרא שר של ישראל (והוא מ\"ש מיכאל שרכם), רק שלפעמים הוא בהגבהה ומעלה גדולה כמו בימי יהושע שבא אליו לעזור לישראל בכיבוש יריחו וא\"ל אני שר צבא הוי' עתה באתי לעזרתך (והוא בחי' נער מט\"ט דאצי' כנ\"ל), ולפעמים הוא בירידה וקטנות מאד מאד והיינו כאשר ישראל בירידת המדרגה בבחי' הקטנות כמו כי נער ישראל<sup data-n=\"988\">46</sup> כו' או שהן מושפלים ביותר בין אוה\"ע ונלחצים בלחץ ודוחק אזי גם הוא בבחי' הירידה והקטנות עמהם יחד ממש שכאשר עולין עולה עמהם וכאשר יורדין יורד עמהם, שבעליית ישראל כמו בזמן בהמ\"ק דשלמה שהי' כנ\"י בתכלית העילוי (כנ\"ל) כתיב והכרובי\"ם פורשי כנפים<sup data-n=\"989\">47</sup> כו' והן אנפי זוטרי שנק' נערי\"ם דאצי' כרוב כרבי\"א<sup data-n=\"990\">48</sup>, וכן בזמן התנאים ואמוראים שמשו בבת קול כו' (וז\"ש נכנסו לפרדס ראו שמט\"ט יושב וקושר כתרים<sup data-n=\"991\">49</sup> כו'), ובזמן הגלות דשכינה עמהם בגלות וכנ\"י בתכלית הירידה יורד גם הוא עמהם ונקרא אז שומר ישראל שהוא כמו מלאך שומר ממש כמו כי מלאכיו יצוה לשמרך<sup data-n=\"992\">50</sup> כו' כך לכלל נש\"י בגלות היו מוטבעי' בי' כל צורריהם לולי שומר ישראל זה שהוא בחי' מט\"ט (שנק' שר צבא ישראל) שבכל צרתם לו צ\"ר ומלאך פניו כו' יושיעם ול\"ו צ\"ר ממש כי הוא בתכלית ההתאחדות עם ישראל וכל צרתם ל\"ו צר ממש כאילו הוא נתון בצרה זו, וכאשר נגאלי' מצרתם הרי זה יוצא ונגאל עמהם כענין שא' ליעקב אנכי ארד עמך מצריימה<sup data-n=\"993\">51</sup> שזהו ענין גלות השכינה כך בנער זה עולה ויורד עמהם בכל דור וכל זמן ועליו נאמר לא ינום ולא יישן שומר ישראל, דבכל צרה ישמור לישראל ונעשה ניסים ע\"י מלאך זה וכמ\"ש חונה מלאך ה'<sup data-n=\"994\">52</sup> סביב ליריאיו כו', וכאשר ידוע שמתלבש מלאך זה בכל דור וזמן לפי העת והשעה בכל צרת ישראל להושיעם בכמה סיבות ותחבולות וניסים נפלאים למעלה מדרכי הטבע האנושית כו' וכמאמר לא אחד בלבד עמד כו' אלא שישלח מלאך ויושיעם, וה\"ז כמו שמלאך זה יושיע א\"ע כו' וד\"ל.\n<b>והנה</b> מפני שבחי' מלאך זה שמיוחד לישראל לבדם הי' תמיד עמהם בכל הלחץ והדחק שבכל זמן הגליות, ע\"כ כאשר יבא משיח ויתעלו ישראל יתעלה גם הוא עמהם לפי שבכל צרתם הי' לו צר וישמרם בכל כחו עוז ע\"כ בעלייתם יתעלה ויתקרב גם הוא לתכלית העילוי שיהי' בזמן משיח, ומלבד שהדין נותן כך אלא מצד חיבת ישראל להראות עוז החיבה להם עד שגם",[["988","46","<b>כי נער ישראל</b>: הושע יא, א."],["989","47","<b>והכרובים פורשי כנפים</b>: ע\"פ תרומה כה, כ. ויקהל לז, ט."],["990","48","<b>כרוב כרביא</b>: ראה חגיגה יג, ב."],["991","49","<b>נכנסו לפרדס ראו שמט\"ט יושב וקושר כתרים</b>: ראה לקמן סוף אות ח. וש\"נ."],["992","50","<b>כי מלאכיו יצוה לשמרך</b>: תהלים צא, יא."],["993","51","<b>אנכי ארד עמך מצריימ'</b>: ויגש מו, ד."],["994","52","<b>חונה מלאך ה'</b>: תהלים לד, ח."]]],[1900420239,"למלאך זה יעלוהו עבור שהי' שר שלהם וירד גם הוא בירידתם לשומרם בירידתם ובכל הלחץ עמהם יחד, עד\"מ מלך גדול שחפץ להראות עוז חיבה יתירה מודעת לאנשי חילו כשניצולו מן המלחמה הקשה אז מראה חיבה וקירוב גדול לשר שלהם שהי' להם למגן ומחסה בעת צרתם ולוחצם מפני האויב והי' סובל עמהם שבזה מראה חיבה יתירה להם עד שגם שר שלהם יקרב מחמתם כי מחמת אהבתם יבא הקירוב אל השר שלהם כו', וכך יובן במלאך זה שנק' מט\"ט שמתלבש בכל צרת ישראל כנ\"ל עבור זכות ישראל יקבל קירוב ועילוי גדול ויהי' נק' אז בשם שר צבא הוי' להיות שר משנה למלך המשיח אחר שהי' לו ירידה גדולה בירידת ישראל כל ימי הגלות וד\"ל (ומ\"ש ונתתי נערי\"ם שריה\"ם דאינו לטובה ולא חשיבות כלל היינו מצד שבגלות הוא בחי' שינה וניתן ההנהגה ע\"י שרו של עולם שהוא בקטנות מאד שזהו בא מצד בחי' הקטנות דישראל כשהן בתכלית הירידה כנ\"ל והוא כאשר מעשיהם של ישראל בתו\"מ בבחי' הקטנות כנער קטן כמ\"ש כי נער ישראל כו' וכמשי\"ת).\n[ז] <b>ולהבין</b> זה בתוס' ביאור, הנה יש להקדים מ\"ש ביעקב שראה סולם מוצב ארצה<sup data-n=\"995\">53</sup> וראשו מגיע השמיימה ומלאכי אלקים עולי' ויורדי' בו. דהנה ידוע שבחי' המל' נק' תפלה ונק' ג\"כ בית תפלה וכמ\"ש ואני תפלה<sup data-n=\"996\">54</sup> אנ\"י היינו המל' ואני תפלה הכונה שאני עצמי נק' תפלה כו', וכמ\"ש למען יזמרך כבוד כו' וכן אלקים אל דמי לך בחי' אלקים עצמו קארי תדיר<sup data-n=\"997\">55</sup> לנהורא עילאה ולא שכיך כו', להיות ידוע שזהו כח הפועל האלקי בבי\"ע שעולה למעלה בבחי' העלאת מ\"ן וכמו יזמרך כבוד שהוא כבוד תחתון, וגם א' כי ביתי בית תפלה וכמ\"ש יעקב אין זה כ\"א בית אלקים<sup data-n=\"998\">56</sup> כו'. וזהו ענין הסולם שראה כידוע בזוהר שהסולם הוא צלותא<sup data-n=\"999\">57</sup> ומה שמוצב ארצה וכו' היינו סדר התפלה מב\"ש עד ש\"ע שהן ד' תיקונין דשכינתא<sup data-n=\"1000\">58</sup> שהיא כנ\"י שנק' תפלה כנ\"ל. וביאור ענין מדרגו' הסולם הזה הוא מתחיל בפסד\"ז שהן שירות ותושבחות של המלאכים שהן בבי\"ע בבחי' גבול ותכלית וה\"ז כמו עד\"מ שליבות הסולם בתחתיתו בארץ שמוצב ארצה והולכין ועולין בו מעלה מעלה, עד ראשו שמגיע השמיימה היינו ענין שתים לפניה שפוסק מלדבר במלאכים ומדבר בנשמות שגבוהים ממלאכים והוא כמו בברכת אהבת עולם אהבתנו דקאי בנשמות ומסיים הבוחר",[["995","53","<b>סולם מוצב ארצה</b>: ויצא כח, יב."],["996","54","<b>ואני תפלה</b>: תהלים קט, ד. וראה זח\"ג מט, ב: כ\"י דאיהי תפילה דכתיב ואני תפלה כו'."],["997","55","<b>למען יזמרך כבוד. . אלקים אל דמי לך. . קארי תדיר</b>: תהלים ל, יג. פג, ב. ראה זח\"ב קמ, א. זח\"א קעח, ב. עז, ב. פו, ב."],["998","56","<b>כי ביתי בית תפלה. . אין זה כ\"א בית אלקי'</b>: ישעי' נו, ז. ויצא כח, יז."],["999","57","<b>כידוע בזוהר שהסולם הוא צלותא</b>: זח\"א רסו, ב. זח\"ג שו, ב. תקוני זהר תמ\"ה (פג, א)."],["1000","58","<b>שהן ד' תקונין דשכינתא</b>: ראה זח\"ב קלג, א. ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תח. נ\"ך ע' טז. וש\"נ."]]],[1900420240,"בעמו ישראל כו', ואח\"כ הולך ועולה יותר והוא בק\"ש שהוא במדרגה עליונה יותר והוא בבחי' יח\"ע ויח\"ת דאצי' כידוע דפסוק ראשון דק\"ש מדבר בשית תיבן דיח\"ע<sup data-n=\"1001\">59</sup> ובשכמל\"ו הוא במל' דאצי' כו' וכל פרטי היחודים עליונים דאו\"א וזו\"נ עד בחי' א\"א וע\"י הכל בק\"ש דוקא, והולך ועולה יותר והוא מ\"ש וראשו מגיע השמיימה שזהו בח\"י ברכאן דש\"ע שהן ח\"י המשכות בז\"א מעצמות המאציל באמרו ברו\"ך אתה הוי' דאצי' כידוע וד\"ל (ואשר סולם זה מגיע השמיימה הן ב' מקיפים עליונים דשמים ושמי השמים<sup data-n=\"1002\">60</sup> שהוא טהירו עילאה וטהירו תתאה וכמ\"ש הן השמים ושמי השמים לא יכלכלוך). וע\"כ כנ\"י נק' ג\"כ בשם סול\"ם כזה כידוע בזוהר דמ\"ש וסולם כו' היינו כנ\"י<sup data-n=\"1003\">61</sup>, להיות ידוע דנרנח\"י שבכל איש מישראל הרי בחי' נפש שלו הוא המלובש בכח המעשה הטוב שכל איש מישראל עושה ורוח שבו הוא בדו\"ר שכליי' שבתפלתו ונשמ' במוחו הוא התענוג אלקי שבשכל האלקי כו' וחי' יחידה שבו הוא ב' מקיפים דצל\"ם שעל נפשו מגיע השמיימה, דהיינו בנר\"נ שבו עושה יחודים עליונים בנר\"נ דאד\"ם דאצי' ובבחי' חי' יחידה שבו עושה יחודים עליונים יותר עד שמגיע השמיימה בב' מקיפים שבא בצלם אדם העליון כו', והיינו בש\"ע ונפ\"א שכמו שהאדם מתפלל למטה כך בחי' אדם העליון מתפלל למעלה באצי' וכמאמר מנין שהקדב\"ה מתפלל<sup data-n=\"1004\">62</sup> כו' וד\"ל.\n<b>וזהו</b> ומלאכי אלקים עולין ויורדין בו, פי' מלאכי אלקים הן הנה בחי' שרים העליונים דאצי' שנק' נערים והן בחי' מיט\"ט וסנדל דאצי', וכשר צבא הוי' שבא ליהושע שנק' מלאך הוי' כו' כך יש מלאכי אלקים שאינם רק בשם אלקים ולא בשם הוי' דז\"א, וכמו יעקב שראה מלאכי אלקים ואמר מחנה אלקים זה כו'. והענין הוא כידוע דהמל' נק' בשם האלקים וכמ\"ש כי שמש ומגן<sup data-n=\"1005\">63</sup> ה' אלקים ומלאכים דמחנה שכינה נקראו מלאכי אלקים ולא מלאכי הוי' כו', והוא כמו בחי' מט\"ט דבריאה שר הכולל לכל מחנה שכינה כידוע בענין ד' דגלים<sup data-n=\"1006\">64</sup> וכמו דכתיב ומלאך האלקים כו' (בג' שמות דויסע ויבא ויט<sup data-n=\"1007\">65</sup> כו'). והנה מבואר למעלה שהמלאכים ושרים האלה הן הנה המתלבשים ויורדים למטה בכנ\"י שבגופים ונק' שומר לישראל וכמ\"ש כי מלאכיו יצוה לך לשמרך כו' וכמ\"כ אמר הנני שולח מלאכי לפניך כו' (כנ\"ל). והיינו מלאכי אלקים עולים ויורדים",[["1001","59","<b>כידוע דפסוק ראשון דק\"ש מדבר בשית תיבן דיח\"ע</b>: ראה זח\"א יח, ב."],["1002","60","<b>הן השמים ושמי השמים</b>: ע\"פ מלכים-א ח, כז. דברי הימים-ב ו, יח."],["1003","61","<b>בזוהר דמ\"ש וסולם כו' היינו כנ\"י</b>: ראה זח\"א קמט, ב. של\"ה לז, א."],["1004","62","<b>מנין שהקדב\"ה מתפלל</b>: ברכות ז, א."],["1005","63","<b>כי שמש ומגן</b>: תהלים פד, יב."],["1006","64","<b>כידוע בענין ד' דגלי'</b>: ראה זח\"ג קיח, ב. וביאוה\"ז לשם."],["1007","65","<b>בג' שמות דויסע ויבא ויט</b>: ע\"פ בשלח יד, יט-כא: ויסע מלאך האלקים גו' ויבוא בין מחנה גו' ויט גו'. ראה זח\"ב נב, א. פרדס שער פרטי השמות (שכ\"א) פ\"ה."]]],[1900420241,"בו פי' בסולם זה שהן כנ\"י מלאכי אלקים בחי' שרים הללו לפעמים עולין בו בעליות ישראל ולפעמים יורדין בו בירידת ישראל כנ\"ל וד\"ל.\n[ח] <b>ולהבין</b> הדבר בתוס' ביאור הנה תחלה יש להקדים משל אחד לזה, והוא כמו מלך חכם גדול והי' לו בן יקר וחביב לו ילד שעשועים ביותר אך הבן עדיין רך בשנים וילד שעשועים זה יכול להזיק א\"ע כשילך למקום מסוכן כמקומות שנחשים ועקרבים שמה או מקום לסטים וחיות רעות וכה\"ג, הנה יצוה לאחד מעבדיו המקורבים שאוהב את בנו והוא מנערי בית המלך המשרתים פני המלך וכל ביתו שילך אחרי הנער באשר הוא שם וישמרנו מכל נזק וכל פגע רע, והנה אם הי' הבן בר דעת להציל נפשו ולא לילך למקום מסוכן לא הי' צריך לשומר זה כלל אך מצד קטנותו ומיעוט דעתו צריך לשומר מעולה שישמרנו כו', אמנם אם הבן שומע לקול השומר הזה ודאי יושמר מכל דבר רע המזיק לו, אבל אם הבן אינו שומע לו כלל והולך שובב בדרך לבו גם למקומות המסוכנים או לאכול דבר המזיק (או לבתי חורבה ששם הפקר לזנות ויין כו') הנה בהכרח עפ\"י ציווי המלך שעבד זה ילך עמו כאשר ילך גם למקום המסוכן מלסטים ונחשים וחיות רעות או לבתי זונות וכה\"ג, אך שם דוקא ישמרנו מכל פגע רע שלא יוזק שם מן הלסטים והחיות ונחשים כו', כמו כאשר חשקה נפש הבן לילך למדבר נחש שרף ולסטים כו' בהכרח שילך עמו השומר הזה ואם אפשר לא ינצל גם השומר מן הרע המזיק ישים נפשו בכפו כי דבר מלך הוא ויסכן נפשו בזה על הספק אולי יכול להציל בן המלך, וא\"כ העבד הזה הולך עם בן המלך גם אם יוזק הבן יוזק גם הוא עמו וכו' וזה אין ביכולת העבד להטותו מן הדרך הרע כו'. והנמשל מובן דכנ\"י נא' בו הבן יקיר לי אפרים<sup data-n=\"1008\">66</sup> ילד שעשועים כו' וכתיב כי מלאכיו יצוה לך לשמרך בכל דרכיך בכל דרכיך ממש הן לטוב והן לרע, ועיקר השמירה לא יתכן רק במקום מסוכן דוקא והיינו כאשר ירדו כנ\"י בגלות במדב\"ר העמים בקליפ' נוג\"ה מקום חיות כמו ויאכלו את ישראל בכל פה<sup data-n=\"1009\">67</sup> כו' ולזה צריך שמירה מעולה, והוא הנק' שומר ישראל הן בחי' שרים העליונים שנק' מט\"ט וסנד\"ל, ובהכרח עפ\"י דבר מלך לשרים השומרים האלה שילכו גם המה באשר ילכו כנ\"י בגלות לסבול יסורים קשים ובכל צרת\"ם להם צר כמו שומר לבן מלך שילך ויצר במקום מסוכן עם בן המלך יחדיו יהיו בצרה אחת כו', וז\"ש לשמרך בכל דרכי\"ך, וכמו שא' על כפים ישאונך<sup data-n=\"1010\">68</sup> פן כו' על שחל ופתן כו' ששומרים הללו מצילים לכנ\"י מכל פגע רע דג' קליפות שהן שחל ופתן כפיר ותנין כו' וכמו שר של מצרים שנק' תנין כו' ובכל גלות, ואם אפשר שהמלאכים השומרים הללו לא יוזקו כ\"כ במקום מדב\"ר העמים הזה ואמנם",[["1008","66","<b>הבן יקיר לי אפרים</b>: ירמי' לא, יט."],["1009","67","<b>ויאכלו את ישראל בכל פה</b>: ישעי' ט, יא."],["1010","68","<b>לשמרך בכל דרכיך. . ישאונך</b>: תהלים צא, יא."]]],[1900420242,"ברוחניות יוזקו גם הם כמו שיוזקו כנ\"י בגשמיות ממש, וכמ\"ש מלאכי שלו\"ם מ\"ר יבכיון<sup data-n=\"1011\">69</sup> כו' הרי בוכי' במ\"ר נפשם ברוחניות על ששבתו מסילות שבת עובר אורח והן היחודים דזו\"נ שהיו מסילות כו' וד\"ל. והיינו כנ\"ל שבעליות כנ\"י גם הן עולין ובירידתם גם הם יורדי' עמהם בבחי' צער רוחני עכ\"פ (ובפרט במט\"ט דיצירה שנז' בו לשון עונש כמו דאפקוהו למט\"ט<sup data-n=\"1012\">70</sup> ומחיוהו ס' פולסי דנורא שהן ס' גבורות קשות כו'), והיינו מטעם משל הנ\"ל דשומר הבן צריך לירד במקום שהוא הולך כו', ולזאת בעליי' דכנ\"י יתעלה השומר גם הוא מפני שסבל והלך בכל אשר התהלך הבן כו' וכנ\"ל. וזהו ומלאכי אלקים עולין ויורדין בו<sup data-n=\"1013\">71</sup> בסולם הזה, דבירידת ישראל יורדין השומרים ובכל צרת\"ם להם צ\"ר ממש כנ\"ל ובעלייתם לפרקים יתעלו גם הם, וכמו מט\"ט יושב וקושר כתרים<sup data-n=\"1014\">72</sup> לקונו מתפלותיהן של ישראל דוקא שהמל' נק' תפלה שראשו מגיע' השמיימה כנ\"ל ואז גם מלאכי אלקים הללו עולין שם, ולפעמים יורדין בו תכלית הירידה כאשר תפלת ישראל אינה עולה אלא יורדת כמו גם כי תרבו תפלה<sup data-n=\"1015\">73</sup> אינני שומע כו' ואוה\"ע משתעבדי' בהם ביותר אז גם מט\"ט שר ישראל משתעבד עמהם, וע\"כ בביאת משיח יתעלה תכלית העילוי (וכמ\"ש ישכיל עבד\"י הוא עבד מיט\"ט כו' ירום ונשא וגבה מאד כו', ולא על משיח נא' שהרי משיח נק' ב\"ן כמ\"ש בנ\"י היום ילדתי\"ך<sup data-n=\"1016\">74</sup> כו' וד\"ל).\n[ט] <b>וזהו</b> קול מצהלות חתנים כו'. דהנה אע\"פ שמבואר למעלה דבחי' נערים שנק' שומר ישראל הן מלאכי אלקים עולין וגם יורדי' בעליות וירידות דכנ\"י כמו שראה יעקב בסולם שהוא כנ\"י מלאכי אלקים כו', הנה עכ\"ז אינם שוים ממש, דעליית כנ\"י למעלה הרבה מעליית הנערים מצד שרשם למעלה במדרגה עליונה יותר בהכרח שיהי' עלייתם לשרשם. ויובן זה בהקדים ענין חתנים מהו ומהו ההפרש בין חתנים לנערים ומ\"ש בחתנים מצהלות חתנים מחופתן ובנערים א' ממשתה נגינתם כו', בהיות ידוע ההפרש בין נשמות למלאכים, דשרש הנשמות הן מבחי' פנימי' אור אבא דאצי' היינו מבחי' פנימי' מוח אבא כמו עד\"מ הטפה במוח האב כו' מאחר שהנשמות נק' בנים כידוע וכמ\"ש כי אתה אבינ\"ו<sup data-n=\"1017\">75</sup> כו', וזהו מאמר ישראל עלה במחשבה<sup data-n=\"1018\">76</sup>, ופי' במחשבה אין הכונה על מחשבה סתם שבאה בצרופי אותיות הנק' לבוש לגבי",[["1011","69","<b>מלאכי שלום מר יבכיון</b>: ישעי' לג, ז."],["1012","70","<b>דאפקוהו למט\"ט</b>: חגיגה טו, א."],["1013","71","<b>ומלאכי אלקים עולי' ויורדי' בו</b>: ויצא כח, יב."],["1014","72","<b>מט\"ט יושב וקושר כתרים</b>: ראה חגיגה יג, ב: ועומד אחורי המרכבה וקושר כתרים לקונו [ובתוס' שם: מתפלתן של צדיקים כו']. זח\"א לז, ב. והערת כ\"ק אדמו\"ר שליט\"א בסה\"מ תש\"ח ע' 202."],["1015","73","<b>גם כי תרבו תפלה</b>: ישעי' א, טו."],["1016","74","<b>ישכיל עבדי. . בני היום ילדתיך</b>: ישעי' נב, יג. תהלים ב, ח."],["1017","75","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["1018","76","<b>ישראל עלה במחשבה</b>: ב\"ר פ\"א, ד."]]],[1900420243,"השכל שגם הוא איננו עצמי ממש כידוע שהשכל בא בבחי' אור גילוי בעלמא, אלא מבחי' מחשבה דחש\"ב מ\"ה<sup data-n=\"1019\">77</sup> שזהו כח מ\"ה העצמי, והוא בחי' פנימי' אור אבא הנ\"ל ששם כח המוליד בדומה לו כמו התהוות הולד מטפה שבמוח האב כו' (וכידוע בפי' מ\"ה שמו<sup data-n=\"1020\">78</sup> מ\"ה שם בנו דהיינו בחי' מ\"ה דאדם קדמאה שהוא אור אבא ומ\"ה שם בנ\"ו הוא בחי' ז\"א ונק' ישראל סבא שהולידו בצלמ\"ו כדמותו כו', והיינו ב' מיני כבוד שית'), אבל הנה שרש המלאכים באה מבחי' חיצוניו' והוא מבחי' דיבור העליון, כידוע שמן האותיות אלקיי' דהיינו דבר ה' נתהוו כל המלאכים וכמ\"ש וברוח פיו כל צבאם<sup data-n=\"1021\">79</sup> והבל פיו שבדיבור בא מצרופי אותיות המחשבה שגם היא בחי' לבו\"ש לגבי השכל כנ\"ל, ושרש אותיות המחשבה מבחי' בינה שהוא השגת השכל והבנתו בהסבר אורך ורוחב ששם מתהווה אותיות וצירופי' במחשבה שנק' לבוש להלביש השכל המושג אבל טרם שבא השכל לכלל השגה אין כאן אותיות כלל (וגם נקודת חכמה שבהעלם נק' חיצוני' יסוד אבא לגילוי אור ושפע שכל מן ההעלם ואין לו ערך לעצם בחי' הטפה שבמוח אבא להוליד בדומה לו כמ\"ש במ\"א בענין ההפרש בין איבין וזרעין<sup data-n=\"1022\">80</sup> בזוהר פ' נח הנדפס בביאורי הזוהר ע\"ש באריכות). וזהו ענין עיקר ההפרש בין נערים לחתנים, דהנה שרש חתנים הן הנשמות שמעלמא דדכורא שהוא בחי' ז\"א דאצי' (ששרשו בפנימי' אור אבא כנ\"ל בפי' מ\"ה שמו מ\"ה שם בנ\"ו כו'), ולכך נק' הנשמה אד\"ם בצלמ\"ו כו' ואין המלאך נק' אד\"ם הגם שדמות פניהם פני אדם<sup data-n=\"1023\">81</sup> ופני אדם לארבעתן<sup data-n=\"1024\">82</sup> כו' אך זהו רק בבחי' הקטנות מאד כאנפי רביא ונק' נערים כנ\"ל, והיינו מצד שרשם שהמלאכים מתהווים מבחי' האותיות דמו\"ד שהוא מבחי' בינה בחיצוניות האור כשבא לכלל השגה כנ\"ל וד\"ל.\n<b>וזהו</b> קול מצהלות חתנים מחופתן, כי הנה כתיב כי על כל כבוד חופה<sup data-n=\"1025\">83</sup>, ויש להבין מה שייך חופה לכבוד וגם על כל כבוד כמה מיני כבוד כו'. אך הנה ידוע שאור החכמה נק' כבו\"ד דגימטריא כבו\"ד הוא ל\"ב<sup data-n=\"1026\">84</sup> והן ל\"ב נתיבות חכמה שמתחלק לל\"ב שבילין ל\"ב חדרים שבמוח כידוע וכמ\"ש כבו\"ד חכמים ינחלו כו' וכמארז\"ל אין כבוד אלא תורה<sup data-n=\"1027\">85</sup> כו' וע\"כ בחי' כבוד דתורה חכמים ינחלו (ובנשמה היינו בחי' כח מ\"ה שבנה\"א בחי' ביטול בעצם לאי\"ן האלק\"י",[["1019","77","<b>דחש\"ב מ\"ה</b>: זח\"א כד, א. ובכ\"מ."],["1020","78","<b>וכידוע בפי' מ\"ה שמו</b>: ראה לעיל אות ד', ובהמ\"מ שם."],["1021","79","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["1022","80","<b>כמ\"ש במ\"א בענין הפרש בין איבין וזרעין בזוהר פ' נח הנדפס בביאוה\"ז</b>: זהר ר\"פ נח. ביאוה\"ז ה, ג. וראה סה\"מ תרל\"ד ע' יו\"ד הע' 46."],["1023","81","<b>שדמות פניהם פני אדם</b>: יחזקאל א, יו\"ד."],["1024","82","<b>ופני אדם לארבעתן</b>: ראה גם לעיל ח\"א ע' רנו, ובהמ\"מ בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'רעז."],["1025","83","<b>כי על כל כבוד חופה</b>: ישעי' ד, ה."],["1026","84","<b>דגימטריא כבוד הוא ל\"ב</b>: זח\"ג לג, א. פא, ב. ועוד."],["1027","85","<b>כבוד חכמים ינחלו. . אין כבוד אלא תורה</b>: משלי ג, לה. אבות פ\"ו מ\"ג."]]],[1900420244,"שמאיר בנשמתו למעלה מן הטעם ודעת שכלי כלל כו'). והנה ידוע שבכל אור בפרט יש בחי' א\"פ וא\"מ, וכמ\"כ בחכמה שנק' ראשית הגילוי מבחי' אי\"ן דכת\"ר וכמ\"ש והחכמה מאי\"ן תמצא וכידוע, יש בה בחי' א\"פ וא\"מ, ובחי' או\"פ שבה היינו כשנק' בשם כבו\"ד והן ל\"ב נ\"ח דהנתיבות הללו ה\"ז בא בבחי' גילוי אור ממש וכמ\"ש מאין תמצא<sup data-n=\"1028\">86</sup> כמציאה שבאה בגילוי, והיינו נקודת השכל כשמבריק מן ההעלם לגילוי אור ומתחלק לל\"ב נ\"ח כו', אבל בחי' מקיף דחכמה היינו טרם שבא אור החכמה לגילוי מן ההעלם אלא כמו שהיא בבחי' ההעל\"ם דאי\"ן (וכפשוטו דמאין תמצא כלומר מהיכן שלא נודע מציאותו) ונק' תעלומות חכמה, ולא שהיא בהעלם והסתלקות לגמרי (שזהו הנק' שכל מופלא שכל הנעלם מכל רעיון<sup data-n=\"1029\">87</sup> כו' ונק' ח\"ס סתום לגמרי) אלא שמאירה בבחי' מקיף, והוא הנק' חופה שזהו בחי' אור מקיף דחכמה וכמו החופה ממש שחופפת ע\"ג הראש הגבה למעלה כו', אך חופה זו היא מקור נעלם החופף מלמעלה לבחי' אור החכמה שמשם נובע תעלומות חכמה מן ההעלם לגילוי אור, וזהו כי על כל כבוד דחכמ\"ה חופה בחי' מקיף שלה (וכמו בחי' קרומ\"א דמחפיא על מוחא שבלתי מתחלק לל\"ב שבילין עדיין והוא נק' ח\"ס כמ\"ש במ\"א<sup data-n=\"1030\">88</sup>, דלא כדלעיל, ובנשמה היינו מקיף דצלם כ\"ח המקיף דחכמה שבנפש שמעוררו פתאום בתשובה ומעוררו לבחי' הביטול העצמי הנ\"ל וד\"ל). ומ\"ש על כל כבוד כי יש ב' מיני כבוד כבוד עליון וכבוד תחתון ונק' כבוד נאצל וכבוד נברא<sup data-n=\"1031\">89</sup> (והיינו כבו\"ד דאור אבא וזהו מי הוא זה מלך הכבוד<sup data-n=\"1032\">90</sup> כו' שנק' מלכא עילאה, וכבוד נברא הוא בבחי' תולדה שלו בז\"א שנק' מלך סתם וכן במל' שז\"ש ה' צבאות הוא כו'), ועל כל כבוד יש חופ\"ה שהן ב' מיני מקיפים א' מקיף דאור החכמה עילאה הנק' כבוד העליון והב' מקיף דחכמה תתאה כמ\"ש בס\"י שיש חכמה בראש וחכמה בסוף<sup data-n=\"1033\">91</sup> (והוא מ\"ש מ\"ה שמו מה שם בנ\"ו שהוא זו\"נ כו' כנ\"ל), והיינו כידוע דכמו שמבחי' ת\"ת דא\"א נעשה כת\"ר לאו\"א נק' חופה לכבוד העליון כך מת\"ת דאימא נעשה כת\"ר לזו\"נ והוא החופה לכבוד התחתון, וביאור כל זה מבואר ע\"פ זה בסידור<sup data-n=\"1034\">92</sup>).",[["1028","86","<b>מאין תמצא</b>: איוב כח, יב."],["1029","87","<b>הנק' שכל מופלא שכל הנעלם מכל רעיון</b>: ראה פרדס שער הנתיבות פ\"א. ובהנסמן בארוכה בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"א ע' שי."],["1030","88","<b>קרומא דמחפיא על מוחא. . כמ\"ש במ\"א</b>: זח\"א קכח, ב: בחללא דגולגלתא קרומא דאוירא דחכמתא עילאה סתימאה כו' והאי קרומא אתחפיא על מוחא כו' מוחי' אתפשט ונפיק לל\"ב שבילין כו'. וראה ביאור מאמר זוהר זה בס' מאמרי אדה\"ז על מארז\"ל ע' רעו-ז. סה\"מ תקס\"ב ח\"א ע' ע. ובכ\"מ."],["1031","89","<b>ונק' כבוד נאצל וכבוד נברא</b>: ע\"פ תקוני זהר בהקדמה (ה, רע\"א. ו, רע\"ב). רמב\"ן ויגש מו, א. וראה עוד לעיל ח\"א ע' א ובמ\"מ שם."],["1032","90","<b>מי הוא זה מלך הכבוד</b>: תהלים כד, י."],["1033","91","<b>כמ\"ש בס\"י שיש חכמה בראש וחכ' בסוף</b>: הלשון הוא בזח\"א כו, ב. זח\"ג רלח, א. וראה ס' יצירה פ\"א מ\"ז ומפרשים שם. ולעיל ח\"א ע' רכד. וס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תצה."],["1034","92","<b>וביאור כ\"ז מבואר ע\"פ זה בסידור</b>: ד\"ה כי על כל כבוד חופה בסידור קכח, ד ואילך. ומקבילו לעיל ח\"א ע' א ואילך."]]],[1900420245,"[יו\"ד] <b>וזהו</b> והוא כחתן יוצא מחופתו, דהנה בחי' חתן ל' חות דרגא הוא בחי' אד\"ם בחי' משפיע ומוליד שמעלמא דדכורא והן הנשמות ששרשם במחשבה עילאה בחי' ח\"ע כנ\"ל (שהמלאכים אין להם כח המוליד מפני שלא נק' אד\"ם כללא דדכר ונוק' רק נק' נערי\"ם כנ\"ל) והן יוצאי' מחופת\"ן הוא מבחי' המקיפים דכבוד העליון והתחתון הנ\"ל כי שרשם בבחי' מקיף דח\"ע כנ\"ל (ולמעלה היינו בחי' ז\"א שיוצא מחופתו שזהו בחי' מקיף דאבא, ומ\"ש בעטרה שעטרה לו אמו ביום חתונתו כו', וכמ\"ש במ\"א דשניהם אמת<sup data-n=\"1035\">93</sup> דגוף הכתר הנק' עטרה עטרה לו אמו אבל החופה הוא מקיף דאבא). והנה בחי' עליי' דכנ\"י עולה לשרשם שהוא בבחי' מקיף דחכמה עילאה, וכפי ערך ירידת הנשמה בגוף שנעשה בצל\"ם אד\"ם כו', כך שכרה לעלות במחשב\"ה עילאה בחי' חופה (וכמ\"ש כבוד ה' יאספך<sup data-n=\"1036\">94</sup>, וכמו בג\"ע שיש חופה לנשמות כו') דכבוד העליון, משא\"כ המלאכים ששרשם רק מבחי' אותיות דבינה שבא בבחי' צמצום גדול כשהן עולין אין עולין רק לשרשם באותיות דבינה ולא בחופה דכבוד דאור אבא כלל וד\"ל. ונמצא שגם שהמלאכי אלקים שעולין ויורדין בסולם שהוא כנ\"י היינו בזמן שישראל עולין ויורדין ממש כנ\"ל, מ\"מ אין עלייתם שוה, דעליית כנ\"י לשרשם העליון הרבה יותר מעליית הנערים שעולין לשרשם בבחי' אותיות דחיצוניות בינה בלבד כנ\"ל. וזהו כללות ענין ההפרש שבין חתנים לנערים שהן נשמות ומלאכים ואע\"פ שחונה מלאך ה' סביב<sup data-n=\"1037\">95</sup> לנשמ' שנק' יריאיו לשומרו כנ\"ל מ\"מ בעליותם למעלה הרי הנשמה עולה למעלה הרבה ולכך נק' מהלך כמ\"ש מהלכים בין העומדים האלה וכמ\"ש במ\"א<sup data-n=\"1038\">96</sup> וד\"ל.\n[יא] <b>ובזה</b> יובן מ\"ש קול מצהלות חתנים מחופתן ובנערים לא הזכיר חופה כלל אלא ממשתה נגינתם, והענין הוא דבחי' החתנים שנים כי הנשמות ששרשם מעלמא דדכורא כאשר יבאו להזדווג בנשמות שמעלמא דנוק' ה\"ז כמו בחי' יחוד וזוג עליון דזו\"נ דאצי' וכיחוד עליון יותר דאו\"א (וע\"כ א' על כל כבוד חופה ב' מיני כבוד כנ\"ל ב' מיני חופה א' חופה שעל חתן העליון שהוא אבא עילאה בזוג להוליד כו' והב' חופה שע\"ג חתן התחתון שהוא בחי' ז\"א כו') והחופה חופפת על דכר ונוק' כא' שיהי' בהם כח להתייחד ולהוליד מצד היותו אור מקיף כידוע. וזהו פי' מצהלו\"ת חתני\"ם מחופת\"ן שיוצאי' מחופתן בקול",[["1035","93","<b>וכמ\"ש במ\"א דשניהם אמת</b>: ראה גם ביאוה\"ז עו, ב."],["1036","94","<b>כבוד ה' יאספך</b>: ישעי' נח, ח."],["1037","95","<b>שחונה מלאך ה' סביב</b>: תהלים לד, ח."],["1038","96","<b>מהלכי' בין העומדים האלה וכמ\"ש במ\"א</b>: זכרי' ג, ז. ראה תו\"א ל, א ואילך. לקו\"ת בחוקותי מה, א. שלח לח, ד. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תרסז. וש\"נ בארוכה."]]],[1900420246,"רינה וצהלה שהוא בחי' חדוה וגילה עצמית שלמעלה מן הטעם מצד אור המקיף דחופה החופפת מלמעלה ולכך נק' צהלה ולא שמחה שהשמחה באה מצד גילוי אור כו', אבל הנערי\"ם אין להם בחי' חופה כלל כנ\"ל ע\"כ לא אמר בהם מחופתן אלא ממשתה נגינתם בלבד.\n<b>והענין</b> יובן בהקדים לזה ענין אחד והוא בענין ניסוך היין ע\"ג המזבח שהי' בשיר הלוים דוקא, והי' כאן ב' דברים א' ניסוך היין והב' שיר של הלוים, ואמרז\"ל על מ\"ש הגפן החדלתי תירושי המשמח אלקים ואנשים אם אנשים משמח אלקי\"ם במה משמח מכאן שאין אומרים שירה אלא ע\"ג היין<sup data-n=\"1039\">97</sup>, ולזה הי' שיר הלוים על ניסוך היין דוקא ושניהם כאחד דוקא ולא זה בלא זה, דאע\"פ שהכל ענין אחד והוא השמחה שהיין משמח אלקים כו' וגם השיר משמח אך אין אומרים שירה אלא על היין, וזה פלא לכאורה דכבר מצינו שיש שיר בלא יין כמלאכים שאומרים שיר בלא יין ויש יין המשמח בלא שיר כמ\"ש המשמח כו' ולמה צירפו שניהם דוקא. אך הנה כתיב ועבד הלוי הוא ואיתא בזוהר הוא דא הוא עתיקא<sup data-n=\"1040\">98</sup> כו', והוא בחי' פנימי' בינה שנק' הו\"א ל' נסתר שהוא בחי' הסתימות וההעלם שבבינה שם הוא גילוי בחי' עתיקא, וזה אינו מובן לכאורה דהרי נהפוך הוא דמ\"ש בע\"ח דהתגלות ע\"י בבינה היינו בבחי' התגלות דבינה דוקא וכמשי\"ת.\n<b>והנה</b> יש להקדים לזה הענין הידוע דיין המשמח הוא בבחי' בינה והיינו נכנס יין יצא סוד דסוד גימטריא ע'<sup data-n=\"1041\">99</sup> והיין גימטריא ע', ויש להבין מהו גילוי הסוד שע\"י היין יוצא הסוד הנעלם הזה לגילוי כו'. דהנה יש ג' מדרגות ביין, הא' הנק' יין המשומר בענביו<sup data-n=\"1042\">100</sup> עדיין שלא יצא לגילוי כלל, והב' יין המשמח שהוא היין הנסחט ועמד זמן מה ובא לכלל טעמו במזג נכון, והג' יין המשכר כמו בנח דכתיב וישת מן היין וישכר<sup data-n=\"1043\">101</sup> כו' וכמו בחטא עה\"ד שאשכול של ענבים סחט\"ה לו<sup data-n=\"1044\">102</sup> שהי' מעורב טו\"ר ובחי' הרע שביין הוא המסתעף ממנו כעס ורציחה (כרבה דשחטי' לר\"ז במשתה דפורים<sup data-n=\"1045\">103</sup>) ובחי' הטוב שביין הוא המביא לידי שמחה וטוב לבב דוקא כמו כאשר טוב לבו ביין כו', וכמו שנראה בחוש שבמשתה היין יטיב לב אדם ויסתעף ממנו כל טוב וחסד גם לשונאו כמו לאהובו והוא מצד השמחה שישמח לבו ויתרומם בנפשו באור הטוב והחסד",[["1039","97","<b>החלדתי תירושי. . שאין אומרי' שירה אלא ע\"ג היין</b>: שופטים ט, יג. ברכות לה, א."],["1040","98","<b>ועבד הלוי. . דא הוא עתיקא</b>: קרח יח, כג. זח\"ג קעח, ב. וראה לעיל ח\"א ע' רלח ואילך."],["1041","99","<b>נכנס יין יצא סוד. . גי' ע'</b>: עירובין סה, א."],["1042","100","<b>יין המשומר בענביו</b>: ברכות לד, ב."],["1043","101","<b>וישת מן היין וישכר</b>: נח ט, כא."],["1044","102","<b>שאשכול של ענבים סחטה לו</b>: ראה ב\"ר פי\"ט, ה. זח\"א לו, א. קצב, א. זח\"ב רסז, ב. זח\"ג רלו, א."],["1045","103","<b>כרבה דשחטי' לר\"ז במשתה דפורים</b>: מגילה ז, ב. הובא גם לעיל ח\"א ע' עדר."]]],[1900420247,"דוקא כו' מה שלא הי' בו עד הנה כו', ועוד זאת שיגלה כל מצפוני לבבו שהי' צפון ונסתר בלבו ונכנס יין יצא סוד הגנוז ונעלם בתכלית, והכל ע\"י היין המשמח דוקא, והטעם הוא כי טבע השמחה שבלב לגלות כל מצפון ולהיות טוב לב לכל, והשמחה שבאה ע\"י היין יותר נעלה ויותר יגלה ההעלם הגדול, וכמו אגברו חמרא אדרדקי כי היכי דלימרו מילתא וכמאמר דחמרא וריחא פקחין<sup data-n=\"1046\">104</sup> הרי ע\"י היין יצא סוד החכמה הגנוזה שהי' בהעלם הגדול ביותר. ויובן זה גם בעבודת ה' בשמחה שבהתבוננות שנק' בינה אם הבנים שמחה יגלה כל תעלומו\"ת לב\"ו לה' שהי' נעלם בבחי' יחידה דהיינו בחי' נקודת הלב שלמעלה מן השכל וההשגה בגדולת ה' רק רצון פשוט ועצמי כו' ואע\"פ שהתחלת התפעלות לבו לא הי' רק מצד שכל והשגה דהתבוננות זו כו' וד\"ל.\n[יב] <b>ועתה</b> יש להבין מא' אין אומרים שירה אלא ע\"ג היין כשיר הלוים דכתיב ועבד הלוי הוא דא הוא ע\"י כו'. דהנה השיר גם הוא מגלה הצפון ונעלם שבלב ומוח, כידוע בענין שיר פשוט ושיר כפול ומשולש כו' דהניגון יוצא מנקודת הלב שלמעלה מן הכונה שבמוח, ושיר הלוים שהי' שרשם מבחי' בינה בחי' השגו' אלקות בפנימי' הכונה שבמוח כשהיו אומרים המזמור כידוע בתוך זה יצא לגילוי כל תעלומות נקודת הלב שנק' שי\"ר פשו\"ט מפשטות הרצון שלמעלה מן הכונה לגמרי, וזהו ועבד הלוי הוא בפנימי' בינה שנסתר מן ההשגה, ושרשו שיר פשוט הוא בחי' התענוג העצמי להתענג על ה' מצד העצם ממש כמ\"ש במ\"א<sup data-n=\"1047\">105</sup>, וזהו כמו שמבחי' חיצוניות התענוג בא במורגש בבינה דוקא בשכל המושג שז\"ש בע\"ח דעיקר התגלות ע\"י בבינה וכמ\"ש במ\"א בענין ג' קוצין דיו\"ד<sup data-n=\"1048\">106</sup> כו', כך הוא בבחי' ההעלאה דשיר הלוים בבחי' פנימי' ע\"י שבפנימי' בינה שהוא עומק המושג שלא בא לכלל השגה ותפיסא לרוחב כלל וד\"ל. ולזה גזרו אומר דאין שיר הלוים אלא על היין המשמח להיות דיי\"ן גימטריא סו\"ד גם הוא בא להוציא הפנימי' הסוד דע\"י פנימי' העלם התענוג לגילוי, וגילוי עונג הנעלם זה הוא בפנימי' ההשגה דבינה ושניהם כאחד דוקא טובים. וזהו הנק' יין המשמח אלקי\"ם דבינ\"ה להמתיק בחי' הגבורות והדינים שלה בב' אופנים, א' שיומתק בחי' גבורות קשות דבינה שזהו הנק' יין המשכר שעושה רציחה וכעס כנ\"ל שהוא חלקי הרע דנוג\"ה שבעה\"ד טו\"ר שסחטה חוה כו' שנק' אשכלות מרורות ענבי רוש ולענה<sup data-n=\"1049\">107</sup> כו' שהחיצונים מקבלים משם. והאופן הב' הוא הגבה למעלה והיינו שיהי' בבחי' היין המשומר בענביו מוימ\"ב",[["1046","104","<b>אגברו חמרא אדרדקי. . דחמרא וריחא פקחין</b>: סנהד' לח, א. יומא עו, ב."],["1047","105","<b>שיר פשוט. . מצד העצם ממש כמ\"ש במ\"א</b>: ראה לעיל ח\"א ע' י, ובהמ\"מ שם."],["1048","106","<b>בע\"ח דעיקר התגלות ע\"י בבינה וכמ\"ש במ\"א בענין ג' קוצין דיו\"ד</b>: תו\"ח לך לך פא, ב ואילך. וראה תו\"א יא, סע\"ב [ובהמ\"מ שם]. שם פ, ב. ס' מאמרי אדה\"ז עה\"ת ס\"ע פד ואילך [ושם ר\"ע פח ג\"כ בענין ג' קוצין דיו\"ד]."],["1049","107","<b>אשכלות מרורות ענבי רוש ולענה</b>: ע\"פ האזינו לב, לב. [ובצירוף לשון הפסוק דנצבים כט, יז]."]]],[1900420248,"כו' שהוא המשומר ממגע נכרי כו' דהיינו שאין שליטה לחיצונים שם כלל וכלל כידוע. והענין הוא דיין זה נק' חמרא דמנטרא<sup data-n=\"1050\">108</sup> שסודו נעלם לגמרי ולא יצא לגילוי מעולם כיין הגנוז בענביו כו', וזהו למעלה הרבה מיין המשמח. וביאור הדבר הנה דוגמא לדבר יין ישן שדעת זקנים<sup data-n=\"1051\">109</sup> נוחה כו' ולא דעת נערים כו', דמ\"ש אגברו חמרא אדרדקי היינו יין המשמח שיבא כל תעלומות שבמוחי' שלהם לגילוי והן נק' אנפי זוטרי דרדקי שהן בקטנות המוחין כנערים כו' והגילוי שלהם בא ממקיפים דנר\"נ שלהם לבד שהוא רק מבחי' הקטנות דבינה אם הבנים כו' כנ\"ל בענין נכנס יין יצא סוד והוא כעונג מורגש בשכל גלוי בטוב טעם, אבל בחי' עונג הנעלם שלמעלה גם מן החכמה שנק' טעם כמוס זהו יוצא ע\"י יין ישן דוקא והוא יין המשומ\"ר שיתפרש שיושב על שמריו זמן רב כחמר טב דיתיב על דורדייא<sup data-n=\"1052\">110</sup> כו' (והוא יין החזק ביותר והיינו כיין הכנוס ומשומר בענביו שיש בו כל זה החיזוק ממש רק שהוא בהעלם), והוא יין שדעת זקנים שקנה חכמה ממקורה מבחי' א\"ס שיצא לגילוי שהוא בחי' ההעלם העצמו', וכנ\"ל בענין שיר פשוט שנק' תעלומות לב כו' שאינו מורגש כלל כי עצמות ההעלם שמתגלה כו', וע\"י השיר ביין ע\"ג המזבח יומשך מבחי' ההעלם העצמי. וזהו ועבד הלוי הוא דא הוא ע\"י להמתיק לבחי' יי\"ן המשמח ג\"כ דהיינו שלא יבא לכלל בחי' גבורות קשות שביין אחר שיעלה לבחי' יין המשומר ממגע נכר\"י שהוא עצמות התענוג הפשוט שדעת זקנים נוח\"ה הימנו כנ\"ל שנמצא בחי' הקטנות שביין בא לבחי' הגדלות דיין המשומר כו', וזהו ע\"י השיר על היין דוקא שהשיר ממתיק היין המשמח אלקים והיין פועל בחי' שרש השמחה שיבא לגילוי למטה ולא ישאר למעלה, ולכך אין אומרים שירה אלא על היין וד\"ל.\n<b>וזהו</b> ממשת\"ה נגינת\"ם שיר ומשתה יין שניהם כאחד דוקא, מפני שבחי' הנערים מיט\"ט וסנד\"ל כו' שנק' אנפי זוטרי שמחתם הוא בבחי' בינה בבחי' הקטנות כדרדקי כנ\"ל, וע\"י היין המשמח שלהם יצא סוד דבינה לגילוי, וזהו משת\"ה נגינתם שיר ויין שניהם כאחד דוקא מטעם הנ\"ל וד\"ל, וזהו עלייתם לשרשם בפנימי' בינה שהוא פנימי' ע\"י הגנוז שם כנ\"ל לע\"ל דוקא אחר שסבלו כל ירידות דכנ\"י כמ\"ש תנו יין למרי נפש<sup data-n=\"1053\">111</sup> להעלותם לשרשם, וזהו ונערים ממשתה נגינת\"ם, אבל עליי' דכנ\"י שנק' חתני\"ם לבחי' מקיף דח\"ע ח\"ס הוא הגבה למעלה גם מפנימי' בינה שהרי שם שורה עצמות השעשועים שבעצמות א\"ס ממש כמ\"ש אז תתענג על ה' על ה' ממש, והוא מצהלות חתנים כנ\"ל שלמעלה מן השמחה מצד המקיף דחופה וכמ\"ש עוז וחדוה",[["1050","108","<b>חמרא דמנטרא</b>: זח\"ג ד, א. ועוד."],["1051","109","<b>יין ישן שדעת זקנים</b>: מגילה טז, ב."],["1052","110","<b>כחמר טב דיתיב על דורדייא</b>: זח\"ג קכח, ב."],["1053","111","<b>תנו יין למרי נפש</b>: משלי לא, ו."]]],[1900420249,"במקומ\"ו דוקא. ומ\"מ צהלות חתנים שנים הנ\"ל ומשתה נגינתם דנערים הנ\"ל הכל בזמן א' שהוא לע\"ל שע\"ז א' מהרה ישמע קול ששון כו' שזהו בחי' שמחה דנערים קול חתן וכלה הוא ענין מצהלות חתנים ומפרש דבריו במ\"ש קול מצהלות כו', וכן מ\"ש תחלה אשר ברא ששון בריאה יש מאין הוא שמח' דנערים חתן וכלה גילה רינה כו' הכל בחופה דדכר ונוק' שנק' אד\"ם בצלם אלקים שהוא זווג נשמות ששרשם ביחוד פנימי' דאו\"א כנ\"ל וכמשי\"ת ב\"ה.\n[יג] <b>והנה</b> מעתה יש להבין<sup data-n=\"1054\">112</sup> סדר הדברים במ\"ש מהרה ישמע בערי יהודה כו' קול ששון וקול שמחה קול חתן וקול כלה קול מצהלות חתנים כו'. דהנה יש לדקדק במ\"ש מהרה ישמע ל' עתיד ולא עתה ומה ענין הקול חתן וקול כלה שישמע לעתיד דוקא ולא עכשיו, וגם מה שכפל לומר קול חתן בפ\"ע וקול כלה בפ\"ע הל\"ל קול חתן וכלה, ומהו ענין הרמת קול שמחה לחתן וכלה. ויש עוד להבין ענין שינוי הנוסח דברכת אשר ברא שחותם משמח חתן עם הכלה ולא חתם משמח חתן וכלה כמו בברכת שמח תשמח כו'. ויש להקדים תחלה ענין ההפרש בין אירוסין לנישואין, דהנה ארז\"ל במס' מנחות על משה יבא טוב<sup data-n=\"1055\">113</sup> ויקבל טוב מטוב כו' טוב זו תורה כו', ויש להבין הלא כבר ניתנה התורה ודבריו חיים וקיימים ולמה יצטרך עוד הפעם לקבלת התורה. אך הנה ידוע דאורייתא סתים וגליא וקודב\"ה סתים וגליא וגם כנ\"י סתים וגליא וג' אלה מתקשראן בקשר אחד ממש וכמאמר הזוהר ג' קשרין הן<sup data-n=\"1056\">114</sup> ישראל מתקשראן באורייתא ואורייתא בקודב\"ה כו', ובג' אלה הוא ההפרש בין מ\"ת שע\"י משה ובין קבלת התורה בימי משיח (שהוא משה כידוע דפנימי' אבא הוא פנימי' ע\"י<sup data-n=\"1057\">115</sup> וזהו יבא טוב ונק' גואל ראשון וגואל אחרון וכמ\"ש אם יגאלך טו\"ב<sup data-n=\"1058\">116</sup> כו'). דהנה אורייתא סתים וגליא בחי' גליא הנגלות שבתורה ניתנה במ\"ת כמ\"ש ביום חתונתו זו מ\"ת<sup data-n=\"1059\">117</sup> וזהו בחי' אירוסין לבד, ובחי' סתים שבהן שהן הנק' טעמי תו\"מ שלא נגלו אז רק יתגלו לע\"ל וכמ\"ש ישקני מנשיקות פיהו שהן טעמי מצות כדפרש\"י<sup data-n=\"1060\">118</sup> וזהו קבלת התורה פנימי' בימי משיח מחדש ממש כמו שניתנה בחי' חיצוניות החלק הנגלה שבה (וכמ\"כ קודב\"ה דסתים וגליא במ\"ת",[["1054","112","[יג] והנה מעתה יש להבין [בכת\"י 2026 נרשם לפני פיסקא זו כותרת: ”ביאור\"]. מכאן (עד אות יט) מיוסד על ד\"ה מהרה ישמע — בסידור עם דא\"ח קלח, ב. ומקבילו לעיל ד\"ה אשר ברא (השני), וראה בהמ\"מ לשם."],["1055","113","<b>במס' מנחות יבא טוב</b>: מג, ב."],["1056","114","<b>דאוריי' סתים וגליא. . הזוהר ג' קשרין הן</b>: ע\"פ זח\"ג עג, א."],["1057","115","<b>דפנימי' אבא הוא פנימי' ע'</b>: [עתיק]. פע\"ח שער הק\"ש פט\"ו. וראה בהנסמן ע\"ז בארוכה בהערת כ\"ק אדמו\"ר שליט\"א בסה\"מ ה'ת\"ש ע' 49. וס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תרצה. ולעיל ח\"א ע' קט."],["1058","116","<b>אם יגאלך טוב</b>: רות ג, יג."],["1059","117","<b>ביום חתונתו זו מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."],["1060","118","<b>ישקני מנשיקו' פיהו. . כדפרש\"י</b>: שה\"ש א, ב."]]],[1900420250,"דכתי' וירד ה'<sup data-n=\"1061\">119</sup> הי' בחי' גילוי בחי' חיצוניות לבד ובחי' סתים שבו שנק' סתימא דכל סתימין יתגלה לעתיד, וכמ\"כ נש\"י שהיו במ\"ת בגופים הוא בחי' גליא ומ\"ש וגם אשר איננו פה<sup data-n=\"1062\">120</sup> קאי על הנשמות שיסתעפו דור אחר דור, אבל נשמות חדשות לגמרי או שרש הנשמות כולן כמו שהן במקורן הוא בחי' סתים שעליהם א' כולך יפה כו' שחתומים ונעלמים באוצר הנשמות כו' והן יתגלו לעתיד וד\"ל).\n<b>והנה</b> ההפרש בין חיצוניו' הנגלה לנסתר שבה ידוע שזהו הנק' פנימי' וחיצוניות בחכמה דאורייתא מחכמה נפקת וכך הוא ההפרש בבחי' העונג העליון שמלובש בחכמה יש בו פנימי' וחיצוניות (והוא ענין פנימית אבא שהוא פנימית ע\"י וחיצוניות אבא הוא חיצוניות ע\"י כו'). וביאור הדברים ידוע דבתורה נאמר ואהי' אצלו אמון<sup data-n=\"1063\">121</sup> שעשועים יום יום, ויש בזה ב' ענינים, א' בבחי' החכמה שנק' התורה חכמה הקדומה שקדמה לעולם אלפים שנה<sup data-n=\"1064\">122</sup> וכמ\"ש כאשר יאמר משל הקדמונ\"י<sup data-n=\"1065\">123</sup> וגם א' נובלות חכמה של מעלה תורה<sup data-n=\"1066\">124</sup>, והענין הוא דחכמה של מעלה הוא שרש החכמה הנגלית שבתשב\"כ ושבע\"פ והוא בחי' פנימי' חכמתו העצמית שהוא חכמה דא\"ס בבחי' פנימי' שבו היינו שבה בחי' גילוי אור עצמותו ממש וז\"ש ואהי' אצלו ממש אמון אמון מופל\"א<sup data-n=\"1067\">125</sup> בסדכ\"ס כו' ורק בחי' הנובלות דחכמה של מעלה הוא בחי' גליא שבתורה וז\"ש הנסתרות לה' כו' (וכמ\"ש במ\"א בפי' ותמלא כד\"ה כו' זהו כ\"ד ספרים<sup data-n=\"1068\">126</sup> דאורייתא כמו עד\"מ השואב בכד מים הגדול כו'), וכמו דאורייתא מח\"ע נפקת יש בזה פנימי' וחיצוניות כנ\"ל כך בבחי' התענוג העליון שבח\"ע דתורה שנק' שעשועים יש בזה ממילא ג\"כ בחי' פנימי' וחיצוניות, והיינו מ\"ש ואהי' אצלו כו' שעשועים עצמיים שנק' בחי' שעשועי המלך בעצמו היינו מצד עצמותו, והוא בחי' התענוג הפשוט שבאחדות הפשוטה שאינו מדבר שחוץ ממנו כלל וכלל כו' וד\"ל, והוא הנק' פנימי' התענוג שבח\"ע ונק' עתיקא דעתיקין, והוא בחי' סוד ה' הגנוז ונעלם בכל דין ודין מדיני התורה הנגלית (וכמו שגם עכשיו בג\"ע",[["1061","119","<b>וירד ה'</b>: יתרו יט, כ."],["1062","120","<b>וגם אשר איננו פה</b>: ע\"פ נצבים כט, יד. תנחומא נצבים ג. פדר\"א פמ\"א. שמו\"ר ספכ\"ח. זח\"א צא, א. זח\"ב פג, ב. תקוני זהר תמ\"ט (פו, א)."],["1063","121","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1064","122","<b>שקדמ' לעולם אלפים שנה</b>: מדרש תהלים צ, ד. ובכ\"מ."],["1065","123","<b>כאשר יאמר משל הקדמוני</b>: שמואל-א כד, יג. ראה לעיל ח\"א ע' צא וע' צו. וש\"נ."],["1066","124","<b>נובלות חכמה שלמעלה תורה</b>: ב\"ר פי\"ז, ה."],["1067","125","<b>אמון מופלא</b>: ב\"ר בתחילתו."],["1068","126","<b>הנסתרות לה'. . במ\"א בפי' ותמלא כדה. . כ\"ד ספרי'</b>: נצבים כט, כח. חיי\"ש כד, טז. ראה תקוני זהר תכ\"א (מו, ב). סה\"מ תקס\"ט ע' ב ואילך. תו\"ח חיי\"ש קכח, א. קלד, ב. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תרסו. דברים ח\"א ע' רכו. לעיל ח\"א ע' צא."]]],[1900420251,"לומדים רזין וסודות דתשבע\"פ דוקא וכמו עובדא דרבה בר נחמני בדין דאם בהרת קדמה לשער לבן כו' וכמ\"ש במ\"א<sup data-n=\"1069\">127</sup>), וכמו שנובלות חכמה של מעלה לבד בבחי' הנגלה שבתורה כך רק בחי' נובלות וחיצוניות התענוג הפשוט שנק' שעשועים העצמיים הנ\"ל נמשך בבחי' גליא שבתורה, וזהו משחקת לפניו בתבל ארצו כשירדה התורה למטה וכן ושעשועי את בני אדם<sup data-n=\"1070\">128</sup>, והוא הנק' חיצוניות ע\"י שבחיצוניות ח\"ע (ומלובש בבחי' טעמים ונקודות שבתורה, וכידוע בענין טנת\"א דהטעמים בכת\"ר<sup data-n=\"1071\">129</sup> כו', ומ\"ש טוב טעם ודעת למדני<sup data-n=\"1072\">130</sup> היינו בחי' טעמי תורה הגנוזים בנגינות הללו ונק' רננה דאורייתא וכמ\"ש ובלילה שירה כו' וכן א' זמירות היו לי חוקיך<sup data-n=\"1073\">131</sup> כו', וזהו שיר השירים כו' ישקני מנשיקות כו' שהן טעמי תורה כנ\"ל).\n<b>והנה</b> לפי שמבואר למעלה בענין ג' קשרין דאורייתא וקודב\"ה וישראל ממילא מובן דכמו שההפרש בין מ\"ת לע\"ל הוא בין הפנימי' לחיצוניו' שבתענוג וחכמה, כך הוא ממש ההפרש בשני אלה בבחי' סתים וגליא שבהם, דמאחר דישראל מתקשראן באורייתא ידוע דס\"ר נש\"י כל אחד יש לו אות אחת בתורה שלנו הנגלית, ואם במ\"ת הי' רק בחי' חיצוניות ח\"ע וחיצוניות התענוג העליון כך בנש\"י הי' הגילוי בס\"ר נשמות שהיו אז בגופים (ומה שעל כל דיבור פרחה נשמתן<sup data-n=\"1074\">132</sup> למעלה מעלה היינו כמו שהנשמות בשרשן למעלה כו') שהן רק בצלם ודמות אד\"ם העליון בבחי' החיצוניות לבד, אבל בחי' סתים שבהן היינו כמו שהנשמות בשרשן העצמי והוא כמאמר ישראל עלה במחשבה<sup data-n=\"1075\">133</sup> שהוא מחשב\"ה העצמית הקדומה הנ\"ל שהיא חכמה שבתורה דכתיב בה ואהי' אצלו אמון כנ\"ל דישראל מתקשראן שם באורייתא הקדומה כו' לא הי' בהן קבלת התורה שלהם בפנימי', עד לע\"ל שיקבלו אותן הנשמות בחי' תורה הפנימי' הנ\"ל. וזהו כאשר התורה נק' חתן וכנ\"י נק' כלה וכמ\"ש ביום חתונתו וכנ\"י נק' כלה שמקבלת מן החתן כו'. ואמנם ודאי כמו שישראל מתקשראן ומקבלי' מאורייתא כל ניצוץ אות אחת והכל בבחי' גליא, כך אורייתא מתקשרא בקודב\"ה שאז התורה נק' כלה וכמ\"ש מאורש\"ה<sup data-n=\"1076\">134</sup> כו' וקודב\"ה נק' סתים וגליא, והיינו ההפרש בין",[["1069","127","<b>עובדא דרבה בר נחמני. . במ\"א</b>: ב\"מ פו, א: קא מיפלגי במתיבתא דרקיעא אם בהרת קודמת כו'. ונת' בס' מאמרי אדהאמ\"צ ויקרא ח\"ב בתחילתו. וש\"נ. וראה גם לעיל ח\"א ע' צט."],["1070","128","<b>משחקת לפניו. . את בני אדם</b>: ע\"פ משלי שם."],["1071","129","<b>וכידוע. . דהטעמי' בכתר</b>: ראה לעיל ד\"ה אשר ברא (השני). וש\"נ."],["1072","130","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו."],["1073","131","<b>רננה דאוריי'. . ובלילה שיר'. . זמירות היו לי חוקיך</b>: זח\"ג כג, ב. תהלים מב, ט. קיט, נד. וראה לעיל ח\"א ע' רנו."],["1074","132","<b>שעל כל דיבור פרחה נשמתן</b>: שבת פח, ב."],["1075","133","<b>ישראל עלה במחשבה</b>: ב\"ר פ\"א, ד."],["1076","134","<b>שאז התורה נק' כלה וכמ\"ש מאורשה</b>: ברכות נז, א. ראה לעיל ד\"ה להבין שבברכה ראשונה, קרוב לתחילתו. וש\"נ."]]],[1900420252,"שעשועי המלך בעצמו לשעשוע ותענוג הנמשך למטה לגבי המקבלים (וכידוע דבחי' ע\"י ממוצע בין עצמות המאציל לנאצלים ומה שהוא ראש לנאצלים הוא בחי' חיצוניות התענוג בלבד ומה שיש בו מבחי' האחרונה שבעצמות עולם הא\"ס הוא בחי' פנימי' ע\"י בכלל כידוע), ובחי' גליא דאורייתא מקבל מבחי' גליא דא\"ס שהוא בחי' חיצוניות התענוג שבעצמותו כנ\"ל אבל בחי' סתים שבו שבעצמותו ממש לא בא לידי גילוי כלל במ\"ת רק לע\"ל הכל יהי' בבחי' סתים דוקא והיינו כל ג' אלה הקשרין דישראל באורייתא ואורייתא בקודב\"ה שהוא עצמות המאציל כו' יהיו בבחי' הסתים שבהן שהן בבחי' פנימי' התענוג שבעצמות שנק' ארץ חפ\"ץ חפצי בה<sup data-n=\"1077\">135</sup> כו' ויקבלו התורה מבחי' פנימי' שבתענוג העליון כנ\"ל ואורייתא ג\"כ מתקשראת אז בקודב\"ה בפנימי' ועצמות השעשועים כמו שהי' קודם שנאמר ואהי' אצלו כו' (וגם כבר הי' לעולמים בדוגמא דלע\"ל בדוד שהי' מחבר תורה של מעלה בהקדב\"ה כמ\"ש במדרש<sup data-n=\"1078\">136</sup> לפי שהוא בחי' מל' משיח וכמ\"ש נאם דוד בן ישי הקים עול של תורה וזהו ואלה דברי דוד האחרונים וכמ\"ש במ\"א<sup data-n=\"1079\">137</sup> וד\"ל).\n[יד] <b>ומעתה</b> הנה יש להבין ענין ההפרש בין אירוסין לנישואין דבמ\"ת הי' בבחי' אירוסין לבד כמ\"ש תורה צוה לנו משה מאורשה<sup data-n=\"1080\">138</sup> כו' ולע\"ל בקבלת התורה פנימי' כנ\"ל יהי' בבחי' נישואין וכמ\"ש ביום ההוא תקראי לי אישי ולא בעלי כו', דמ\"ש כי בועליך<sup data-n=\"1081\">139</sup> עושיך זהו ביום שמחת לבו דבנין בהמ\"ק ונתגרשה וכמ\"ש ובפשעיכם שולחה אמכם<sup data-n=\"1082\">140</sup> כו', ובאמת ביום שמחת לבו קאי לע\"ל כו'. דהנה לכאורה יש להבין בענין הנ\"ל שבמ\"ת לא הי' הגילוי רק מבחי' חיצוניות העונג העליון כו' והוא חיצוניות אא\"ס שבתורה כו' והלא אמר וירד ה' על הר סיני וכשירד ודאי כל עצמותו ירד כמו שהוא בבחי' פנימי' שלו וגם הרי בפי' א' אנכי ה' כו' ופי' אנכי מי שאנכי<sup data-n=\"1083\">141</sup> בחי' סדכ\"ס דלא ידע לי' בר איהו<sup data-n=\"1084\">142</sup> כו' וכמ\"ש צאנה וראינה כו' בעטרה שעטרה לו אמו ביום חתונתו<sup data-n=\"1085\">143</sup>",[["1077","135","<b>ארץ חפץ חפצי בה</b>: מלאכי ג, יב. ישעי' סב, ד [וראה לעיל ח\"א ע' רל. וש\"נ]."],["1078","136","<b>בדוד שהי' מחבר. . כמ\"ש במדרש</b>: ראה זח\"ג רכב, ב. ובלקו\"ת שלח נא, א בשם ס' הבהיר ומעיין החכמה. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תתסז. דברים ח\"ג ע' תשפג [ובהמ\"מ שם]."],["1079","137","<b>נאם דוד. . ואלה דברי דוד. . במ\"א</b>: שמואל-ב כג, א. וראה תו\"ח בראשית כא, ג. נח סג, א. אמרי בינה שער הק\"ש לח, ג. מח, ג. ועוד."],["1080","138","<b>תורה. . מאורשה</b>: ברכה לג, ד. ובהנסמן לעיל בסמוך."],["1081","139","<b>נישואין. . ביום ההוא תקראי לי אישי. . כי בועלייך</b>: בשמו\"ר ס\"פ ט\"ו [והובא בלקו\"ת שה\"ש מח, א]: העוה\"ז אירוסין היו שנאמר וארשתיך לי לעולם כו' אבל לימות המשיח יהי' נישואין שנאמר כי בועלייך עושייך. הושע ב, יח: והי' ביום ההוא נאום ה' תקראי אישי ולא תקראי לי עוד בעלי [וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ד ע' א'רס ואילך]. ישעי' נד, ה."],["1082","140","<b>ובפשעיכם שולחה אמכם</b>: ישעי' נ, א."],["1083","141","<b>אנכי מי שאנכי</b>: ראה לעיל ח\"א ע' רנט. וש\"נ."],["1084","142","<b>דלא ידע לי' בר איהו</b>: ראה זח\"ג קכט, ב. קמ, ב."],["1085","143","<b>צאנה וראינה. . ביום חתונתו</b>: שה\"ש ג, יא. וראה תענית כו, ב."]]],[1900420253,"כו' ומבואר בזוהר שכל אורות הגנוזים ונעלמים בעצמות עולם הא\"ס באו לגילוי בזמן מ\"ת<sup data-n=\"1086\">144</sup> כו' ואיך נאמר שלא הי' אז הגילוי רק בחיצוניות כו'. אך הנה הענין הוא דודאי מ\"ש וירד ה' כל בחי' עצמותו ירד אך א\"כ הי' העולם מזדכך מחומריותו שנעשה ע\"י חטא עה\"ד כו', וגם שהי' חירות גם ממלאך המות<sup data-n=\"1087\">145</sup> לולי חטא העגל אח\"כ עכ\"ז לא היתה ירידה זו כמו שיהי' לע\"ל דכתיב ונגלה כבוד ה' וראו כל בשר שיהי' גילוי אא\"ס למטה כמו למעלה ממש משום דאת רוח הטומאה<sup data-n=\"1088\">146</sup> אעביר כו', ומוכרח לומר שירידת ה' על הר סיני בגילוי הי' רק מבחי' גליא שבו דקודב\"ה סתים וגליא וכל בחי' אורות העליונים דע\"ס דאצי' ולמעלה מעלה הגנוזים בעצמות המאציל אע\"פ שגם הם באו ונמשכו למטה וכמ\"ש בעטרה כו' מבחי' מקיפים דע\"י וא\"א כו' אבל כולם היו בבחי' ההעלם וההסתר על בחי' הגילוי היינו בבחי' אור מקיף ולא בא בחי' הסתים שהוא פנימי' אור א\"ס שבפנימי' ע\"י כו' לידי גילוי גמור בבחי' או\"פ רק הי' בבחי' מקיף על האו\"פ וסובב עליו מכל צדדיו כו', ולא שהי' בהעלם והסתלקות לגמרי אלא אדרבה הי' הכל שם רק שנשארו בהעלם על אור הגילוי שבא בבחי' או\"פ, וכמו הדיבור אנכי כו' ודאי הי' בבחי' גילוי גמור אך מה שהי' גנוז ונעלם בבחי' מקיף על הדיבור הוא בחי' פנימי' אור א\"ס שבטעם ועונג העצמו' ובחי' פנימי' ח\"ע שבזה הדיבור ע\"כ על כל דיבור פרחה נשמתן כו', והוא ענין המא' שכפה עליהם ההר כגיגי\"ת<sup data-n=\"1089\">147</sup> בבחי' מקיף כו' וד\"ל. ונמצא שההשפעה הפנימי' שהוא פנימי' האור מאור א\"ס שבי' הדברות הי' נמשך בבחי' מקיף שהוא בהעלם ולא בגילוי גמור, וזהו הנק' בחי' אירוסין וכמ\"ש וארשתיך לי באמונה כו' (ואע\"פ שכל העם רואים<sup data-n=\"1090\">148</sup> את הקולות כו' ראו רק בחי' הגילוי אור דא\"ס שבא בבחי' קול ודיבור אבל בחי' הפנימי' דאור א\"ס שהי' בבחי' העלם ומקיף הי' מאיר עליהם בבחי' מקיף והן העדיי\"ם שנק' כתרי\"ם).\n<b>דהנה</b> ענין האירוסין ידוע שלוקח הטבעת העגול ונותן על אצבעה ואומר הרי את מקודשת לי, שהעיגול דטבעת קידושין מורה בחי' היקף המקיף דמשפיע והוא אור שפע המקיף להקיף את המקבל שיוקרב ויוקדש אליו ביחוד ועדיין לא בא ליחוד אך זהו עיקר ומקור לכל יחוד וזווג שיהי' אח\"כ כי באמרו הרי את מקודשת לי מתקדשת ומזומנת לו ליחוד וקנאה בקידושי' אלה כידוע ופי' מקודשת מזומנת גם הוא ל' קדש מובדל מאיש זולתו ומקודשת בבחי' קד\"ש עליון אליו, והוא האירוסין שמקדש האשה בכסף והאשה נקנית בג'",[["1086","144","<b>בזוהר שכל אורות הגנוזו'. . לגילוי בזמן מ\"ת</b>: זח\"א קפז, א. זח\"ב פא, א. צג, ב."],["1087","145","<b>חירות גם ממלאך המות</b>: ראה שמו\"ר פל\"ב, א. פמ\"א, ז."],["1088","146","<b>ונגלה. . דאת רוח הטומא'</b>: ישעי' מ, ה. זכרי' יג, ב."],["1089","147","<b>שכפה עליהם ההר כגיגית</b>: שבת פח, א."],["1090","148","<b>וארשתיך. . שכל העם רואי'</b>: הושע ב, כא. יתרו כ, טו."]]],[1900420254,"דרכי'<sup data-n=\"1091\">149</sup> בכסף ושטר כו'. והענין הוא למעלה כידוע דכנ\"י נק' אשה וכתי' וארשתיך לי כו', דבמ\"ת הי' בבחי' אירוסין כמ\"ש ביום חתונתו היינו שקיבלו התורה בבחי' מקיף דקידושין כמו הרי את מקודש\"ת דכנ\"י נעשית מקודשת להקדב\"ה, והוא המקור לכל יחוד וזווג שיהי' אח\"כ והיינו לע\"ל שיהי' בחי' נישואין, כי כל מה שהי' בהעלם באירוסין דמ\"ת הכל יבא בבחי' גילוי גמור בכנ\"י לע\"ל, כמו בבחי' יחוד וזווג שנק' נישואין שבא אור שפע המשפיע למקבל בגילוי גמור והוא הנק' קליטה כידוע, והיינו ענין טעמי תורה שהוא פנימי' אא\"ס שבפנימי' טעמי תו\"מ יומשך בכנ\"י בהתגלות גמור בבחי' כלי כמאמר אין האשה כורתת ברית<sup data-n=\"1092\">150</sup> אלא למי שעשאה כלי בית קיבול לקבל אור ושפע דמשפיע בגילוי ובאופן ערך שפע המשפיע דוקא, ולהיות שלע\"ל יהי' התגלות כל עצמו' אא\"ס שבתורה (שאז גם התורה בבחי' א\"ס כמ\"ש ארוכה מארץ מדה<sup data-n=\"1093\">151</sup> ורחבה מני ים ארץ וים ב' ההי\"ן כו' והוא פנימי' התורה) יהי' כנ\"י בית קיבול לקבל כל המרחב שבעצמות אא\"ס, ולכך נק' ארץ חפ\"ץ ונק' ארץ טובה ורחבה בלי גבול (משא\"כ עכשיו כו'). וז\"ש ביום ההוא תקראי לי אישי<sup data-n=\"1094\">152</sup> כו' ולא עתה שלא הי' רק אירוסין וכמ\"ש וארשתיך לי כו'. וזהו האשה נקנית בכסף הוא בחי' האירוסין בטבעת קידושין בעיגול בחי' מקיף לבד כנ\"ל, ובביאה הוא בחי' נישואין ביחוד וזוג היינו לע\"ל כנ\"ל.\n<b>(ונמצא</b> מובן מזה דבחי' אירוסין שהי' במ\"ת שהי' בחי' מקיף יהי' בבחי' או\"פ לע\"ל, וז\"ש וארשתיך לי באמונה וידעת כו' דעכשיו בחי' האמונה בכנ\"י בבחי' מקיף בלבד וכן בחי' הדעת שיודעי' ומשיגי' הכל מרחוק ה' נראה להם ולא בגילוי גמור, וגם כל המצות מעשיות שישראל עושין עכשיו הכל נעשה למעלה בחי' יחודי' עליוני' דקודב\"ה ושכינתי' ושורה בהעלם ומקיף בלבד, ומ\"ש אלה המצות אשר יעשה אותם האדם וחי בהם<sup data-n=\"1095\">153</sup> היינו בבחי' מקיף על נשמתו שנק' לבושי', ולע\"ל יבאו בגילוי, והוא העוה\"ב שיש לכאו\"א מישראל ע\"י המצות שעשה בעוה\"ז כידוע, ואמנם בבחי' גליא שבג' קשרין הללו הרי בחי' האירוסי' שהי' במ\"ת בהעלם אינו רק לגבי הנישואי' דלע\"ל שכל זה בבחי' הפנימי' הנק' סתים, אבל בחי' הנגלה הבא למעשה כמ\"ש והנגלות לנו ולבנינו<sup data-n=\"1096\">154</sup> כו' הוא בא לבחי' נישואין ביחוד גמור גם עכשיו והן כל מעשה המצו' שנעשה יחוד קודב\"ה ושכינתי' אלא שאין זה בבחי' הפנימי' שנק' נסתרות לה' אלקינו ולע\"ל גם הפנימי' יתגלו ואין גילוי זה דלע\"ל רק מסיבת",[["1091","149","<b>והאשה נקנית בג' דרכי'</b>: קידושין ב, א. וראה לעיל ד\"ה אשר ברא (השני). וש\"נ."],["1092","150","<b>אין האשה כורתת ברית</b>: סנהד' כב, ב."],["1093","151","<b>ארוכה מארץ מדה</b>: איוב יא, ט."],["1094","152","<b>ביום ההוא תקראי לי אישי</b>: ע\"פ הושע ב, יח."],["1095","153","<b>אלה המצות אשר יעשה אותם האדם וחי בהם</b>: ע\"פ אחרי יח, ה. וראה בהנסמן ע\"ז ב”מילואים להמ\"מ\" בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"א ר\"ע שח."],["1096","154","<b>והנגלות לנו ולבנינו</b>: נצבים כט, כח."]]],[1900420255,"המעשה בחיצוניו' דעכשיו משום דנעוץ תחלתן בסופן שהוא סוף מעשה דוקא וכמשי\"ת בעזר\"ה וד\"ל).\n[טו] <b>והנה</b> מעתה יש להבין מ\"ש צאנה וראנה כו' בעטרה שעטרה לו אמו ביום חתונתו זו מ\"ת כו', דהנה ידוע שהמלך שלמה מלך שהשלום שלו<sup data-n=\"1097\">155</sup> כו' היינו בחי' ז\"א דאצי' ועטרה שעטרה לו אמו הוא בחי' אימא בינה עילא' ובחי' העטרה הזאת היינו כל בחי' אורו' העליוני' דע\"י ולמעלה מעלה הגנוזי' בעצמות אור א\"ס וז\"ש שעטרה לו אמו דוקא כידוע בענין אהי' אשר אהי' דכל התגלו' העלם הכת\"ר הכללי הוא בבחי' בינה אנא זמין לאתגלאה<sup data-n=\"1098\">156</sup> כו', וזה סותר לכאורה לענין הנ\"ל דבמ\"ת הי' בבחי' מקיף בהעלם הנק' אירוסין. ועוד שא' וביום שמחת לבו שזהו לע\"ל וגם אז בעטרה שעטר\"ה לו אמו, ואין הענין כן לפי כל הנ\"ל שלע\"ל יהי' האור מבחי' העצמו' והפנימי' דאא\"ס שבפנימי' ע\"י ולא בבחי' עטר\"ה ומקיף אלא בגילוי כנ\"ל.\n<b>אך</b> הנה יש להקדים לזה ענין א' הידוע בע\"ח דעכשיו בחי' המל' מקבל מבחי' ז\"א בעלה והוא יחוד זו\"נ שהוא יחוד הוי' ואלקים כידוע. והנה בחי' חתן וכלה שהוא בחי' משפיע ומקבל הרי למעלה בחי' ז\"א נק' חתן חו\"ת דרגא כו' וכנ\"י נק' כלה בחי' מקבל השפע, וזהו יחוד קודב\"ה ושכינתי' כידוע, אך הנה כדי שיהי' בכח החתן להשפיע למקבל ביחוד וזווג ושיהי' בחי' תולדה מייחודם לזאת צריך שיבא הכח והעוז להמשפיע מלמעלה מעלה דוקא. וזהו ענין בעטרה שעטרה לו אמו דהיינו בחי' בינה עילא' שממשכת לז\"א עטרה שהוא מקור למוחי' בשביל כח היחוד להוליד נשמות כו' שאז דוקא יש ביכולת ז\"א להשפיע למל' היא כנ\"י, ועטרה זו היא מקיף ע\"ג הראש דחתן כשהוא בחופה שחופפת ע\"ג שניהם יחד כו'. ואמנם ב' דברים יש כאן הא' האירוסין שהוא ג\"כ בחי' מקיף כשמקדש בכסף קידושי' והב' ענין העטרה שבראשו שעטרה לו אמו שלמעלה הרבה מזה המקיף דאירוסין כו'. והענין הוא דכח המקיף הזה שבעטרה זו היינו להיות במוחין שלו כח התולדה ביחוד שנק' נישואין כנ\"ל זהו למעלה הרבה ממקיף של המקבל שהוא טבעת קידושי' שע\"ג אצבעה באמרו לה הרי את מקודש\"ת לי כו' שאין זה המקיף רק לגבי דידה שתתקדש אליו ותהי' ראוי' ליחוד וזווג כו', אבל מקיף דידי' שיהי' בו כח התולדה הוא בעטר\"ה כו' וד\"ל.\n<b>(ויובן</b> זה בעבודת ה' במ\"ש אשרי איש ירא ה' וארז\"ל כשהוא איש ולא אשה, ולכאורה גם באשה נז' יראה כמ\"ש אשה יראת ה'<sup data-n=\"1099\">157</sup>, אלא הענין הוא",[["1097","155","<b>שהמלך שלמה מלך שהשלום שלו</b>: ראה במדב\"ר פי\"ב, ד. ובכ\"מ."],["1098","156","<b>כידוע בענין אהי' אשר אהי'. . אנא זמין לאתגלא'</b>: שמות ג, יד. ראה לעיל ד\"ה להבין שבברכה ראשונה, אות כב. וש\"נ."],["1099","157","<b>אשרי איש. . כשהוא איש. . אשה יראת ה'</b>: תהלים קיב, א. ע\"ז יט, א [וראה יהל אור ע' תלה]. משלי לא, ל."]]],[1900420256,"כידוע דאית יראה כו' יראה תתאה בנוק' שנק' אשה יראת ה' בחי' ביטול היש לאי\"ן האלקי כמו בהתעוררות תשובה ואוי\"ר טבעיים להתפעל לצאת ממקומו הטבעי לבד כו', אבל יראה עילאה בחי' ביטול בעצם רק מצד בחי' אי\"ן האלקי שבנשמ' הוא בחי' דכ\"ר ונק' אי\"ש ביו\"ד דחכמה כ\"ח מ\"ה העצמי כידוע, וזהו אשרי אי\"ש בחי' דכר כו', ואמנם מי הוא הנותן כח לאיש זה להיות בו ביטול העצמי דכח מ\"ה הנ\"ל זהו בחי' המקיף דצלם והוא צ' ל' שנק' צל ומ\"ם דצלם למעלה מזה וצל זה הוא הבא בגילוי כמ\"ש ה' צילך<sup data-n=\"1100\">158</sup> כו' ונק' מזלי' כידוע, והוא בחי' העטר\"ה הנ\"ל להיות לו כח המוליד במוחין שזהו בבחי' כחב\"ד תוס' כח כו', אבל החופה הוא מקיף דיחידה בחי' מ\"ם דצלם שכולל דכר ונוקבא כאחד כו' וד\"ל, ויש נשמות שהן בבחי' נוק' כאשה יראת ה' הנ\"ל ויש להן בחי' מקיף מיוחד ליתן בה כח ועוז לקבלת אור האלקי, וזהו כמו טבעת קידושין כו', ויש נשמות שהן מבחי' דכורא ומקיף שלהם הוא שיולידו ויעשו פרי למעלה בעבודתם כאיש שיוכל להוליד כו'. ובזה יובן ההפרש בין מקיף דעטרה לגבי החתן וכמ\"ש כחתן יכהן פאר<sup data-n=\"1101\">159</sup> שהוא העטרה ובין מקיף דכלה שזהו ככלה תעדה כליה שהן טבעת הקידושין כו' וד\"ל).\n[טז] <b>והנה</b> כל זה עכשיו דוקא שהמל' מקבלת מז\"א ע\"כ נאמר בעטרה שעטרה לו אמו להיות לו כח היחוד כנ\"ל, אבל לע\"ל כתיב אשת חיל עטרת בעלה ונקבה תסובב גבר<sup data-n=\"1102\">160</sup> שאז לא תקבל המל' מז\"א כי תעלה למעלה הרבה ממנו והיינו בבחי' אור הכת\"ר דכתר מלכות איהו כתר עליון כו' משום דנעוץ תחלתן בסופן וסופן כנ\"ל וסוף מעשה עלה במחשבה תחלה כידוע בענין כוסי רוי\"ה גימטריא אר\"ך<sup data-n=\"1103\">161</sup> והוא בחי' א\"א דאצי' כו' (ומ\"ש והי' אור הלבנה<sup data-n=\"1104\">162</sup> כאור החמה שיהיו זו\"נ שוין בקומתן יהי' עוד עלי' למל' למעלה מזאת והוא שתהי' עטרת לבעלה כו'). והענין הוא כנ\"ל דבחי' פנימי' אור א\"ס שבפנימי' התענוג העצמי שנק' שעשועי המלך בעצמו יאיר בכנ\"י לע\"ל ויקראו חפצ\"י בה כנ\"ל שזהו סוף מעשה שעלה במחשבה תחילה ממש ויהיו בחי' בית קיבול להכיל זה כנ\"ל. וזהו מארז\"ל עתידים צדיקים שיאמרו לפניהם קדוש<sup data-n=\"1105\">163</sup> שזהו מה שהמלאכים אומרים עכשיו קדוש הוי' כו' יאמרו קדוש זה לפני נשמות הצדיקים, וזה פלא גדול לכאורה. אלא הענין הוא שנשמות הצדיקים בעסקם בתו\"מ ובתפלה ותשובה בהיותם בגופים בעוה\"ז עושין בחי' כת\"ר ועטרה לבחי'",[["1100","158","<b>ה' צילך</b>: תהלים קכא, ה."],["1101","159","<b>כחתן יכהן פאר</b>: ישעי' סא, י."],["1102","160","<b>אשת חיל עטרת בעלה ונקבה תסובב גבר</b>: משלי יב, ד. ירמי' לא, כא."],["1103","161","<b>כידוע בענין כוסי רוי' גי' ארך</b>: תהלים כג, ה. ויומא עו, א: כסא דדוד לעוה\"ב רכ\"א לוגין מחזיק שנאמר כוסי רוי' כו'. וראה מזה בתו\"א יט, א. ס' מאמרי אדהאמ\"צ בראשית ע' רעט ואילך. במדבר ח\"ה ע' א'תרלח ואילך. דברים ח\"א ע' כג ואילך. ובהמ\"מ שם."],["1104","162","<b>והי' אור הלבנה</b>: ישעי' ל, כו."],["1105","163","<b>עתידי' צדיקי'. . קדוש</b>: ב\"ב עד, א."]]],[1900420257,"המל' מבירורים דרפ\"ח כו' שעולה המל' עי\"ז בבחי' או\"ח לקדמותו שהוא אשר עלה במחשבה תחלה כו', והוא תענוג הנעלם שבעצמותו ממש הנ\"ל שיתגלה לע\"ל במשיח דכתיב בי' וגבה מאד<sup data-n=\"1106\">164</sup>, וזהו עליית המל' עד פנימי' ע\"י כנ\"ל, ולכך תהי' עטרת לבעלה שהוא בחי' ז\"א. והענין הוא דעטרה שעטרה לו אמו ביום חתונתו במ\"ת הי' מאורות עליונים מלמעלה למטה בבחי' או\"י כו', אבל אין לה ערך לגבי עטרה שתהי' לו מבחי' המל' כשתהי' לע\"ל עטר\"ת בעלה להיות שזה יבא מבחי' הברורים דאו\"ח (וכמו הפרש בין ב' מיני אבן שהם וישפה שהבהקת אבן הנק' ישפה מצד הנקיון (בל\"א גְישט ערלְי עט) והזיכוך שנק' טהרה יוכל להיות אור צח מצוחצח הרבה יותר מהבהקת אבן הנק' שהם שהוא בהיר מצד העצם, וזהו שצדיק תחתון למעלה מצדיק עליון אשת חיל עטרת בעלה וד\"ל), והוא ע\"י התשובה ומע\"ט בעוה\"ז דוקא, ולכך עתידים צדיקים שיאמרו לפניהם קדוש דהמלאכים שרשם מבחי' המל' כמו שהיא בבי\"ע וכבו\"ד הוי' בחי' ז\"א קדוש ומובדל מהם וצדיקים הגם שנשמותיהם בשם הוי' דז\"א אך אז יהי' אחר הבירור דתשובה ומע\"ט שיעלו קדושתם עי\"ז לבחי' סובב הכללי שלמעלה משם הוי' ששם עלי' המל' שנק' עטרת בעלה וכמאמר צדיקים יושבים<sup data-n=\"1107\">165</sup> ועטרותיה\"ם בראשיהם ע\"כ יאמרו המלאכים לפניהם קדוש כו' לפי ששרש הצדיקים יהי' מבחי' המל' לאחר שתעלה ויעלו עמה גם הם, ודוגמא לדבר גם עתה הרי מט\"ט יושב וקושר כתרים<sup data-n=\"1108\">166</sup> לקונו מתפלותיהן של ישראל שזהו מתפלות הצדיקים שבגופים עושה כת\"ר ועטרה במל' שנק' קונ\"ו דמט\"ט דיצירה או דבריאה, ועטרות אלה הרבה למעלה מעטרה שעטרה לו אמו כו' מטעם הנ\"ל וד\"ל.\n<b>אך</b> הנה לפ\"ז עדיין אין מתיישב ענין הפסוק זה דצאנה וראנה כו' במ\"ש וביום שמחת לבו דודאי קאי זה לע\"ל ואז לא יהי' בעטרה דאמו אלא ע\"י אשת חיל שתהי' עטר\"ת בעלה ומטעם הנ\"ל, וגם אינו מתורץ עדיין הקושיא דלעיל מה שסותר לענין הנ\"ל דבמ\"ת הי' בבחי' מקיף דאירוסין שהוא בהעלם ולא בגילוי ועטרה זו בחי' גילוי הוא דוקא שהוא בבחי' מקיף כו'. והנה יש להקדים לזה ענין אחד והוא מ\"ש וארשתיך לי בכסף ואח\"כ וארשתיך באמונה<sup data-n=\"1109\">167</sup> כו', הנה האירוסין באמונה אחר הכסף זהו כמ\"ש זכרתי לך חסד נעוריך<sup data-n=\"1110\">168</sup> לכתך אחרי כו' שהי' עיקר הלוכם אחרי ה' ממצרים רק באמונה והוא הי' בבחי' מקיף",[["1106","164","<b>וגבה מאד</b>: ישעי' נב, יג."],["1107","165","<b>צדיקי' יושבי'</b>: ברכות יז, א."],["1108","166","<b>מט\"ט יושב וקושר כתרים</b>: ראה לעיל אות ח. וש\"נ."],["1109","167","<b>וארשתיך לי בכסף. . באמונה</b>: ראה בהושע ב, כא-כב: וארשתיך לי לעולם וארשתיך לי בצדק ובמשפט ובחסד וברחמים וארשתיך לי באמונה. ובס' מאמרי אדהאמ\"צ במדבר ח\"ב ס\"ע תתסב: בכסף שנק' חסד כמ\"ש וארשתיך כו'. וכהלשון כאן מובא גם במאמרי אדהאמ\"צ נ\"ך ע' תקל."],["1110","168","<b>זכרתי לך חסד נעוריך</b>: ירמי' ב, ב."]]],[1900420258,"ועטרה בלתי גילוי אמנם מכח זה הי' כל אשר קיבלו במ\"ת וזהו וארשתי\"ך כו', וזהו העטרה דאמונה בכנ\"י תהי' בחי' עטרת לבעלה לע\"ל כנ\"ל שאמונה זו יהי' לה עליי' גדולה כ\"כ עד שתעלה למעלה להיות לעטרת לשם הוי', ועתה הוא בהיפך דאיהו אמת ואיהי אמונה<sup data-n=\"1111\">169</sup> דודאי אמת דהוי' למעלה מן אמונה דמל' ואדרבה מקיף האירוסין באמונה שבהעלם כו', וענין איהו אמת היינו בחי' גילוי אמיתת אור א\"ס שבקו האמצעי דז\"א וכמ\"ש דוד אמת\"ך אלקי כו' וכן ואמת ה' לעולם<sup data-n=\"1112\">170</sup> כו', וזהו עוטר ישראל בחי' ז\"א בתפאר\"ה כמ\"ש כחתן יכהן פאר<sup data-n=\"1113\">171</sup> שהוא ת\"ת דאימא שנעשה עטרה לו כו'. ואמנם ביום חתונתו במ\"ת נמשך מעטרה זו כח לכל יחוד כנ\"ל, וגם מה שיהי' עטרת תפארת למעלה מזו והוא מבחי' האמונה גם זו יהי' מעטרה שעטרה לו אמו ביום חתונתו דכאמה בתה<sup data-n=\"1114\">172</sup> (והוא בחי' שם ב\"ן דמל' שעולה בבחי' ס\"ג דבינה כידוע וד\"ל). ולפ\"ז ביום שמחת לבו דלע\"ל גם יהי' מעטרה זו דאמו רק שיהי' בעליי' ע\"י בחי' המל' שנק' עט\"ב מטעם הנ\"ל וד\"ל.\n[יז] <b>ובכל</b> זה יובן ענין שינוי נוסח החתימה דחותם בברכת אשר ברא משמח חתן עם הכלה ובשמח תשמח חותם משמח חתן וכלה. דהנה כאשר או' משמח חתן וכלה השמחה באה תחלה לחתן וממנו תבא השמחה לכלה שהחתן הוא המשמח לכלה וכמו שאמרו אשה בעלה משמחה<sup data-n=\"1115\">173</sup> כו', וזהו עתה בזמן הגלות, אבל מ\"ש משמח חתן עם הכלה הכונה שעיקר השמחה באה אל הכלה שהיא עיקר והחתן מקבל שמחה מן הכלה שממנה עיקר ומקור השמחה לשמח את החתן, והיינו לע\"ל דוקא דאשת חיל עטרת בעלה כנ\"ל. וביאור הדברים מובן עפ\"י הנ\"ל דעתה בזמן הגלות בחי' המל' שרש כנ\"י שנק' כלה למעלה מקבלת מבחי' ז\"א שנק' חתן וע\"כ שמחה דחופ\"ה בחתן תחלה וכמ\"ש קול מצהלות חתנים מחופתן כו' והוא משמח לכלה דאשה בעלה משמחה והוא ע\"י העטרה שעטרה לו בחופתו שקיבל בחי' מוחין חדשים לשמח גם הכלה עמו כו' וד\"ל, אבל לע\"ל דגם העטרה שלו יהי' מן הכלה דאשת חיל עט\"ב לפי שתתעלה המל' למעלה מעלה והוא בפנימי' הכת\"ר דאצי' כנ\"ל אז נהפוך הוא שעיקר השמחה מן הכלה שהיא כנ\"י בחי' המל' סופא דכל דרגין שנעוץ סופן בתחלת הכל ע\"כ יקבל החתן שהוא ז\"א שמחה עליונה מן הכלה דוקא וממנה יושפע לו אור השמחה, וז\"ש משמח חתן עם הכלה פי' מן הכלה כו' וד'\"ל.\n<b>(ויובן</b> זה בעבודת ה' בשמחה דכנ\"י שלמעלה מן הטעם ודעת רק מצד בחי' התקשרות בחי' עצמיות דיחידה בעצמות דא\"ס ממש ולא מצד מדותיו",[["1111","169","<b>דאיהו אמת ואיהי אמונה</b>: ראה זח\"ג קצח, ב."],["1112","170","<b>אמתך אלקי. . ואמת ה' לעולם</b>: תהלים עא, כב. קיז, ב."],["1113","171","<b>כחתן יכהן פאר</b>: ישעי' סא, י."],["1114","172","<b>דכאמה בתה</b>: יחזקאל טז, מד."],["1115","173","<b>אשה בעלה משמחה</b>: ר\"ה ו, ב."]]],[1900420259,"כלל, וכמו וישמחו ב\"ך<sup data-n=\"1116\">174</sup> ממש וכמו שם נשמחה ב\"ו שלמעלה הרבה משמחה בהוי' שהוא ז\"א ע\"י שמחה במדות שבלב מההתבוננות שישמחו בהוי' שהן מדות דאצי' ששרשם בבינה שנק' אם הבנים שמחה, וגם שהעונג שברצון הוא מלובש בשמחה שבהתבוננות הרי עונג מורכב הוא, אבל השמחה שבעצמות הנפש שלמעלה מכל עונג ורצון בפרט מגיע למעלה בשמחה ועונג שבעצמות ממש שלא מצד שום טעם ודעת (וגם לא מצד יחוד כמו עתה שאל אישך תשוקתך ותשמח בבעלה כו' וזהו אז תשמח בתולה<sup data-n=\"1117\">177</sup> במחול כו' וד\"ל). ושמחה כזאת הנה היא בשמחה של מצוה שזהו מצד שאמר ונעשה נח\"ר לפניו<sup data-n=\"1118\">178</sup> ולא מצד עצם הרצון ולזה נק' כנ\"י אז ארץ חפ\"ץ כו', וזהו שמחה שמן הכלה אל החתן לעורר שמחה העצמית למעלה וכמ\"ש שם נשמחה בו<sup data-n=\"1119\">175</sup> ומשם יומשך שפע השמחה<sup data-n=\"1120\">176</sup> להוי' שהוא בחי' ז\"א וכמ\"ש הנני בורא חדשה בארץ נקבה תסובב גבר משום דנעוץ סופן<sup data-n=\"1121\">179</sup> כו' כנ\"ל).\n[יח] <b>וזהו</b> מהרה ישמע ל' עתיד כו', דהנה יש להפלא מאד על אשר אנו רואים בענין הקידושין שאו' לה הרי את מקודש\"ת לי והרי היא שותקת ואינה משיבה כלום לאמר לו הן ורוצה אני עכ\"ז מתקדשת בזה ואיך תתקדש בשתיקה אולי אין רצונה בקידושין והרי כל קניי' בכסף הקונה נותן הכסף ושואל אם מרוצה בכסף זה למכור והלה משיב הן ומושך הקונה ונקנה בכסף או במשיכה, אבל האשה שנקנית בכסף הרי בשתיקה מתקדשת ונאמר בה קיחה כי יקח<sup data-n=\"1122\">180</sup> כו', והנה גם מה שאומר הרי את מקודשת זהו כאילו פוסק הדבר שבמאמר זה מיד מקודשת ולא תוכל לומר לאו כו'. אך הנה כל זה יובן דעתה בזמן הגלות אין למל' רק מה שמקבלת מז\"א ובבואה לפניו לית לה מגרמה כלום גם קול ודיבור אין לה, וכמו בתפלת ש\"ע שנק' צלותא בלחש אד' שפת\"י תפתח תפתח אתה כי אין מלה בלשוני כו' וכמו נאלמתי דומי'<sup data-n=\"1123\">181</sup> כו' מצד בחי' הביטול ושפלות דמקבל אין לה בחי' התפשטות בדיבור כלל וכלל (ותחלה נעשי' רק כמו נקודה אחת כו' וחוזרת להבנות בפרצוף ואמנם בבחי' ביטול",[["1116","174","<b>וישמחו בך</b>: נוסח תפילת יו\"ט: וישמחו בך כל ישראל מקדשי שמך. ובתהלים מ, יז: ישישו וישמחו בך כל מבקשיך גו'."],["1117","177","<b>אל אישך תשוקתך. . אז תשמח בתולה</b>: בראשית ג, טז. ירמי' לא, יג."],["1118","178","<b>שאמר ונעשה נח\"ר לפניו</b>: ספרי פינחס כח, ח."],["1119","175","<b>שם נשמחה בו</b>: תהלים סו, ו."],["1120","176","<b>בבינה שנק' אם הבנים שמחה</b>: תהלים קיג, ט. זח\"א ריט, א. וראה הערת כ\"ק אדמו\"ר שליט\"א בסה\"מ תש\"ט ע' 112."],["1121","179","<b>הנני בורא חדשה. . דנעוץ סופן</b>: ע\"פ ירמי' לא, כא [ראה גם לעיל ח\"א ע' שי. ובכ\"מ]. ס' יצירה פ\"א מ\"ז."],["1122","180","<b>כי יקח</b>: תצא כד, א. ראה קידושין ב, א."],["1123","181","<b>כי אין מלה. . נאלמתי דומי'</b>: תהלים קלט, ד. לט, ג."]]],[1900420260,"עצום), וז\"ש בחנה וקולה לא ישמע<sup data-n=\"1124\">182</sup> כו' שאין לה קול כלל מעוצם הביטול לגבי בחי' המשפיע, וע\"כ מיד שאומר החתן הרי את מקודשת לי שותקת בבחי' ביטול לבטל רצונה אליו בלי שיהי' נצרך להשיב לו הן כי אין לה קול ודיבור ובשתיקה זו מתקדשת לו וקולה לא ישמע כלל. אבל לע\"ל דאשת חיל עטרת בעלה<sup data-n=\"1125\">183</sup> יהי' לכלה עליונה בחי' קול ודיבור בהתפשטות בפ\"ע מאחר שיהי' עליי' שלה לבחי' פנימי' הכתר כנ\"ל עד שתהי' משפיע לבעלה כנ\"ל, וזהו קול כלה שיהי' לכלה קול, ודוקא לע\"ל ישמע בערי כו' קול כלה ולא עתה שבשתיקה מתקדשת בצלותא דלחש וד\"ל.\n<b>אך</b> א\"כ מה זה שאומרים קול חתן ג\"כ מאחר שהכלה עיקר לעתיד, הענין הוא משום דעיקר ההפרש הוא בין עתה לע\"ל הוא ההפרש שבין אירוסין לנישואין הנ\"ל, שבמ\"ת הי' רק בחי' אירוסין בטבעת קידושין שהוא בבחי' מקיף על הכלה כו' ע\"כ בשתיקה דוקא מתקדשת ואין לה קול כביטול דצלותא בלחש, אבל לע\"ל יהי' בחי' נישואין דהיינו שכנ\"י תקבל פנימי' ועצמות אור הא\"ס ממש ונעשית בחי' כלי בפ\"ע לקבל הכל בבחי' בלי גבול ע\"כ אז יהי' לה בחי' קול בהתפשטות גדולה ויתרה בלי גבול כו' (וזהו הנק' קול גדול ולא יסף כמשי\"ת). וזהו שא' ישמע קול חתן וקול כלה שקול כלה יהי' בחי' כלי לקבל כל אור ושפע העצמות (ועכ\"ז משמח חתן עם הכלה דכלה עיקר גם לגבי שפע העצמו' כנ\"ל בענין שמחה דכנ\"י בבחי' עצמיות כשמחה של מצוה כו' וכמ\"ש וישמחו ב\"ך כו') וד\"ל.\n[יט] <b>ולהבין</b> זה בתוס' ביאור, כי הנה עדיין אין מתיישב ענין קול חתן וקול כלה, דלכאורה לפי פי' הנ\"ל יש סתירה מיני' ובי', דקול חתן וקול כלה משמע כמו עכשיו שחתן משפיע לכלה לכך הזכיר קול חתן קודם לקול כלה ובחתימה מסיים משמח חתן עם הכלה דמשמע שהכלה עיקר והוא כמו שיהי' לע\"ל והרי א' מהרה ישמע לשון עתיד וא\"כ הי' לו להקדים קול כלה לקול חתן כו'. אך הנה יש להקדים לזה ענין הידוע בע\"ח דגם לע\"ל יש ב' מדרגות בבחי' עליית המל'<sup data-n=\"1126\">184</sup>, הא' שתהי' שוה בקומתה לבחי' ז\"א ולא תצטרך לקבל ממנו כלל כעכשיו אלא מקור אחד להם, והוא בחי' ת\"ת דאימא שנעשה כתר א' לזו\"נ<sup data-n=\"1127\">185</sup> כמו שהן שוין בקומתן כו', וזהו שא' לעתיד והי' אור הלבנה כאור החמ\"ה ממש בשוה, וזהו ה' אחד ושמו אחד יח\"ע דהוי' דז\"א ויח\"ת דמל'",[["1124","182","<b>וקולה לא ישמע</b>: שמואל-א א, יג."],["1125","183","<b>דאשת חיל עטרת בעלה</b>: משלי יב, ד."],["1126","184","<b>הידוע בע\"ח דגם לע\"ל יש ב'. . עליי' המל'</b>: ראה שער מיעוט הירח פ\"א."],["1127","185","<b>ת\"ת דאימא שנעשה כתר א' לזו\"נ</b>: ראה ע\"ח שם שער מוחין דצלם רפ\"ה ורפ\"ז. שער דרושי הצלם דרוש ד' וה'."]]],[1900420261,"שנק' שמו יהיו שוין למהוי אחד באחד<sup data-n=\"1128\">186</sup> כו' וד\"ל, והיינו שיהי' אור הלבנה כמו שהיתה קודם שמיעטה א\"ע דכתיב ויעש ה' את שני המאורות הגדולים את המאור הגדול לממשלת היום ואת המאור הקטן כו', וידוע הקושיא מרישא לסיפא דקאמר שני המאורות הגדולים דגם מאור הלבנה נק' מאור הגדול ומסיים ואת המאור הקטן, אך מפני שקטרגה הלבנה<sup data-n=\"1129\">187</sup> וטענה וכי אפשר לב' מלכים להשתמש בכתר אחד א\"ל לכי ומעטי א\"ע כו', ולע\"ל יהי' אור הלבנה כמו שהיתה קודם המיעוט שנק' שני המאורות הגדולים וד\"ל (ואין זה מובן דא\"כ איך לעתיד ישתמשו בכתר אחד והדרא קושיא לדוכתה, וצריך לומר דלע\"ל לא יהי' הפרש כלל בין מדת יום למדת לילה וכמ\"ש לעת ערב יהי' אור כו' ולילה כיום יאיר<sup data-n=\"1130\">188</sup> ואז אפשר להשתמש בכתר אחד, משא\"כ כאשר הי' במע\"ב הפרש בין יום ללילה גם בטרם שעשה המאורות דשמש וירח והוא ע\"י שהבדיל בין אור והחושך ויקרא לאור יום<sup data-n=\"1131\">189</sup> ולחושך קרא לילה והמאורות עשה להבדיל יותר ונק' הלבנה מאור לממשלת הלילה ע\"כ מיעטה א\"ע לקבל מהשמש וד\"ל, וביאור זה יובן במ\"א ע\"פ ושמתי כדכ\"ד<sup data-n=\"1132\">190</sup> שמשותיך כו' שהם וישפה ב' מדרגות דא\"י וא\"ח שלע\"ל יהיו שוין ממש כו').\n<b>והנה</b> לנגד עלי' זו אמר כאן קול חת\"ן וקול כלה ר\"ל שניהם שוין במעלה ואין הכונה קול חתן משפיע לקול כלה, אלא קול חתן בפ\"ע וקול כלה בפ\"ע כענין שני מאורות הגדולים דאור הלבנה ואור החמה וכמ\"ש ה' אחד ושמו אחד כנ\"ל שיהי' זו\"נ שוין ומשתמשין בכתר אחד כנ\"ל ולא כמו עכשיו שאין לכלה קול כלל וכענין צלותא דלחש כנ\"ל וד\"ל. אבל הנה עלי' המל' השנית לע\"ל הוא עלי' הנ\"ל דא\"ח עט\"ב וכן נקבה תסובב גבר כו' שתהי' עולה עד פנימי' ע\"י וא\"א (כמו בנעילה דיו\"כ) ולמעלה מעלה יותר, והיינו כמ\"ש ביום ההוא יצאו מים חיים<sup data-n=\"1133\">191</sup> מירושלים חציים אל הים הקדמונ\"י שזהו שתתן שפע מלמטה למעלה מעלה לים הקדמוני שהוא עולם התוהו קודם שהי' התיקון וחציים אל הים האחרון שהוא עולם התיקון כו' ואז תהי' בחי' משפיע לבחי' ז\"א בעלה (והוא שם ב\"ן שיעלה בבחי' או\"ח לקדמותו ממש שהוא מל' דא\"ס ממש) כי בחי' התיקון דאד\"ם שהוא ז\"א יהי' כמו טפל לעיקר, ולזה אמר משמח חתן עם הכלה דהכלה עיקר כנ\"ל וד\"ל (ולא הוי החתימה שלא מעין הפתיחה, ומה גם דקול מצהלות חתנים סמוך לחתימה קאי ג\"כ אדסמיך לי' דקול חתן קודם כו' משום שכל זה כסדר העליות הוא תחלה שוין בקומתן ואח\"כ משמח חתן עם הכלה והמשמ\"ח חתן וכלה שבברכת שמח תשמח שהוא",[["1128","186","<b>והי' אור הלבנה. . ה' אחד ושמו אחד. . למהוי אחד באחד</b>: ישעי' ל, כו. זכרי' יד, ט. זח\"ב קלה, א."],["1129","187","<b>ויעש ה' את שני המאורו'. . שקטרגה הלבנה</b>: בראשית א, טז. חולין ס, ב."],["1130","188","<b>לעת ערב יהי' אור. . ולילה כיום יאיר</b>: זכרי' יד, ז. תהלים קלט, יב."],["1131","189","<b>ויקרא לאור יום</b>: בראשית א, ה."],["1132","190","<b>במ\"א ע\"פ ושמתי כדכד</b>: ס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תכ ואילך."],["1133","191","<b>ביום ההוא יצאו מים חיים</b>: זכרי' יד, ח."]]],[1900420262,"כשהמל' מקבל מז\"א והמשמח חתן עם הכלה בעליי' הב' דמל' הכל מעצמות אור א\"ס ב\"ה וד\"ל).\n[כ] <b>והנה</b> מ\"ש והי' אור הלבנה כו' הרי אמר ואור החמה יהי' שבעתיים כאור ז' הימים שהן בחי' ז\"ת דע\"י, ומאחר שיהי' הלבנה כמו אור החמה ממילא יהי' עליי' המל' באשר הוא שם אור החמה בלי הבדל כלל, וא\"כ מהו עליי' הב' דמל' למעלה מז\"א שנק' אור החמה. אלא הענין הוא דמ\"ש והי' אור הלבנה כו' היינו כמ\"ש לא יבא עוד שמשך<sup data-n=\"1134\">192</sup> וירחך לא יאסף כו', שזהו עליי' אור החמה כאור ז' הימים שבעתיים פעמים כמוהו, דביאת השמש עתה עושה הבדל בין היום והלילה ואור ז' הימים כולו יום ואור ולא חושך כלל, וזהו לא יבא עוד שמשך שיהי' בחי' אור א\"ס בשם הוי' דז\"א שנק' שמשא וכן במל' שנק' ירח, וכמו שהיו שניהם מוגבלים בממשלתם ביום ולילה שהן חו\"ג כי חסד אל כל היו\"ם<sup data-n=\"1135\">193</sup> כו' כך יהיו שניהם בלתי מוגבלים לע\"ל, אבל עכ\"פ יש מדת יום אלא שנק' יום שכולו ארוך שכולו טוב<sup data-n=\"1136\">194</sup> כו' ואור הלבנה יהי' כאור החמה ג\"כ לא יאסף, אבל מ\"ש לא יהי' לך השמש<sup data-n=\"1137\">195</sup> לאור יומם כו' ה' יהי' לך לאור עולם היינו למעלה מזו\"נ שנק' שמש וירח גם בעליית' בע\"י אלא עצמות אא\"ס ממש יהי' לך לאור עולם בבחי' נצחי' דא\"ס ולא כאור ז' הימים וגם לא כשמש שלא יבא שיפול בגדר זמן כו' דמ\"מ אינו אור עולם ממש וד\"ל.\n<b>וזהו</b> מ\"ש לע\"ל דוקא קול גדול ולא יסף<sup data-n=\"1138\">196</sup>. דהנה עתה המל' מקבלת מז\"א שנק' שמש וגם כשהיא מאור בפ\"ע ובלי גבול כמ\"ש ירחך לא יאסף אין לכל זה ערך לעלי' המל' לקבל מעצמות אא\"ס ממש וכמ\"ש ה' לא יהי' לך לאור שהמל' נק' בית קיבול להכיל בה אור עולם זה כו' וע\"כ תקרא אז ארץ חפץ כנ\"ל, וזהו שנק' קול גדול ולא יסף להיותה מקבלת מעצמות אור עולם בחי' א\"ס ממש ע\"כ קולה גדול בבחי' א\"ס, וכמו שאומרים בשכמל\"ו ביו\"כ בקול רם דוקא לפי שיו\"כ נק' שבת שבתון מעין עליי' המל' דלע\"ל, וזהו היפוך גמור מצלותא דלחש שקולה לא ישמע כלל וכל המשמיע קולו כו', ולע\"ל יהי' להיפך דוקא בקול רם שהוא בחי' קול מורגש בבחי' יש ודבר גדול דוקא היפך הביטול כו' (ושרש הדברים הוא דמ\"ש ה' יהי' לך לאור עולם הוא יהי' יום הגדול שכלול מיום ולילה כאחד בלי התחלקות דשמש וירח כלל וכמ\"ש ביום הג' יקימנו<sup data-n=\"1139\">197</sup> ונחי\"ה לפני\"ו ממש, ולכך יהי' בבחי' מורגש ליש דוקא, כי עכשיו",[["1134","192","<b>לא יבא עוד שמשך</b>: ישעי' ס, כ. ראה גם ס' מאמרי אדהאמ\"צ שם ע' תעה."],["1135","193","<b>כי חסד אל כל היום</b>: ע\"פ תהלים נב, ג. [ראה גם ס' מאמרי אדהאמ\"צ במדבר ח\"ד ע' א'תקלט]."],["1136","194","<b>יום שכולו ארוך שכולו טוב</b>: קידושין לט, ב. נוסח ”הרחמן\" בברכת המזון ליו\"ט."],["1137","195","<b>לא יהי' לך השמש</b>: ישעי' שם יט."],["1138","196","<b>קול גדול ולא יסף</b>: ואתחנן ה, יט. וראה לעיל סוף אות יח בענין קול כלה דלעת\"ל בחי' נישואין ”וזהו הנק' קול גדול ולא יסף\"."],["1139","197","<b>ביום הג' יקימנו</b>: הושע ו, ב."]]],[1900420263,"שהמל' בחי' מקבל מעונג דאי\"ן דכח\"ב כו' א\"א לה לקבל כ\"א ע\"י ביטול במציאות שהוא השתיקה כמו מלאכים בעמדם תרפינה<sup data-n=\"1140\">198</sup> כו' שזהו עמידה דש\"ע וזהו הנק' ביטול לאי\"ן ולא האי\"ן אלקי עצמו, אך כאשר תעלה המל' לקבל מעצמות העונג כמו שהוא בלתי תבא לבחי' ביטול עצמותה כלל אדרבה תהי' בבחי' יש מורגש כמו שהתענוג בעצם, וכמו להנחיל אוהבי יש<sup data-n=\"1141\">199</sup> י\"ש האמיתי כו' וכשכינה מדברת מתוך גרונו<sup data-n=\"1142\">200</sup> דמשה ולא הי' בו ביטול כלל, וכן במשיח שיהי' בו אור א\"ס בבחי' מורגש דוקא, וכך אנו רואי' ביחידי הדור צדיקים גדולים שמתענגים על ה' בעבודה שבלב במורגש בלי ביטול כלל וד\"ל. וזהו קול גדול ולא יסף דקול גדול בא במורגש דוקא היפך הביטול דתפלה שבלחש כנ\"ל וד\"ל.\n[כא] <b>והנה</b> להבין בתוס' ביאור<sup data-n=\"1143\">201</sup> ענין קול כלה דלעתיד שנק' קול גדול כו', הנה יש להקדים ענין אחד והוא אשר לע\"ל יהיו נשמות גבוהות מאד ונק' נשמות חדשות<sup data-n=\"1144\">202</sup> לגמרי ששרשם מעצמות אא\"ס שלפני הצמצום דקו\"ח כו' עד אשר הנשמות דעכשיו שהן מבחי' פני אדם שבמרכבה יחשבו בבחי' מזון גשמי להנשמות עליונות הנ\"ל, והוא הנק' סעודת לויתן ושור הבר<sup data-n=\"1145\">203</sup> כו', וכאשר יאכלום אותן נשמות העליונות הנ\"ל יעלו אותן ניצוצות דעכשיו כמו שאדם מעלה עכשיו למזון הגשמי וכמ\"ש ענין זה באריכות ע\"פ ואכלתם אכול<sup data-n=\"1146\">204</sup> ושבוע והללתם את שם ה' כו'. ותחלה יש להבין ענין כונת האכילה עכשיו ומזה יובן אכילה דלויתן לע\"ל. דהנה ידוע שיש נשמות ומלאכים בכל עולם מג' עולמות בי\"ע ומלאכים דבריאה נק' שרפים ומלאכים דיצירה נק' חיות ואופנים בעשי' ומרכבה דפני ארי' ופני שור הוא ביצירה ויורד אור ושפע מעולם הבריאה ממדרגה למדרגה עד שמרי האופנים דעשי' שמקבלים המזלות והמזלות הן שרש האחרון הבא בהגשמה לגידול דצח\"ם עד שאין לך עשב<sup data-n=\"1147\">205</sup> שאין לו מזל כו', ולזאת הרי שרש בהמות וחיות דלמטה הוא מפני שור ופני ארי' דיצירה שיורד מעילה לעילה עד התהוות הנפשות בהמות וחיות גשמיות,",[["1140","198","<b>בעמדם תרפינה</b>: יחזקאל א, כד-כה."],["1141","199","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1142","200","<b>וכשכינה מדברת מתוך גרונו</b>: ראה זח\"ג רלב, א. שמו\"ר פ\"ג, טו. מכילתא שמות יח, יט. וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשמט [ובמ\"מ שם]. לעיל ח\"א ע' קנה. ובכ\"מ."],["1143","201","<b>[כא] והנה יש להבין בתוס' ביאור</b>: מכאן (עד אות כה) מיוסד על ד\"ה ואכלתם אכול בסה\"מ תקס\"ז ע' רנא ואילך. ומקבילו בלקו\"ת צו ז, א."],["1144","202","<b>לע\"ל. . נשמות חדשות</b>: בלקו\"ת צו (ז, ג) מציין: ועיין מענין הנשמות החדשות שיתגלו לעתיד בספר הגלגולים פ\"ז, וקרוב לסופו בד\"ה ענין נשמות חדשות, ובמשנת חסידים מס' השגת הנשמות, ובהרמ\"ז ר\"פ תולדות. ע\"כ. וע\"ש דף ח, ד."],["1145","203","<b>סעודת לויתן ושור הבר</b>: ב\"ב עה, א. ויק\"ר פי\"ג, ג."],["1146","204","<b>באריכו' ע\"פ ואכלתם אכול</b>: יואל ב, כו. סה\"מ תקס\"ז, נסמן לעיל בסמוך."],["1147","205","<b>שאין לך עשב</b>: ב\"ר פ\"י, ו."]]],[1900420264,"ועד\"ז גם פני שור שבמרכבה דיצירה מקבלים ממלאכים דבריאה שהוא שרש הראשון ברוחניות כו'. והנה יש בחי' פני אדם במרכבה שמנהיג כולם והוא שרש הראשון לנפש האדם למטה, וכמו שאנו רואים הפרש בין אדם לבהמה למטה שמאכל אדם הוא בשר החי כו' ומאכל בהמה הוא עשב כו', כך הוא למעלה במרכבה דארי' ושור שנאמר מצמיח חציר לבהמה<sup data-n=\"1148\">206</sup> כו', והוא שפע אור המשכה אלקי' הבאה לשור העליון להיות לו למזון גשמי והוא אשר משיג בהשגות אלקות המחי' אותו, ולהיותו בא בהגשמה ה\"ז לו למזון כמו חציר ועשב לשור הגשמי שלמטה, וכן הכפירים עליונים שואגים לטרף<sup data-n=\"1149\">207</sup> כו' היינו ג\"כ טרף ומזון רוחני ברוחניות אור ושפע האלקי כו', ומשם יורד האור ומשתנה ומתגשם מעילה לעילה עד נעשה שפע גשמי' במזלות דעשי' להשפעת דצ\"ח כו' כי ירד האור כ\"כ בריבוי ממוצעים עד שבא בהגשמה כ\"כ כצומח וחי גשמיים. ואמנם בחי' מאכל אדם למעלה היינו כמו מאכל אדם למטה שהוא בחי' התכללות פני שור העליון להיות למזון גשמי לבחי' אדם שעל הכסא, וכמו הקרבן שור ע\"ג המזבח עולה למעלה לשרשו בחי' פני שור וגם שור העליון עולה כקרבן במזבח העליון ונכלל בבחי' אדם כמאכל גשמי ונק' לחמ\"י ריח ניחוחי<sup data-n=\"1150\">208</sup> כו', וע\"כ האדם התחתון שהוא בצלם אד\"ם העליון כשאוכל הבשר דשור מעלהו לשרשו פני שור ששם נכלל בפני אדם. וזהו כללות כונת האכילה דאדם לצומח וחי כו' להיות שזה ביכולת האדם דוקא להעלות לשרשי דצו\"ח למעלה שיוכללו בבחי' אד\"ם מצד שרשו בפני אד\"ם העליון וד\"ל.\n<b>והנה</b> כמו שעכשיו בשר השור ששרשו בחי' פני שור נק' בהמה לגבי אדם למטה כמו שהוא למעלה כנ\"ל, כך כאשר יהי' עליות כל העולמות הרי מה שהוא בחי' פני אדם בעולם התחתון כשיגיע למעלה הימנו אינו נחשב רק בחי' בהמה לגבי בחי' פני אדם שבעולם העליון, כך יהי' בחי' פני אדם דעכשיו בנשמות ששרשם מפני אדם דבריאה או יצירה רק בחי' בהמה ושור לגבי ערך מעלת הנשמות העליונות שיהיו לע\"ל בימות המשיח שבחי' פני אדם שבהם יהי' מעולם היותר עליון כ\"כ עד שנשמות דפני אדם דבריאה דעכשיו יהיו בבחי' מזון גשמי להם כמו מאכל בשר השור לאדם למטה, וזהו סעודת לויתן ושור הבר דלע\"ל כמשי\"ת.\n[כב] <b>אך</b> להבין זה בתוס' ביאור איך יהיו נשמות שמשיגים אלקות בבחי' מזון גשמי לנשמות דלע\"ל, הנה אנו מוצאים גם בכנ\"י עכשיו שיש בהן בחי' אדם ובחי' בהמה וכמ\"ש וזרעתי את ב\"י<sup data-n=\"1151\">209</sup> זרע אדם וזרע בהמה, וא\"א לומר",[["1148","206","<b>מצמיח חציר לבהמה</b>: תהלים קד, יד."],["1149","207","<b>הכפירי'. . שואגי' לטרף</b>: תהלים שם, כא."],["1150","208","<b>לחמי ריח ניחוחי</b>: פינחס כח, ב."],["1151","209","<b>וזרעתי את ב\"י</b>: ירמי' לא, כו."]]],[1900420265,"זרע בהמה ממש שהוא נפש הבהמיות בהמה ממש כרוח התאוה גשמי' שבאדם שהוא כבהמה ממש מצד המשכת תאוה גופנית דאב ואם כו' דא\"כ איך אמר וזרעתי ב\"י כו', אלא הכונה הכל בבחי' אור זרוע לצדיק עליון דאצי' נשמות אלקיי', רק שיש בהן ב' מדרגות זרע אדם וזרע בהמה והוא בחי' מ\"ה וב\"ן וכמ\"ש אדם ובהמה תושיע כו' וכמ\"ש דוד ואני בהמות<sup data-n=\"1152\">210</sup> הייתי עמך, והוא אשר מצינו בעבודה שבלב ב' מיני התפעלות אלקות, א' בנשמה שבמוח בשכל ודעת האלקי דוקא כל א' כפי מדרגת נשמתו במוחי' דבחי' אד\"ם, ונק' זרע אדם כו', ויש הרבה נשמות שהם בעבודתם כבהמה בבחי' הקטנות המוחין לגמרי רק כשור לעול בלבד, וכמו שיש הרבה פשוטים שאין להם דיעה והשגה אלקי' כלל וגם לא התפעלות אוי\"ר שכליים רק טבעיים כמדות שבבהמה ממש אבל הוא דוקא לה' אחד אך שהוא בבחי' טבעי' וכמ\"ש ואני בהמות כו', ולגבי גדלות המוחין דזרע אדם כמו נשמות ת\"ח נק' בחי' בהמה ממש כו', וזהו כדמיון בחי' פני שור במרכבה שבטל ונכלל בפני אד\"ם שבמרכבה (וכמו הפרות שנשאו הארון דכתיב ותשרנה הפרות<sup data-n=\"1153\">211</sup> כו').\n<b>ואמנם</b> הנה יובן שלפי ערך זה יוכל להיות חלוקי מדרגות הרבה זו למעלה מזו עד שגם בחי' הנשמות שנק' זרע אדם לא יחשבו רק בחי' זרע בהמה לגבי הנשמות שבעולם העליון יותר, ודוגמא לדבר מצינו שבימי משה הי' כל הדור ההוא דור דיעה מבחי' החכמה שבראש וכמ\"ש כל העם קדושים<sup data-n=\"1154\">212</sup> כו' ות\"ר אלף שמש\"ה בקרב\"ו, ודאי גם בחי' זרע בהמה דשם שהוא בעקביי' בחי' נה\"י רק בחי' המעשה כטבעיות אוי\"ר להיות סור מרע כו' בפ\"מ לבד ובלא טעם כלל כנ\"ל שנק' רגל\"י<sup data-n=\"1155\">213</sup>, היו למעלה מראשי אלפי ישראל שבדור האחרון הזה שבבחי' הגדלות דזרע אדם. וא\"כ בימי המשיח שיתעלה למעלה הרבה גם מבחי' החכמה שבראש וכמ\"ש וגבה מאד יוכל להיות שגם בחי' זרע אד\"ם שבגדלות המוחין יהיו אז רק בבחי' זרע בהמה כו' שיצטרכו לבא בבחי' בירור כמו שהבהמה מתבררת עכשיו ע\"י האדם כו', וזהו הנק' בירור אחר בירור דגם פני אדם שנק' מברר עכשיו עתיד לבא בבחי' בירור להיות למזון בבחי' בהמה לבחי' אדם היותר נעלה שיהי' לע\"ל, וזהו בירור אחר בירור דהיינו שהדבר שכבר הוברר ונק' אד\"ם נעשה בבחי' בהמה להתברר ע\"י בחי' אד\"ם העליון יותר וד\"ל.\n<b>וזהו</b> ענין סעודת לויתן ושור הבר שיהי' לע\"ל, דלכאורה זהו דבר פלא ולא מתיישב על הדעת שיהי' בחי' אכילה גשמי' לצדיקים לע\"ל כלויתן ושור",[["1152","210","<b>אדם ובהמה תושיע. . ואני בהמות</b>: ע\"פ תהלים לו, ז. עג, כב."],["1153","211","<b>ותשרנה הפרות</b>: ע\"פ שמואל-א ו, יב."],["1154","212","<b>כל העם קדושי'</b>: ע\"פ קרח טז, ג."],["1155","213","<b>ות\"ר אלף. . רגלי</b>: בהעלותך יא, כא."]]],[1900420266,"הבר הגשמי דודאי יהיו צדיקים דלע\"ל בתכלית ההפשטה מן הגשם לגמרי מכל וכל (עד שאמרו עתידים צדיקים<sup data-n=\"1156\">214</sup> שיאמרו לפניהם קדוש כו' כי גופם לא יהי' חומר גופני כגופים שלנו שנולדו מתאות אב ואם כבהמ' כו' אלא אחר שיחיו המתים מטל העליון דנטיף מע\"י<sup data-n=\"1157\">215</sup> כו' כדוגמא דתחיית המתים דיחזקאל<sup data-n=\"1158\">216</sup> דרוח האלקי בא בעצמות כו'). אך הענין הוא דאכילה הזאת לא תהי' אכילה גשמי' כלל אלא רוחניות וגם יותר רוחני מאכילת אדם העליון לבחי' [פני שור] כו' בהעלאת הקרבן לריח ניחוח כנ\"ל. ויובן זה מאשר מצינו דוגמתו למעלה גם עכשיו והוא מארז\"ל דמיכאל כה\"ר<sup data-n=\"1159\">217</sup> מקריב נשמות ע\"ג המזבח העליון, הרי גם הנשמות בחי' אד\"ם בכלל הקרבה למעלה כקרבן הבהמה ממש משום דעליות הנשמות למקום ומדרגה העליונה שהוא לאשתבאה בגופא דמלכא<sup data-n=\"1160\">218</sup> בעולם עצמות התענוג העליון הרי שם נחשבו לבחי' בהמה ממש (וכמו תפלה במקום קרבן בהמה הרי נפש הבהמיות נק' נפש השכלית בזה העולם להשכיל כל דבר חכמה וגם להשכיל ולהתפעל בגדלות הבורא ועכ\"ז נק' קרבן בהמה ממש לפי שהיא בחומריות התאוה הגשמי' ג\"כ ששרשה מעה\"ד טו\"ר ונברר חלק הרע שבה ע\"י תשובה והטוב שבה עולה כקרבן ע\"ג המזבח לריח ניחוח כו', ויותר מזה העלאת נשמה שנק' זרע בהמה אלקי' הנ\"ל שעולה כקרבן, עד שגם שנשמות שלמעלה מזה הנק' זרע אד\"ם ממש נעשי' בבחי' בהמה ע\"ג המזבח דאצי' דמיכאל כה\"ר ששרשו בחסד דז\"א מקריבן כמו שמקריב הכהן שלמטה ממש כו'). וכך יהי' נשמות דעכשיו בחי' מזון גשמי לנשמות הגבוהות מאד נעלה בערך מהם שיהיו לע\"ל כנ\"ל עד שיצטרכו נשמות דעכשיו לבא בבחי' בירור שני ולכלל בנשמות דלע\"ל כמאכל גשמי (וכקרבן נשמות ע\"ג המזבח כנ\"ל), וא\"כ אכילה זאת ודאי זהו יותר עליון גם מאכילת אדם העליון לבחי' העלא' פני שור דמרכבה הרוחני כו' שהרי נשמות דעכשיו שרשם בפני אדם שבמרכבה כנ\"ל וד\"ל. וזהו ענין סעודת לויתן, דלויתן ושור זה אינם גשמיים ח\"ו אלא כמ\"ש לוית\"ן זה יצרת לשחק בו כמו לוי\"ת חן<sup data-n=\"1161\">219</sup> כו' שהן הנשמות הגבוהות ששרשן בי\"ם הקדמונ\"י שיצאו מן ההעלם העצמות ביחוד או\"א וזו\"נ דאצי' למטה בבי\"ע ונתלבשו בגופי' לקיים תו\"מ, ולוית\"ן זה יצרת לשח\"ק ב\"ו שיבא מזה התעוררות התענוג הפשוט שבעצמות ממש, והן נשמות מבחי' החסדים דעלמא דאתכסיא, וכמ\"כ יש נשמות מבחי' הגבורות העליונות דעולם התוהו, וכללותם הוא הנק' שו\"ר הב\"ר דבחי' התוהו שקדם לאד\"ם",[["1156","214","<b>עתידי' צדיקי'</b>: ב\"ב עד, א."],["1157","215","<b>שיחיו המתים מטל העליון דנטיף מע\"י</b>: ראה זח\"ג קכח, ב. רפח, ב."],["1158","216","<b>דתח\"ה דיחזקאל</b>: יחזקאל לז."],["1159","217","<b>דמיכאל כה\"ר</b>: ראה חגיגה יב, ב (ע\"פ גירסת הע\"י). זבחים סב, א. מנחות קי, א תוד\"ה ומיכאל זח\"א פ, סע\"א. פא, רע\"א. ועוד. ובהנסמן בארוכה בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' א. דברים ח\"א ע' עא."],["1160","218","<b>לאשתאבא בגופא דמלכא</b>: זח\"א ריז, ב. [וראה בהמ\"מ ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' מה, ש\"נ למקומות רבים ע\"ז בדא\"ח]."],["1161","219","<b>לויתן זה יצרת. . לוי\"ת חן</b>: תהלים קד, כו. משלי א, ט. ד, ט."]]],[1900420267,"דתיקון וכידוע בפי' בהמה רב\"ה שלפני האצי'<sup data-n=\"1162\">220</sup> כו', וכל נשמות דעכשיו יתלבשו בלוית\"ן ושור הבר הזה ויבאו בבחי' בירור שני בבחי' הגשמה כמאכל דג ובשר גשמי לאדם התחתון למטה ממש כך יהי' כמו בחי' סעודה גשמית לנשמות העליונות דלע\"ל, וכאשר נשמות הצדיקים דלע\"ל יאכלום יעלו לכל הניצוצות קדושות דעכשיו המלובשים בלויתן ושור הבר ממש כמו שיעלה האדם עכשיו למאכל גשמי כנ\"ל וד\"ל.\n[כג] <b>אך</b> הנה עדיין יש להבין איך יתכן שיהיו ערך הנשמות דלע\"ל גבוהות כ\"כ עד שיהיו נשמות דכל הדורות דאדה\"ר עד ימות המשיח נחשבו לבחי' מזון גשמי כדג ובשר גשמי דלויתן ושור הבר כו'. ואמנם יש להקדים לזה שרש ענין זה דנשמות דלע\"ל מאיזה מקום ומדרגה יבאו כו'. דהנה ידוע שיש ב' מדרגות כלליים בכלל ההשתלשלות. א' השתלשלות דבחי' הקו\"ח שנמשך אחר הצמצום הנק' מק\"פ וחלל ריקן כו' שנמשך עד סוף העולם האחרון הוא עוה\"ז השפל, כידוע דקו\"ח זה בוקע ועובר כל ההשתלשלות מראש עד סוף דהיינו מבחי' א\"ק עד עקב דא\"ק שמסתיים בסוף העשי'<sup data-n=\"1163\">221</sup>, ונמצא מקור דמקור די\"ס דאצי' עד סוף העשי' הכל נכלל בקו\"ח הזה שאחר הצמצום ונק' ממלא כ\"ע בכלל ונק' חי העולמים כולם כו'. אבל למעלה מעלה מבחי' הקו\"ח הזה הנה הוא בחי' העצמות דא\"ס ב\"ה כמו שהוא קודם הצמצום הראשון שלפני הקו כו' ונק' שעשועי המלך בעצמו והי' ממלא כל החלל כו' רק שיער בעצמו בכח מה שיהי' בפועל והן אותיות שבעצמות כמ\"ש בס' עמק המלך<sup data-n=\"1164\">222</sup>, ושם נחצבו גם בחי' נשמות ונק' נשמות חדשו\"ת לגמרי (ואולי זהו שאמר משה ואשר איננו פה<sup data-n=\"1165\">223</sup> לגמרי שלא יבאו בגופים גשמיים כלל רק לע\"ל בימי משיח), והוא למעלה גם מבחי' אור מקיף הכללי דמקיף לאבי\"ע שנק' טהירו כו', ונק' סובב הכללי מאחר שסובב זה מקור לגילוי דקו\"ח הכל א' (וכמ\"ש במ\"א בפי' כי גאה גאה כו' במשל מלך ואגוסטוס<sup data-n=\"1166\">224</sup> כו', וכל ישראל בני מלכי\"ם<sup data-n=\"1167\">225</sup> היינו ישראל שעלה במחשבה בחי' סובב הכללי, אבל נשמות חדשות לגמרי למעלה מהם הרבה והוא בעצמות אא\"ס ששם נחצבו וכמ\"ש ונשמות אני עשיתי<sup data-n=\"1168\">226</sup> ולא באו להשתלשלות כלל וכלל).",[["1162","220","<b>וכידוע בפי' בהמה רבה שלפני האצי'</b>: ראה זח\"א יח, ב. לקו\"ת אמור לו, א."],["1163","221","<b>עקב דא\"ק שמסתיים בסוף העשי'</b>: ראה ע\"ח ש\"א ענף ד'. ש\"ב סוף ענף ב'. ש\"ג פ\"ב. אגה\"ק ס\"כ (תניא קלא, ב). ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' טו. ובכ\"מ."],["1164","222","<b>שיער בעצמו בכח. . בס' עמק המלך</b>: ראה לעיל ד\"ה שמח תשמח (הראשון) אות יא. וש\"נ."],["1165","223","<b>ואשר איננו פה</b>: נצבים כט, יד."],["1166","224","<b>וכמ\"ש במ\"א בפי' כי גאה גאה במשל מלך ואגוסטוס</b>: שמו\"ר ר\"פ כ\"ג. ד\"ה אז ישיר, בסה\"מ תקס\"ה ח\"א ע' רלו. ס' מאמרי אדה\"ז עה\"ת ח\"א ס\"ע רפו."],["1167","225","<b>וכל ישראל בני מלכי'</b>: שבת סז, א."],["1168","226","<b>ונשמות אני עשיתי</b>: ישעי' נז, טז."]]],[1900420268,"<b>והנה</b> ידוע דכל הנשמות דעכשיו הוא מעולם התיקון דאד\"ם שהוא מבחי' א\"א ואו\"א וזו\"נ עד זו\"נ דעשי' כו' ששרש הראשון לכל זה הוא רק בחי' הקו\"ח הנ\"ל שאחר הצמצום דמק\"פ כו', אבל נשמות דלע\"ל יהי' מוצאם מעצמות אא\"ס ממש שלפני הצמצום כו' כנ\"ל שאין ערך בין זה לזה כלל עד שיוכל להיות דנשמות דאו\"א וזו\"נ דעכשיו לא נחשבו רק בערך החי והצומח לגבי האדם למטה, כי באמת הרי אין ערוך כלל לכל ההשתלשלות דקו\"ח הבא בסיבת הצמצום הראשון לגבי העצמות דעולם הא\"ס רק כערך החי וצומח לגבי האדם ויותר אין ערוך כו' שהרי ידוע דבחי' א\"ק נק' אדם דבריאה<sup data-n=\"1169\">227</sup> וכל בריאה היא יש מאין שהוא בבחי' מיעוט הערך נבדלת לגמרי לגבי הערך של הבורא יותר מהבדל הערך מן הדומם וצומח אל ערך האדם כו' וד\"ל. ולפי כל זה יובן ולא יפלא כלל וכלל על היות הנשמות דעכשיו ששרשן מיחוד או\"א וזו\"נ עד שרשן בא\"ק כו' הכל לא יהי' לע\"ל רק בבחי' מאכל גשמי, והוא הלוית\"ן ששרשו באו\"א שיחוד עליון דאו\"א נק' לויתן כמ\"ש במ\"א<sup data-n=\"1170\">228</sup>.\n<b>(ויובן</b> זה בתוס' ביאור עפ\"י המבואר במ\"א (ונדפס בסידור בענין כוס של ברכה דדוד שאמר לי נאה לברך<sup data-n=\"1171\">229</sup> על יין המשומר בסעודת לויתן דלע\"ל) שיש ב' מדרגות בעונג האלקי הא' נק' עונג הנעלם בלתי מורכב כלל וכלל כו' והב' עונג מורגש ומורכב בדבר מה כו', ויש בזה עילוי המדרגות זה למעלה מזה עד שעונג הנעלם שבזה העולם לא יהי' גם בבחי' עונג מורגש בעולם העליון יותר וכעונג הנעלם שבג\"ע התחתון, מורגש וגשמי יקרא בג\"ע העליון כו', וזהו והי' מדי חדש כו' שעולין בעמוד<sup data-n=\"1172\">230</sup> לפי שצריך לבטל ולשכוח על עונג הרוחני שבג\"ע העליון כו', כך כל מה שנחשב עונג רוחני למטה יחשב עונג גשמי למעלה (ולהיפך יכול להיות שעונג העליון הרוחני יכול לבא בהגשמה למטה, כמזון המן שנק' מזונא דחכמת'<sup data-n=\"1173\">231</sup> רוחני ולמטה בא בהגשמה ממש, וכן הטל שיחי' המתים יבא בהגשמה, וא\"כ עכ\"פ יוכל להיות מרוחני גשמי ע\"כ יוכל להיות שמעונג הרוחני שבנשמות דעכשיו בג\"ע או בהשגה אלקי' בהתענגם על ה' ועושין בתפלה ובק\"ש ביחודים עליונים דאו\"א כו' יהיו לע\"ל בבחי' עונג גשמי שזהו הלוית\"ן לגבי נשמות חדשות לגמרי ששרשם בעצמות השעשועים העליונים שהוא נבדל בערך הרבה כנ\"ל).",[["1169","227","<b>ידוע דבחי' א\"ק נק' אדם דבריאה</b>: ע\"ח ש\"א ענף ד. ובכ\"מ. וראה בארוכה בס' מאמרי אדה\"ז על ענינים בתחילתו. לקו\"ת צו ח, ד. ובהמ\"מ שם."],["1170","228","<b>שיחוד עליון דאו\"א נק' לויתן כמ\"ש במ\"א</b>: ראה זח\"ב נ, ב. פרדס שער ערה\"כ בערך לויתן. סידור קד, ד ואילך. אוה\"ת שמיני ע' תפה ואילך. עקב ע' תקמד ואילך [הגהות על הסידור]. יהל אור ע' תה ואילך."],["1171","229","<b>המבואר במ\"א (ונדפס בסידור. . לי נאה לברך</b>: פסחים קיט, ב. סידור דף קב, ב ואילך. [ומקבילו בס' מאמרי אדה\"ז על מארז\"ל ע' פא]."],["1172","230","<b>והי' מדי חדש שעולין בעמוד</b>: ישעי' סו, כג. זח\"א ריט, א וזח\"ב ריא, א."],["1173","231","<b>שנק' מזונא דחכמת'</b>: זח\"ב סב, א."]]],[1900420269,"<b>וזהו</b> ואכלתם אכול כו', פי' אכול ל' נפעל כלומר מאכל שכבר נאכל פעם א' תאכלוהו עוד הפעם. והענין הוא דבר שכבר מבורר יתברר פעם שני' (ובל\"א איין מאכל וואש מי האט גיגעשין כו'), והוא ענין בירור אחר בירור הנ\"ל בנשמות דעכשיו. כי הנה ידוע דהאכילה נק' בירור ועכשיו נתברר בחי' מאכל דשור ע\"י אדם שיוכלל בבחי' פני אדם וה\"ז כמבורר ועומד ונק' מאכל שנאכל ונברר, ולע\"ל יבאו נשמות שמבחי' פני אדם שכבר הן בבחי' הבירור להתברר בירור שני והוא שיחשבו כמאכל שור וכסעודת לויתן ושור הבר הנ\"ל ליכלל בנשמות הגבוהות שמבחי' עצמות אא\"ס כנ\"ל, וזהו ואכלתם לעתיד בסעודת לויתן דבר שכבר אכול והן נשמות דעכשיו שנעשי' אז בבחי' בהמה כנ\"ל להעלותם למעלה מעלה שהוא במדרגת הנשמות החדשות שהן כלולי' בעצמות המאציל ויהיו גם הם כמותם, כמו שמן מאכל בהמה דשור דעכשיו נכלל בבחי' אדם ונעשה מבהמה אדם וכמו פני שור שבטל ונכלל בפני אדם כנ\"ל (ואין זה מובן לפי פשט הכתוב דואכלתם לא קאי על נשמות החדשות שעתידים לבא אז אלא על נשמות שבאו כבר בעוה\"ז שיאכלו וישבעו ויתענגו על ה' בסעודת לויתן ושור הבר כו', וגם סיפא דקרא מכריח כן שא' והללתם את שם ה' אלקיכם כו' שזהו הכל בנש\"י שעסקו בעוה\"ז בתו\"מ שנק' נשמות צדיקים, וכן מפורש בגמ' שעתיד ה' לעשות סעודה לצדיקים מלויתן כו' ואברהם כו' עד שדוד א' לי נאה לברך כו', הרי כל נשמות שכבר היו בזה העולם כאבות ומשה ואהרן ודוד כו' יאכלו מן הלויתן כו', אלא ואכלתם קאי על נשמות דעכשיו ועכ\"ז גם זה אמת דלויתן זה הוא ברוחניות כלולי' בו כל רוחניות עונג הנשמות דעכשיו יהי' אז במורגש עד שיהי' אז להם בבחי' מזון גשמי כי יתעלו נשמות דעכשיו במדרג' נשמות החדשות ויהיו להם לעונג גשמי ומורגש כל אשר התענגו בתפלה ותו\"מ בעוה\"ז כו'). וזהו והללתם את שם ה' אלקיכם אשר עשה עמכם להפליא, פי' כנ\"ל דנשמות דעכשיו יתעלו להיות בבחי' אד\"ם דנשמות חדשות הנ\"ל, וזהו שעשה עמכם להפליא הפלא ופלא מקור הפלא שהוא בעצמות המאציל שנק' סתימו דכל סתימין כו' שהוא עושה כל פלא כו' וד\"ל.\n[כד] <b>ואחר</b> כל הנ\"ל יובן ענין קול כלה דלע\"ל שלמעלה מן החתן ונק' קול גדול כנ\"ל. דהנה באמת אין זה מובן למה יהי' לע\"ל נשמות גבוהות כאלה עד שנשמות דעכשיו מבחי' פני אדם יהי' אז בבחי' בהמה כנ\"ל. ויש להקדים לזה ענין אחד והוא בבחי' הקול שהוא בחי' ההמשכה מן ההעלם לגילוי וזהו עיקר ענינו בקול היוצא מן הגרון שנשמע במורגש ויוצא מתוך ההעלם כו'. אך הנה יש ב' מדרגות בקול זה שיוצא מהעלם לגילוי א' כשיוצא ונמשך מלמעלה למטה שנק' אור ישר, והב' כאשר בא מן ההעלם לגילוי מלמטה למעלה כקול היוצא מהבל הלב שעולה והולך מלמטה למעלה עד הגרון כמים הבוקעי' ועולין מלמטה למעלה כו' והוא הנק' בחי' אור חוזר כידוע, וב' מיני קול אלה שניהם הן מן ההעלם לגילוי רק שזה מלמעלה למטה"],[1900420270,"וזה מלמטה למעלה. והנה ההפרש בין בחי' או\"י לאו\"ח ידוע שאו\"י הולך ונמשך למטה מטה וכל שהולך ונמשך למטה מתמעט כחו עד שמסתיים, אבל בחי' או\"ח שעולה והולך מלמטה למעלה כל שעולה יותר בגובה יותר יתגבר ויעלה עד אין שיעור למעלה עד שחוזר לקדמותו ממש כו'. והענין יובן בב' מיני קול הנ\"ל בהפרש בין נשמות דעכשיו לנשמות שלע\"ל (והן נשמות דעכשיו רק שיתעלו כנ\"ל). דהנה נשמות דעכשיו שרשן בבחי' מל' כמו שמקבלת מז\"א שהוא המשפיע ומוליד נשמות כו' ונק' אור זרוע לצדיק כו', והכל הוא בבחי' אור ישר שהולך מלמעלה למטה מההעלם לגילוי, והוא הנק' קול יעקב כו', וזהו קול היוצא מלמעלה למטה (וע\"כ אין לכלה קול עכשיו ובשתיקה מתקדשת כנ\"ל לפי שבטילה וטפילה לגבי המשפיע בחי' ז\"א שהוא בחי' או\"י כידוע). אבל לע\"ל דאשת חיל עט\"ב שיהי' עליית המל' בפנימי' ועצמות אא\"ס שקודם הצמצום הראשון כנ\"ל ותשפיע לבעלה כנ\"ל ה\"ז משום דסוף מעשה עלה במחשבה תחילה ונעוץ סופן בתחלתן, שזהו הנק' בחי' אור חוזר והוא הנק' קול העולה מלמטה למעלה מההעלם שלמטה לגילוי והולך ועולה עד אין שיעור למעלה מעלה עד שחוזר לקדמותו ממש כנ\"ל והיינו בעצמות אא\"ס שנק' קדמון לכל הקדומים<sup data-n=\"1174\">232</sup> כו' והיינו מ\"ש יצאו מ\"ח מירושלים<sup data-n=\"1175\">233</sup> כו'. וזהו שיהי' לע\"ל נשמות חדשות שבבחי' עצמות המאציל ממש לפי שבחי' או\"ח דמל' שחזר לקדמות העצמות ממש ממשיך משם אורות עליונים הגנוזים בהעלם העצמות בעילוי אחר עילוי שאין ערך לנשמות דאו\"י להם עד שיחשבו אז רק כמו בהמה לגבי אדם כנ\"ל (ובאמת הרי כל בחי' או\"ח דמל' שהוא כנ\"י עולה בהעלא' הברורים דרפ\"ח כו' דהיינו בתו\"מ של נשמות דעכשיו שעסקו בעוה\"ז דוקא שזהו סוף מעשה כו' כידוע, א\"כ מובן דגם נשמות דעכשיו מבחי' ז\"א בחי' או\"י אבל הן עצמן יתעלו ע\"י תו\"מ שלהם שנק' סוף מעשה לבחי' העצמות ממש שהן נשמות החדשות ויהיו במדרגתם ממש והסעודה דלויתן לפניהם יהי' כנ\"ל דקאי ואכלתם על נשמות דעכשיו דוקא ויאכלו הם עצמם מאשר כבר נברר על ידיהם בחי' אד\"ם שהוא או\"י בבחי' בירור שני מצד בחי' או\"ח שלהם וד\"ל).\n<b>וזהו</b> בחי' קול כלה דלע\"ל שנק' קול גדול ולא יסף מפני שהוא בבחי' או\"ח עד לקדמותו ששם הוא גדול בבחי' גדלות הא\"ס ממש וד\"ל. משא\"כ עכשיו אין לכלה קול כלל מפני שמקבלת מבעלה כו' וכנ\"ל בענין צלותא דבלחש כו', וע\"ז א' הכלה הופכת פניה<sup data-n=\"1176\">234</sup> מפני הבושה מן החתן וכרבקה שנפלה מעל הגמל בראותה את יצחק משום דבחי' מקבל מתבייש מפני המשפיע",[["1174","232","<b>שנק' קדמון לכל הקדומים</b>: תקוני זהר תי\"ט (מב, א). ובכ\"מ."],["1175","233","<b>יצאו מ\"ח מירושלים</b>: זכרי' יד, ח."],["1176","234","<b>הכלה הופכת פניה</b>: פסחים פו, א."]]],[1900420271,"מאחר דלית לה מגרמה כלום רק שמצפה לשפע המשפיע וא' בזוהר דמאן דאכיל לאו דילי' באיש<sup data-n=\"1177\">235</sup> לאסתכלא באנפוהי כו', ע\"כ הכלה הופכ\"ת פני\"ה. והיפך זה ממש יהי' לע\"ל שנא' ואכלתם אכול ושבוע פי' שהמל' שרש כנ\"י תעלה למעלה כ\"כ כנ\"ל ותהי' בבחי' התפשטות קול גדול היפך השתיקה כנ\"ל וע\"כ תאכ\"ל ותשב\"ע מדבר שכבר ברור ועומד והוא בחי' הברורים דרפ\"ח כו' שכבר ביררו צדיקים שהן מפני אד\"ם דז\"א שזהו ענין סעודת לויתן כו' כנ\"ל וד\"ל. וזהו והללתם את שם ה' כו', דעכשיו א' ואכלת ושבעת וברכ\"ת<sup data-n=\"1178\">236</sup> ברכה היא בבחי' או\"י דפני אדם להמשיך מלמעלה למטה דוקא, אבל באכילה דלע\"ל שהוא בירור שני מצד בחי' או\"ח שעולה מלמטה למעלה דוקא כנ\"ל בענין קול הב' שעולה מלמטה למעלה כו' ע\"כ אמר והללתם דהלל הוא בקול העולה כו' והיינו והללתם שיעלו לשם הוי' אלקיכם בהלל זה בעצמות ממש, והיינו אשר עשה עמכ\"ם ממש שהן נשמות דאו\"י להפליא הפל\"א ופל\"א שהוא בחי' העילוי אחר עילוי דבחי' או\"ח לקדמותו עד בחי' עצמות שעשועי המלך כו' שאין בחי' או\"י גם בשרשו בפלא שהוא אור הכת\"ר וגם לא מקור הפלא מגיע לשם דלית מחשבה תפיס' שם כלל אפי' מחשבה דא\"ק<sup data-n=\"1179\">237</sup> כו' מאחר שנק' אד\"ם כו', וזהו וגבה מא\"ד דמשיח וד\"ל.\n[כה] <b>והנה</b> יש להבין בתוס' ביאור ענין קול מצהלות חתנים מחופתן כו' הנ\"ל שהן שנים והן ב' מיני כבוד וכמ\"ש כי על כל כבוד חופה<sup data-n=\"1180\">238</sup> כנ\"ל, ויבואר פסוק זה באופן אחר. ותחלה יש לדקדק בו במ\"ש כי על כ\"ל כבו\"ד כו' הל\"ל על כבוד מהו על כל כבוד כו'. ועוד בעיקר הענין יש להבין דלכאורה תרי קראי דסתרי אהדדי, דפעמים א' מלא כל הארץ כבודו<sup data-n=\"1181\">239</sup> ולפעמים א' ברוך כבוד ה' ממקומ\"ו, פי' ממקומו העצמי הנעלם שנק' סתימא דכל סתימין דלית מחשבה תפיסא בי' משם יומשך ויתברך כבודו, ואיך א' גם בכל הארץ כבודו כו' דזה משמע דכבודו בא בגילוי גמור בכל העולם כו', וגם במה שמבקשים ברוך כבוד ה' משמע שאינו מתגלה כבוד ה' רק לפרקים כמו בג' רגלים אלה מועדי הוי' ובשבת וכה\"ג וגם המלאכים אומרים איה מקום כבודו כו'. והנה לתרץ סתירה זו יש להקדים הידוע שיש ב' מדרגות ממלא כל עלמין וסובב כל עלמין, ומ\"ש מלא כל הארץ כבודו כבודו זיו יקרי' היינו בחי' ממלא כל עלמין שזהו רק מבחי' הזיו והאור האלקי שאינו ממהותו ועצמותו רק בחי'",[["1177","235","<b>בזוהר דמאן דאכיל לאו דילי' באיש</b>: ראה לקו\"ת צו ז, ד — מירושלמי ערלה פ\"א ה\"ג: סימנא דאכיל מן חברי' בהית (פי' מתבייש) מסתכלא בי'."],["1178","236","<b>ואכלת ושבעת וברכת</b>: עקב ח, יו\"ד."],["1179","237","<b>דלית מחשב'. . אפי' מחשבה דא\"ק</b>: ראה לעיל ד\"ה שמח תשמח (הראשון) אות ט. וש\"נ."],["1180","238","<b>[כה] והנה יש להבין כו'. . על כל כבוד חופה</b>: ישעי' ד, ה. מכאן (עד אות לא) מיוסד על ד\"ה כי על כל כבוד בסידור קכח, ד. ולעיל ח\"א בתחילתו. וש\"נ. בכת\"י אחד (מעתיק) מתחיל מכאן כמאמר חדש: כי על כל כבוד חופה להבין מ\"ש על כל כבוד הל\"ל על כבוד."],["1181","239","<b>מלא כל הארץ כבודו</b>: ישעי' ו, ג."]]],[1900420272,"התפשטותו ע\"י צמצום אור עצמותו כמ\"ש באורך נרא\"ה אור<sup data-n=\"1182\">240</sup> וכידוע משום שאין ערך כלל לנברא בע\"ג עם בלתי בעל גבול כו' ואם הי' האור והשפע אלקי' מעצם מהותו איך יתהווה בע\"ג אלא הי' גם הם בלתי בע\"ג, ע\"כ הוצרך להיות השפע ע\"י צמצום והעלם עצמות אורו כידוע וד\"ל (ומ\"ש את השמים ואת הארץ ר\"ת אהו\"ה גימטריא טוב<sup data-n=\"1183\">241</sup> היינו בחי' סובב כ\"ע ואני מלא אין זה בגילוי רק בהעלם, ואע\"פ שא' בזוהר דלית אתר פנוי מיני' גם זה בהעלם ולא בגילוי כמ\"ש במ\"א<sup data-n=\"1184\">242</sup>), ומ\"ש ברוך כבוד ה' ממקומו העצמי שבהעלם העצמות דא\"ס כו' היינו מבחי' סובב כ\"ע הכללי (שלפני הצמצום דקו\"ח הנק' מק\"פ כו'), והיינו בחי' מהותו ועצמותו דלית מחשבה תפיסא בי' כו', ואין ב' המקראות סותרים זא\"ז כלל, דהיינו ב' מיני כבוד הנ\"ל, כבוד עליון הוא כבוד ה' שבבחי' סובב הכללי ונק' כבוד הוי' כבוד נאצל דהיינו כל בנין עולם הנאצל ויתברך ממקומו הנעלם לפרקים כי נק' סתימא דכל סתימין כו' ואינו בא בגילוי רק לפרקים כמו בג' רגלים ושבת וכה\"ג כנ\"ל, אבל כבוד הב' דמלא כל הארץ כבודו הוא בבחי' ממלא כ\"ע שהוא בחי' הזיו הנק' זיו יקרי' דתמיד הוא בגילוי בכל העולמות עד סוף העוה\"ז השפל וע\"כ כולם אומרים שירה כו' ונק' כבוד נברא וכמ\"ש למען יזמרך כבוד כו' (וזהו כבוד אלקים הסתר דבר<sup data-n=\"1185\">243</sup> כבוד עליון הנ\"ל וכבוד מלכים חקור דבר כבוד תחתון כו').\n[כו] <b>והנה</b> להבין זה בתוס' ביאור יש להקדים ענין אחד המבואר במ\"א בפי' כי אל דיעות ה' ב' דיעות הפכיים מן הקצה לקצה והכל בדיעה אלקי', א' מלמעלה למטה שהוא מיש לאין והב' מלמטה למעלה וזהו מאין ליש, והן ב' דיעות סותרות דשפע מיש לאין עם שפע מאין ליש הב' הפכי' הן. וביאור הענין ידוע (ומבואר היטב בסידור הנדפס<sup data-n=\"1186\">244</sup>) שזהו דרך פרט ודרך כלל, דרך הפרט הוא בבחי' מל' דאצי' עצמה ששפע האלקי באה מאי\"ן ליש שנק' כח הפועל בנפעל כידוע הרי בחי' כח האלקי מוסתר בנפעל ונברא ונק' אי\"ן והעלם לגביהם ולא נגלה רק בחי' היש דנברא, וכמ\"ש במ\"א בענין שרפים עומדים ממעל ל\"ו ממעל לשכינתא<sup data-n=\"1187\">245</sup> כו', כחיי הנפש בגוף שלא נראה מהות החיות הרוחני שבגוף רק הגוף חי כו', והב' מי\"ש לאי\"ן במל' עצמה והוא",[["1182","240","<b>באורך נראה אור</b>: תהלים לו, יו\"ד."],["1183","241","<b>את השמים. . ר\"ת אהו\"ה גי' טוב</b>: ראה לעיל ד\"ה שמח תשמח (הראשון) אות ג. וש\"נ."],["1184","242","<b>בזוהר דלית אתר פנוי. . כמ\"ש במ\"א</b>: תקוני זהר תנ\"ז (צא, ב). ת\"ע (קכב, ב). וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשצא."],["1185","243","<b>למען יזמרך כבוד. . כבוד אלקי' הסתר דבר</b>: תהלים ל, יג. משלי כה, ב."],["1186","244","<b>במ\"א בפי' כי א-ל דיעות. . ומבואר היטב בסידור הנדפס</b>: ראה סידור ד\"ה מזמור לתודה (מד, א ואילך) ומקבילו בס' פירוש המלות לכ\"ק אדהאמ\"צ (פקל\"ח ואילך). סידור שם ד\"ה כי על כל כבוד חופה (קכט, א ואילך) ומקבילו לעיל ח\"א ע' ד ואילך. [ונסמן עוד בענין זה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רסב]."],["1187","245","<b>במ\"א בענין שרפים. . ממעל לשכינתא</b>: ישעי' ו, ב. ראה סה\"מ תקס\"ח ע' רטז וע' שלא. ובכ\"מ."]]],[1900420273,"בהיפך משפע הנ\"ל שזהו אור ושפע הנמשך מבחי' מל' שיהי' מקור ושרש לנבראים דאור וזיו זה רק הארה חיצוניות שבעצם מהותו זהו הנק' מי\"ש לאי\"ן, ופי' אי\"ן זה כמו כאי\"ן ואפס דכלא ממש חשיב לגבי העצם ופירושו מי\"ש האמיתי לאי\"ן זה דכלא חשיב כו', וזהו כמו דמיון אור חיי הנפש הרוחניות טרם בואה להחיות הגוף שיש בכחה להחיות גופים רבים שזהו הנק' בחי' אורה וזיווה לבד (ככח תנועת המניע וכמ\"ש במ\"א<sup data-n=\"1188\">246</sup>) וכמו כן בחי' הצמיחה מכח הצומח בעצם טרם שבא בפועל הצמיחה בגשם העשב והתבואה כו', זהו דמיון להבין ענין מי\"ש לאי\"ן, דודאי כלא חשיב כל מה שיש בכח הנפש החיונית להחיות דבר זולתה לגבי מהותה ועצמותה שאינה בגדר חיות להחיות, וכמ\"כ בכח הצומח דכלא חשיב כל מה שיש בכחו להתפשט בצמיחה בפועל לגבי עצמו ומהותו כו'. והנה מה שנמשך מחיי הנפש הרוחניות בגוף ונשתנה מהותו להיות חיי הבשר בדם הוא הנפש וכן בצומח מכח הצומח זהו ממוצע שמחבר ב' ההפכי' כאלה, שהרי מי\"ש לאין הוא רוחני מרוחניות חיי העצם דנפש והאור והשפע חיוני דנפש בבשר ודם שנק' מאין ליש הוא בא בשינוי המהות לגמרי ואיך יחובר מן הרוחני אל הגשם אם לא ע\"י אמצעי, וכך בצמיחה בפועל מכח הצומח הרוחני, אלא ודאי שאמצעי זה למעלה משניהם, והוא מה שאנו רואים שאין שיעור לצמיחה בפועל ואין שיעור לחיי הגוף עד אשר יחלש כח האמצעי והוא הדם שבו הנפש לחבר רוחניות בגשמיות תמיד וא\"ל הי' נפסק כו'.\n<b>והדוגמא</b> מזה יובן למעלה בב' מיני דיעות, א' מיש לאין הוא מעצמות ומהות מדת המל' שמאיר אור וזיו לבד דכלא חשיב לגבי עצמות אלקות, והב' שפע האלקי מאי\"ן ליש שזהו כדמיון חיי הנפש שבא בשינוי המהות בגוף שלא נראה לעין כנ\"ל, וזהו כי עמך מקור חיים<sup data-n=\"1189\">247</sup> באור\"ך העצמי (שזהו כח החיות שבנפש להחיות כמה גופים, וכמו כח תנועת המניע שבחי כו') נראה אור בשינוי המהות וכמרז\"ל מה הנשמה ממלא<sup data-n=\"1190\">248</sup> כו' ונק' כח הפועל בנפעל כנ\"ל שנק' מאי\"ן ליש. ואמנם ודאי בחי' האמצעי המחבר ב' הפכים למעלה משניהם כנ\"ל, ולמעלה היינו למעלה מבחי' ממלא וסובב שבמל' עצמה כו'. וז\"ש כי ה' הוא האלקים בחי' האמצעי זהו הו\"א שמחבר ה' ואלקים וממלא וסובב כמ\"ש בזוהר כי הו\"א ל' נסתר כו', והכונה דהוי' ואלקים כולא חד<sup data-n=\"1191\">249</sup>, וכמו שנראה ומובן במשל חיי הנפש בגוף דבחי' הרוחניות שנק' אור וחיות הנפש",[["1188","246","<b>ככח תנועת המניע וכמ\"ש במ\"א</b>: ראה ס' מאמרי אדה\"ז ענינים ע' עז. מאמרי אדה\"ז מארז\"ל ע' צח. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' תב."],["1189","247","<b>כי עמך מקו\"ח</b>: תהלים לו, יו\"ד."],["1190","248","<b>מה הנשמה ממלא</b>: ראה ברכות י, א. ובהנסמן עוד לעיל אות ה."],["1191","249","<b>כי ה' הוא האלקים. . כולא חד</b>: ואתחנן ד, לה. לט. ראה זח\"א יב, א-ב. זח\"ב קסא, א-ב. זח\"ג קמג, א. רסד, א."]]],[1900420274,"להחיות עם חיי הגוף הגשמיי' מתאחד כא' ממש, וראי' מן הצער ועונג שבנפש הרוחניות הוא עצמו הצער ועונג דנפש בגוף בגשמיות שהרי מן הצער הגשמי יתהווה גרעון באור עצם הנפש ומן העונג גשמי יתרבה אור עצם הנפש הרוחניות כמו השמחה ובשורה טובה דכתיב ותחי רוח יעקב<sup data-n=\"1192\">250</sup> ולהיפך כו'. וכך יובן כל ענין התפעלות אלקות ממעשה התחתונים אם לטוב ישמח ה' במעשיו כו' ולהיפך כמו בדור המבול כתיב ויתעצב אל לבו כו' וכה\"ג, ובאמת אין ערוך כלל [גבול] ונבראים לבלתי בע\"ג עד שנאמר ולא נתכנו כו' וכן אם צדקת<sup data-n=\"1193\">251</sup> כו', דשניהם אמת כפי המובן ממשלים הנ\"ל וד\"ל.\n[כז] <b>והנה</b> כמ\"כ הוא דרך כלל מעצמות המאציל לנאצלים יש ב' מיני דיעות הללו ההפכיים, שהרי ע\"ס דאצי' כמו שלהבת הקשורה בהעלם בגחלת שנק' אור בהעלם (כחיות הנפש טרם שיחי' הגוף) דכלא חשיב לגבי עצמות המאציל וזו מי\"ש האמיתי לאי\"ן כנ\"ל, והב' מאין ליש היינו כאשר כבר מאיר אור המאציל בכל ספי' וספי' כמו בחו\"ב וחו\"ג כו' שזהו כדמיון אור חיי הנפש באיברי הגוף וכמו חכמה מוחא חסד דרועא<sup data-n=\"1194\">252</sup> בחי' או\"כ כו' כידוע (וזהו כשלהבת שיוצא אור בגילוי מן הגחלת) ונק' אי\"ן בהעלם לגבי אורות הנאצלים שנק' יש ודבר מ\"ה, וכמ\"ש בס\"י ע\"ס בלי מ\"ה<sup data-n=\"1195\">253</sup> היינו כמו שהן כלא חשיב לגבי העצמות כו' וד\"ל. וגם בכאן יש בהכרח בחי' אמצעי כמו דהו\"א המחבר ה' ואלקים מאצי' לבי\"ע כנ\"ל, ונמצא אל דיעות ה' ב' דיעות הפכיים והן מתחברים כאחד ממש כנ\"ל דרך פרט ישנו בין מאצי' לבריאה ובין מעצמות המאציל לנאצלים, ומ\"ש אל דיעות שסובל כל הדיעות לפי שהוא למעלה מכל בחי' האור והזיו שנמשך בקו\"ח להשתלשלות העולמות דאבי\"ע, וזהו דרך כלל בכללות ההשתלשלות שבחי' הקו\"ח נק' ממלא כללי ובחי' עצמות אא\"ס שלפני הצמצום נק' סובב הכללי (ומה שנק' סובב כללי גם הוא בבחי' השפעה רק שהוא בבחי' אור העצמות עדיין קודם שמצמצם א\"ע (והוא חיי הרוחניי' שבנפש וכשבאה להתפשט בגוף זהו כחיו' הגוף, וזהו פי' מלך יחיד חי העולמים או יחיד חי העולמים מלך, והכל א' דחי העולמים בכלל הוא הקו\"ח וחיי החיים הוא סובב הכללי נק' מלך מרומם לבד מתנשא מימות עולם, ואמנם אין זה ההתנשאות רק לגבי ימות עולם שהוא הקו\"ח שמרומם מהם אבל בחי' מל' דא\"ס שבעצמות הוא מצד התנשאות עצמותו שלמעלה הרבה מהתנשאות על עולם כו' נק' מלך יחיד כו' ומלך מרומם היינו חי העולמים מלך).\n<b>והנה</b> עפ\"י כל זה יובן ב' מיני כבוד הנ\"ל כבוד עליון וכבוד תחתון שישנם בשני המדרגות, א' בין אור המאציל עצמו לאורו בנאצלים שמי\"ש לאין",[["1192","250","<b>ותחי רוח יעקב</b>: ויגש מה, כז."],["1193","251","<b>ויתעצב אל לבו. . ולא נתכנו. . אם צדקת</b>: בראשית ו, ו. שמואל-א ב, ג. איוב לה, ז."],["1194","252","<b>חכ' מוחא חסד דרועא</b>: תקוני זהר בהקדמה ד\"ה פתח אליהו."],["1195","253","<b>בס\"י ע\"ס בלי מ\"ה</b>: פ\"א מ\"ב ואילך."]]],[1900420275,"דכלא חשיב לגבי העצמות נק' כבוד עליון ומה שהוא מתפשט בע\"ס דאצי' שזהו מאין ליש נק' כבוד תחתון, וכמ\"כ מאצי' לבריאה מה שמאור\"ך העצמי נמשך להיות מקור לבי\"ע נק' כבוד עליון ונק' כבוד הוי' דמל' דאצי' עצמו ומה שנמשך לבי\"ע להיות כח הפועל בנפעל שנק' מאי\"ן ליש זהו הנק' כבו\"ד תחתון וכן נא' למען יזמרך כבו\"ד שעולה בהעלאת מ\"ן כידוע וד\"ל (ובאמת אין ב' הדיעות הפכיים רק שדיעה זו מלמעלה למטה ודיעה זו מלמטה למעלה, דמן המשפיע אל המקבל מלמעלה למטה זהו מיש לאין ומן המקבל אל המשפיע מלמטה למעלה זהו מאין ליש ושניהם כא' ואינם סותרים זא\"ז כלל כמובן ממשלים הנ\"ל. ועוד יובן ממשל גשמי הידוע מן התהום שבוקע מעיינות והמעיינות הולכים בנחלים שהתהום נק' יש בעצם והנביעות מן התהום במעיינות שבארץ כלא חשיב ומן המעיינות לנחלים נק' מקור אך הוא בהעלם כו', ונמצא האין די\"ש בעצם דתהום הוא אין של היש המוגבל שהוא בנהרות ונחלק לב' מדרגות לבד אבל הוא א', וכמו תלמיד לפני רבו דטריד למיבלע וכלא חשיב כו' ומזה עצמו נעשה בחי' משפיע שזהו מאי\"ן ליש מוגבל כו', וכמ\"כ אור הלבנה מאור וזיו השמש וכידוע, וכמ\"כ ענין נקודה קו שטח<sup data-n=\"1196\">254</sup> דהצמצום דנקודה וקו<sup data-n=\"1197\">255</sup>* זהו בבחי' אין של היש בעצם שהוא שטח בלתי מוגבל והשטח מוגבל בא מן הנקודה וקו וד\"ל). וה\"ז עולה בסגנון אחד עם ב' משלים הנ\"ל דחיי הנפש בגוף וכח הצומח בצמיחה דזיו העצם של הנפש אין דיש בעצם נעשה אי\"ן לי\"ש כו').\n[כח] <b>והנה</b> מעתה יש להבין ענין כי על כל כבוד חופה, דהנה ב' מיני דיעות הנ\"ל שהן ב' מיני כבוד כנ\"ל הנה הוא ענין חתן וכלה, כידוע דחתן חות דרגא הוא בחי' הדיעה דמשפיע מיש לאין מלמעלה למטה, והוא בחי' החסדים שיורד מגבוה לנמוך שזהו בחי' ההמשכה וירידה מעצמות שנק' יש האמיתי בלתי בעל גבול להאיר אור וזיו הנק' כבוד נאצל כנ\"ל דכלא וכאין חשיב לגבי העצמות כנ\"ל, וזהו בחי' כבוד העליון דבחי' חתן העליון שטבעו ומהותו בבחי' החסדים דאור ישר שיורד מגבוה לנמוך כו', ובחי' כבוד התחתון שהוא דיעה הב' שמלמטה למעלה מאין ליש כנ\"ל שהוא מן המקבל אל המשפיע הוא בחי' הכלה שהיא בבחי' אור חוזר העולה מלמטה למעלה, כידוע בענין כלה ל' כליון כמו כלתה נפשי<sup data-n=\"1198\">256</sup> כו' להסתלק וליכלל למעלה וכמ\"ש למען יזמרך כבוד ולא ידום שהוא כבוד תחתון דוקא (והוא בחי' כח הפועל בנפעל הנ\"ל, כמשל חיי הנפש בגוף שהנשימה דרוח חיים עולה תמיד בבחי' רצוא ושוב ומזה התהוות קיומו כו', וכך החיות האלקי שמלובש בעולמות",[["1196","254","<b>נקוד' קו שטח</b>: ראה לעיל ח\"א ע' קכו (וע' קפו). וש\"נ."],["1197","255","<b>וקו</b>: תיבה זו אינה ברורה בגוכי\"ק."],["1198","256","<b>כלתה נפשי</b>: תהילים פד, ג."]]]]});
